insert into public.web_recipes (id, title, cuisine, source, url, minutes, servings, technique, prep, precision_level, step_count, score, key_canon, data) values
('www-budgetbytes-com-chili-cheese-beef-n-mac', 'One Pot Chili Mac', 'American', 'Budget Bytes', 'https://www.budgetbytes.com/chili-cheese-beef-n-mac/', 35, 6, 2, 1, 2, 12, 40, array['beef', 'pasta', 'cheddar', 'onion', 'garlic', 'tomatoes', 'broth']::text[], '{"title":"One Pot Chili Mac","cuisine":"American","source":"Budget Bytes","url":"https://www.budgetbytes.com/chili-cheese-beef-n-mac/","minutes":35,"servings":6,"key":["Ground beef","Macaroni","Cheddar","Onion","Garlic","Tomato sauce","Beef broth"],"minor":["Chili powder","Smoked paprika","Garlic powder","Oregano","Flour"],"amounts":{"Ground beef":"1 lb","Macaroni":"1/2 lb (about 2 cups)","Cheddar":"1 cup shredded","Onion":"1 yellow","Garlic":"2 cloves","Tomato sauce":"8 oz","Beef broth":"3 cups"},"steps":[["On a clean cutting board, dice [[1]] yellow onion and mince [[2 cloves]] garlic.",null],["Add [[1 tbsp]] olive oil to a large deep skillet or Dutch oven, then add the onion and garlic. Sauté over medium heat until the onions are soft and translucent, about 5 minutes.",5],["Add [[1 lb]] ground beef to the same skillet. Keep stirring and cooking until the beef is cooked through. If your beef is on the fattier side, carefully drain off the extra fat now.",null],["Sprinkle [[2 tbsp]] flour, [[1 tbsp]] chili powder, [[0.5 tsp]] smoked paprika, [[0.5 tsp]] garlic powder and [[0.5 tsp]] dried oregano into the skillet with the beef and onions.",null],["Cook and stir for about two minutes, letting the flour and spices coat the bottom of the skillet without burning.",2],["Pour [[8 oz]] tomato sauce and [[3 cups]] beef broth into the skillet. Stir well, scraping up any browned bits from the bottom so they dissolve into the liquid.",null],["Add [[0.5 lb]] uncooked macaroni (about 2 cups) and stir to combine.",null],["Put a lid on the skillet and turn the heat up to medium-high. Let the broth come up to a full boil.",null],["Once it''s boiling, give the pasta a quick stir to loosen any stuck to the bottom. Turn the heat down to medium-low and put the lid back on.",null],["Let the macaroni simmer, stirring every few minutes and always putting the lid back, until the pasta is tender and the broth has reduced to a rich red gravy, about 10 minutes.",10],["Stir half of the [[1 cup]] shredded cheddar into the sauce until melted, then sprinkle the rest on top.",null],["Put the lid on, turn the heat off, and let the leftover heat melt the cheese on top. Serve hot!",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":471,"protein_g":25,"carbs_g":36,"fat_g":25},"video":"https://www.youtube.com/watch?v=d8AjTrttx28","country":"US","effort_steps":6,"ingredients":[{"item":"yellow onion","qty":1,"note":"diced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"ground beef","qty":1,"unit":"lb"},{"item":"all-purpose flour","qty":2,"unit":"tbsp"},{"item":"chili powder","qty":1,"unit":"tbsp"},{"item":"smoked paprika","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.5,"unit":"tsp"},{"item":"dried oregano","qty":0.5,"unit":"tsp"},{"item":"tomato sauce","qty":8,"unit":"oz"},{"item":"beef broth","qty":3,"unit":"cup"},{"item":"uncooked macaroni","qty":0.5,"unit":"lb","note":"about 2 cups"},{"item":"shredded cheddar","qty":1,"unit":"cup"}]}'::jsonb),
('www-budgetbytes-com-sloppy-joes', 'Easy Old Fashioned Sloppy Joes', 'American', 'Budget Bytes', 'https://www.budgetbytes.com/sloppy-joes/', 30, 5, 2, 2, 1, 7, 40, array['beef', 'onion', 'bell peppers', 'garlic', 'tomatoes', 'tomato paste', 'buns']::text[], '{"title":"Easy Old Fashioned Sloppy Joes","cuisine":"American","source":"Budget Bytes","url":"https://www.budgetbytes.com/sloppy-joes/","minutes":30,"servings":5,"key":["Ground beef","Onion","Bell peppers","Garlic","Tomato sauce","Tomato paste","Hamburger buns"],"minor":["Apple cider vinegar","Brown sugar","Dijon mustard","Chili powder","Worcestershire sauce"],"amounts":{"Ground beef":"1 lb","Onion":"1 yellow","Bell peppers":"1 green","Garlic":"2 cloves","Tomato sauce":"15 oz can","Tomato paste":"3 Tbsp","Hamburger buns":"5"},"steps":[["On a clean cutting board, finely dice [[1]] yellow onion and [[1]] green bell pepper, and mince [[2 cloves]] garlic.",null],["Add [[1 tbsp]] olive oil and [[1 lb]] ground beef to a skillet. Cook over medium heat until the beef is cooked through.",null],["Carefully drain off any extra fat from the skillet.",null],["Add the onion, garlic and bell pepper to the skillet with the beef. Keep sautéing until the onions are soft and translucent.",null],["Add [[1 can (15 oz)]] tomato sauce, [[3 tbsp]] tomato paste, [[2 tbsp]] apple cider vinegar, [[2 tbsp]] brown sugar, [[1 tsp]] Dijon mustard, [[1 tsp]] chili powder, [[1 tsp]] Worcestershire sauce and [[0.75 tsp]] salt to the skillet. Stir to combine.",null],["Let the meat and sauce simmer over medium-low for about 5 minutes.",5],["Toast [[5]] hamburger buns and spoon the meat sauce over them to serve.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":440,"protein_g":22,"carbs_g":36,"fat_g":23},"video":"https://www.youtube.com/watch?v=XyoVejJRmtM","country":"US","effort_steps":6,"ingredients":[{"item":"yellow onion","qty":1,"note":"finely diced"},{"item":"green bell pepper","qty":1,"note":"finely diced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"ground beef","qty":1,"unit":"lb"},{"item":"tomato sauce","qty":1,"unit":"can (15 oz)"},{"item":"tomato paste","qty":3,"unit":"tbsp"},{"item":"apple cider vinegar","qty":2,"unit":"tbsp"},{"item":"brown sugar","qty":2,"unit":"tbsp"},{"item":"Dijon mustard","qty":1,"unit":"tsp"},{"item":"chili powder","qty":1,"unit":"tsp"},{"item":"Worcestershire sauce","qty":1,"unit":"tsp"},{"item":"salt","qty":0.75,"unit":"tsp"},{"item":"hamburger buns","qty":5,"note":"toasted"}]}'::jsonb),
('www-recipetineats-com-chicken-pot-pie', 'Chicken Pot Pie', 'American', 'RecipeTin Eats', 'https://www.recipetineats.com/chicken-pot-pie/', 75, 4, 5, 3, 3, 18, 78, array['chicken', 'milk', 'onion', 'carrots', 'celery', 'butter', 'puff pastry']::text[], '{"title":"Chicken Pot Pie","cuisine":"American","source":"RecipeTin Eats","url":"https://www.recipetineats.com/chicken-pot-pie/","minutes":75,"servings":4,"key":["Chicken breast","Milk","Onion","Carrots","Celery","Butter","Puff pastry"],"minor":["Garlic","Thyme","White wine","Flour","Parmesan","Frozen peas","Egg","Chicken broth"],"amounts":{"Chicken breast":"600 g (or boneless thighs)","Milk":"2 cups","Onion":"1 large","Carrots":"2-3 large","Celery":"3 ribs","Butter":"50 g","Puff pastry":"2 sheets"},"steps":[["On a clean cutting board, chop [[1 large]] onion, [[2 large]] carrots and [[3 ribs]] celery, and mince [[2 cloves]] garlic. In a small bowl, lightly whisk [[1]] egg and set it aside for later.",null],["Pour [[2 cups]] milk, [[1 cup]] chicken broth and [[2 tsp]] stock powder into a large saucepan. Bring it to a very gentle simmer over medium heat.",null],["Add [[600 g]] chicken and [[2 sprigs]] thyme (optional) to the saucepan. Put the lid on and simmer gently on medium-low for 15 minutes. Don''t let it boil, or the milk can split.",15],["Take the chicken out and shred or dice it on the cutting board (it''s fine if the inside is still a bit uncooked). Cover the saucepan and set the poaching liquid aside for later.",null],["Melt [[50 g]] butter in a large pot over medium-high heat. Add the garlic and onion and cook for 2 minutes.",2],["Add [[1 tsp]] dried thyme, the carrot and the celery to the pot. Cook for 3 minutes, or until the carrot is softened.",3],["Pour in [[0.333 cup]] white wine. Stir, scraping the bottom of the pot, and cook for 1 1/2 minutes or until the wine is mostly evaporated.",1.5],["Add [[0.333 cup]] flour to the pot and stir for 1 minute.",1],["Pour in about half of the saved poaching liquid and stir until all the flour is mixed in. It will look like a thick sludge, and that''s normal.",null],["Add the rest of the poaching liquid, [[0.5 cup]] grated parmesan and [[0.5 tsp]] black pepper. Stir.",null],["Add the chicken and [[1 cup]] frozen peas back into the pot and stir.",null],["Once the mixture is heated (you''ll see steam), cook for 3 minutes to thicken the sauce, stirring regularly.",3],["Take the pot off the heat. Spoon the filling into oven-proof pots (4 large or 6 small). Cool them in the fridge for at least 30 minutes.",30],["Meanwhile, take [[2 sheets]] puff pastry out of the freezer to partially thaw. Using a bowl as a guide, cut rounds about 2.5 cm (1\") wider all the way around than your pots. Be generous!",null],["Preheat the oven to 350°F (180°C).",null],["Brush the rims of the pots with the whisked egg. Top each with a pastry round, folding the edges down.",null],["Brush the pastry tops with egg. With a small knife, cut a 2 cm (2/3\") slit in the middle of each.",null],["Bake for 35 to 40 minutes, until the pastry is deep golden. Serve immediately!",35]],"technique":5,"prep":3,"precision":3,"nutrition":{"calories":588,"protein_g":47,"carbs_g":36,"fat_g":26},"video":null,"country":"US","effort_steps":7,"ingredients":[{"item":"chicken breast","qty":600,"unit":"g","note":"or boneless thighs (1.2 lb)","group":"Chicken & Broth"},{"item":"milk","qty":2,"unit":"cup","note":"any fat %","group":"Chicken & Broth"},{"item":"chicken broth (stock)","qty":1,"unit":"cup","group":"Chicken & Broth"},{"item":"chicken or vegetable stock powder","qty":2,"unit":"tsp","group":"Chicken & Broth"},{"item":"thyme","qty":2,"unit":"sprig","note":"optional","group":"Chicken & Broth"},{"item":"onion","qty":1,"unit":"large","note":"chopped","group":"Chicken Pot Pie"},{"item":"carrots","qty":2,"unit":"large","note":"chopped (or 3 small)","group":"Chicken Pot Pie"},{"item":"celery","qty":3,"unit":"rib","note":"chopped","group":"Chicken Pot Pie"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Chicken Pot Pie"},{"item":"butter","qty":50,"unit":"g","note":"3 tbsp","group":"Chicken Pot Pie"},{"item":"dried thyme","qty":1,"unit":"tsp","group":"Chicken Pot Pie"},{"item":"white wine","qty":0.333,"unit":"cup","note":"sub more chicken stock","group":"Chicken Pot Pie"},{"item":"flour","qty":0.333,"unit":"cup","group":"Chicken Pot Pie"},{"item":"grated parmesan","qty":0.5,"unit":"cup","group":"Chicken Pot Pie"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Chicken Pot Pie"},{"item":"frozen peas","qty":1,"unit":"cup","note":"no need to thaw","group":"Chicken Pot Pie"},{"item":"puff pastry","qty":2,"unit":"sheet","note":"enough to cover pots, with drape","group":"Chicken Pot Pie"},{"item":"egg","qty":1,"note":"lightly whisked","group":"Chicken Pot Pie"}]}'::jsonb),
('www-budgetbytes-com-shrimp-and-grits', 'Shrimp and Grits', 'Southern', 'Budget Bytes', 'https://www.budgetbytes.com/shrimp-and-grits/', 35, 4, 3, 2, 3, 13, 51, array['shrimp', 'grit', 'broth', 'cheddar', 'butter', 'onion', 'milk']::text[], '{"title":"Shrimp and Grits","cuisine":"Southern","source":"Budget Bytes","url":"https://www.budgetbytes.com/shrimp-and-grits/","minutes":35,"servings":4,"key":["Frozen shrimp","Grits","Chicken broth","Cheddar","Butter","Onion","Milk"],"minor":["Cajun seasoning","Garlic","Flour","Hot sauce","Scallions"],"amounts":{"Frozen shrimp":"16 oz jumbo, thawed, peeled","Grits":"1 cup old-fashioned","Chicken broth":"3 cups (divided)","Cheddar":"1 cup grated","Butter":"2 Tbsp","Onion":"1/2","Milk":"1/4 cup"},"steps":[["On a clean cutting board, small-dice [[0.5]] onion, mince [[2 cloves]] garlic and slice [[2]] green onions. Grate [[1 cup]] cheddar if it isn''t already.",null],["In a medium pot over medium-high heat, bring [[2 cups]] water, [[2 cups]] of the chicken broth, [[0.25 tsp]] salt and [[0.25 tsp]] black pepper to a boil.",null],["Once it''s boiling, stir in [[1 cup]] grits and turn the heat to low. Cover and cook for 15-20 minutes, stirring now and then.",15],["While the grits simmer, pat [[16 oz]] shrimp dry with paper towels and season both sides with [[1 tbsp]] Cajun seasoning.",null],["Heat [[1 tbsp]] vegetable oil in a medium skillet over medium-high heat. Once hot, sear the shrimp for 1-2 minutes on each side, working in batches if needed.",1],["Move the shrimp out of the skillet onto a plate and turn the heat to medium.",null],["Add the onion to the same skillet and sauté for 5 minutes, until translucent.",5],["Add the garlic and cook for 2 more minutes.",2],["Sprinkle [[2 tbsp]] flour over the onions and cook for 1 minute.",1],["Pour the remaining [[1 cup]] chicken broth, [[0.25 cup]] milk and [[1 tbsp]] hot sauce into the skillet. Bring to a simmer and cook for 2 minutes until thickened, gently scraping the bottom of the skillet.",2],["Slide the shrimp back into the skillet just to warm through.",null],["To finish the grits, stir [[2 tbsp]] butter and the cheddar into the pot until melted.",null],["Divide the grits evenly among four bowls. Spoon the shrimp and sauce over the top and garnish with the green onions.",null]],"technique":3,"prep":2,"precision":3,"nutrition":{"calories":468,"protein_g":28,"carbs_g":40,"fat_g":21},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"water","qty":2,"unit":"cup"},{"item":"chicken broth","qty":3,"unit":"cup","note":"divided"},{"item":"old-fashioned grits","qty":1,"unit":"cup","note":"uncooked, 175g"},{"item":"salt","qty":0.25,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"freshly cracked"},{"item":"jumbo shrimp","qty":16,"unit":"oz","note":"thawed, peeled & deveined, 21-30 per pound"},{"item":"Cajun seasoning","qty":1,"unit":"tbsp","note":"or Creole seasoning"},{"item":"vegetable oil","qty":1,"unit":"tbsp"},{"item":"onion","qty":0.5,"note":"small dice, 130g/1 cup"},{"item":"garlic","qty":2,"unit":"clove","note":"minced, 1 Tbsp"},{"item":"all-purpose flour","qty":2,"unit":"tbsp"},{"item":"milk","qty":0.25,"unit":"cup"},{"item":"hot sauce","qty":1,"unit":"tbsp"},{"item":"butter","qty":2,"unit":"tbsp"},{"item":"cheddar cheese","qty":1,"unit":"cup","note":"grated, 100g"},{"item":"green onions","qty":2,"note":"sliced"}]}'::jsonb),
('www-budgetbytes-com-chicken-and-dumplings', 'Homemade Chicken and Dumplings', 'Southern', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-and-dumplings/', 55, 6, 4, 3, 3, 14, 67, array['chicken', 'flour', 'butter', 'milk', 'broth', 'onion', 'carrots']::text[], '{"title":"Homemade Chicken and Dumplings","cuisine":"Southern","source":"Budget Bytes","url":"https://www.budgetbytes.com/chicken-and-dumplings/","minutes":55,"servings":6,"key":["Chicken thighs","Flour","Butter","Milk","Chicken broth","Onion","Carrots"],"minor":["Garlic","Celery","Parsley","Thyme","Rosemary","Sage","Baking powder","Garlic powder"],"amounts":{"Chicken thighs":"4 boneless skinless (about 1 lb)","Flour":"1/4 cup + 1 cup","Butter":"4 Tbsp + 2 Tbsp melted","Milk":"1 cup + 1/2 cup","Chicken broth":"2 cups","Onion":"1 yellow","Carrots":"2"},"steps":[["On a clean cutting board, dice [[1]] yellow onion, [[2]] carrots and [[2 ribs]] celery, and mince [[2 cloves]] garlic. Melt [[2 tbsp]] butter for the dumplings and set it aside.",null],["Heat [[1 tbsp]] olive oil in a deep skillet or Dutch oven over medium heat. Add [[4]] chicken thighs and brown them on each side (they don''t need to be cooked through).",null],["Move the chicken to a clean bowl and set it aside.",null],["Add the onion and garlic to the same skillet and sauté over medium heat until softened, stirring to dissolve the browned bits from the bottom of the pan.",null],["Add the carrots and celery to the skillet and keep sautéing for about 5 minutes more.",5],["Add [[4 tbsp]] butter and [[0.25 cup]] flour to the skillet. Stir until the butter melts and makes a paste that coats the vegetables, then cook and stir for about 2 minutes.",2],["Add [[1 tsp]] dried parsley, [[0.5 tsp]] dried thyme, [[0.5 tsp]] dried rosemary, [[0.5 tsp]] dried sage, [[0.5 tsp]] salt, [[0.25 tsp]] black pepper, [[2 cups]] chicken broth and [[1 cup]] whole milk to the skillet.",null],["Turn the heat to medium-high and stir until the mixture simmers and thickens into a gravy.",null],["On the cutting board, dice the browned chicken and add it back to the skillet. Cover with a lid and let it simmer over medium heat while you make the dumplings.",null],["In a new bowl, combine [[1 cup]] flour, [[1 tsp]] dried parsley, [[0.5 tsp]] sugar, [[0.5 tsp]] salt, [[1.5 tsp]] baking powder, [[0.125 tsp]] garlic powder and [[0.125 tsp]] black pepper.",null],["Pour [[0.5 cup]] milk and the melted butter into the flour mixture. Stir just until a soft, scoopable batter forms. Don''t over-stir.",null],["Take the lid off the skillet. Drop the dumpling batter onto the surface of the gravy in [[2 tbsp]] dollops (about 12 dumplings).",null],["Make sure the gravy is simmering, then put the lid back on. Let the dumplings simmer for 15 minutes without lifting the lid. They should double in size and be fluffy and cooked through.",15],["Check that the thickest chicken pieces reach 165°F. Serve hot.",null]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":369,"protein_g":20,"carbs_g":28,"fat_g":19},"video":"https://www.youtube.com/watch?v=ze4_calJyEQ","country":"US","effort_steps":7,"ingredients":[{"item":"chicken thighs","qty":4,"note":"boneless, skinless, about 1 lb","group":"Chicken and Gravy"},{"item":"olive oil","qty":1,"unit":"tbsp","group":"Chicken and Gravy"},{"item":"yellow onion","qty":1,"note":"diced","group":"Chicken and Gravy"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Chicken and Gravy"},{"item":"carrots","qty":2,"note":"diced","group":"Chicken and Gravy"},{"item":"celery","qty":2,"unit":"rib","note":"diced","group":"Chicken and Gravy"},{"item":"butter","qty":4,"unit":"tbsp","group":"Chicken and Gravy"},{"item":"all-purpose flour","qty":0.25,"unit":"cup","group":"Chicken and Gravy"},{"item":"chicken broth","qty":2,"unit":"cup","group":"Chicken and Gravy"},{"item":"whole milk","qty":1,"unit":"cup","group":"Chicken and Gravy"},{"item":"dried parsley","qty":1,"unit":"tsp","group":"Gravy Seasonings"},{"item":"dried thyme","qty":0.5,"unit":"tsp","group":"Gravy Seasonings"},{"item":"dried rosemary","qty":0.5,"unit":"tsp","group":"Gravy Seasonings"},{"item":"dried sage","qty":0.5,"unit":"tsp","group":"Gravy Seasonings"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Gravy Seasonings"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Gravy Seasonings"},{"item":"all-purpose flour","qty":1,"unit":"cup","group":"Dumplings"},{"item":"baking powder","qty":1.5,"unit":"tsp","group":"Dumplings"},{"item":"dried parsley","qty":1,"unit":"tsp","group":"Dumplings"},{"item":"granulated sugar","qty":0.5,"unit":"tsp","group":"Dumplings"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Dumplings"},{"item":"garlic powder","qty":0.125,"unit":"tsp","group":"Dumplings"},{"item":"black pepper","qty":0.125,"unit":"tsp","group":"Dumplings"},{"item":"milk","qty":0.5,"unit":"cup","group":"Dumplings"},{"item":"butter","qty":2,"unit":"tbsp","note":"melted","group":"Dumplings"}]}'::jsonb),
('www-budgetbytes-com-jambalaya', 'Slow Cooker Jambalaya', 'Cajun', 'Budget Bytes', 'https://www.budgetbytes.com/jambalaya/', 285, 8, 1, 3, 2, 10, 61, array['sausage', 'rice', 'tomatoes', 'chicken', 'onion', 'bell peppers', 'celery']::text[], '{"title":"Slow Cooker Jambalaya","cuisine":"Cajun","source":"Budget Bytes","url":"https://www.budgetbytes.com/jambalaya/","minutes":285,"servings":8,"key":["Smoked sausage","Rice","Canned tomatoes","Chicken thighs","Onion","Bell peppers","Celery"],"minor":["Garlic","Oregano","Thyme","Smoked paprika","Cayenne","Parsley","Scallions","Chicken broth"],"amounts":{"Smoked sausage":"12-16 oz","Rice":"2 cups long-grain white, uncooked","Canned tomatoes":"28 oz can diced","Chicken thighs":"2 boneless skinless (optional)","Onion":"1 yellow","Bell peppers":"1 green","Celery":"3 ribs"},"steps":[["On a clean cutting board, finely dice [[3 ribs]] celery, [[1]] yellow onion and [[1]] green bell pepper, and mince [[2 cloves]] garlic.",null],["Slice [[12 oz]] smoked sausage into half moons or rounds. If using, cube [[2]] chicken thighs. Chop [[0.25 bunch]] fresh parsley and slice [[3]] green onions.",null],["Put the celery, onion, bell pepper and garlic into the bottom of a 5-quart or larger slow cooker.",null],["Add the sausage, chicken, [[1 tsp]] dried oregano, [[1 tsp]] dried thyme, [[0.5 tbsp]] smoked paprika, [[0.5 tsp]] cayenne and freshly cracked black pepper (15-20 cranks) to the slow cooker.",null],["Pour [[1 can (28 oz)]] diced tomatoes with all their juices over the meat and spices. Add [[2 cups]] chicken broth and the parsley, and stir briefly.",null],["Cover the slow cooker, turn the heat to high, and cook for four hours.",240],["After four hours the liquid should be boiling. Remove the lid and add [[2 cups]] uncooked rice, making sure it''s fully under the liquid. Put the lid back on and keep it on high.",null],["Keep cooking on high for 20-25 minutes, or until the rice has absorbed most of the liquid.",20],["Remove the lid and taste the rice to make sure it''s tender. Stir gently to fluff it (stirring hard makes it gummy).",null],["Sprinkle the green onions over the top and serve.",null]],"technique":1,"prep":3,"precision":2,"nutrition":{"calories":348,"protein_g":15,"carbs_g":41,"fat_g":13},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"celery","qty":3,"unit":"rib","note":"finely diced, 125g"},{"item":"yellow onion","qty":1,"note":"finely diced, 1 cup, 150g"},{"item":"green bell pepper","qty":1,"note":"finely diced, 1 cup, 150g"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"smoked sausage","qty":12,"qtyMax":16,"unit":"oz","note":"sliced into half moons or rounds"},{"item":"chicken thighs","qty":2,"note":"boneless, skinless, cubed (optional)"},{"item":"dried oregano","qty":1,"unit":"tsp"},{"item":"dried thyme","qty":1,"unit":"tsp"},{"item":"smoked paprika","qty":0.5,"unit":"tbsp"},{"item":"cayenne pepper","qty":0.5,"unit":"tsp"},{"item":"black pepper","note":"freshly cracked, 15-20 cranks of a mill"},{"item":"diced tomatoes","qty":1,"unit":"can (28 oz)","note":"or two 15 oz. cans"},{"item":"chicken broth","qty":2,"unit":"cup"},{"item":"fresh parsley","qty":0.25,"unit":"bunch","note":"chopped"},{"item":"long grain white rice","qty":2,"unit":"cup","note":"uncooked, 370g"},{"item":"green onions","qty":3,"note":"sliced"}]}'::jsonb),
('www-budgetbytes-com-louisiana-red-beans-rice', 'Louisiana Style Red Beans and Rice with Sausage', 'Cajun', 'Budget Bytes', 'https://www.budgetbytes.com/louisiana-red-beans-rice/', 615, 6, 4, 3, 2, 17, 81, array['kidney beans', 'sausage', 'rice', 'onion', 'bell peppers', 'celery', 'garlic']::text[], '{"title":"Louisiana Style Red Beans and Rice with Sausage","cuisine":"Cajun","source":"Budget Bytes","url":"https://www.budgetbytes.com/louisiana-red-beans-rice/","minutes":615,"servings":6,"key":["Dry red beans","Andouille sausage","Rice","Onion","Bell peppers","Celery","Garlic"],"minor":["Smoked paprika","Oregano","Thyme","Garlic powder","Onion powder","Cayenne","Bay leaves","Parsley","Scallions"],"amounts":{"Dry red beans":"1 lb","Andouille sausage":"14 oz","Rice":"1.5 cups long grain white, uncooked","Onion":"1 yellow","Bell peppers":"1 green","Celery":"3 ribs","Garlic":"4 cloves"},"steps":[["The night before, put [[1 lb]] dry red beans in a large bowl with double their volume in water. Let them soak in the refrigerator overnight.",480],["When you''re ready to cook, slice [[14 oz]] Andouille sausage into rounds on a clean cutting board.",null],["Add [[2 tbsp]] cooking oil and the sliced sausage to a large pot. Cook over medium until the sausage pieces are browned.",null],["While the sausage cooks, dice [[1]] yellow onion, [[1]] green bell pepper and [[3 ribs]] celery, and mince [[4 cloves]] garlic.",null],["Use a slotted spoon to move the cooked sausage to a clean bowl, and put it in the refrigerator while you make the rest of the dish.",null],["Add the onion, bell pepper, celery and garlic to the same pot (you can drain the fat first if you like). Sauté over medium heat until the onions are soft, stirring so the moisture from the veggies loosens the browned bits on the bottom.",null],["Add [[2 tsp]] smoked paprika, [[1 tsp]] dried oregano, [[1 tsp]] dried thyme, [[0.5 tsp]] garlic powder, [[0.5 tsp]] onion powder, [[0.25 tsp]] cayenne, [[0.25 tsp]] black pepper and [[2]] bay leaves to the pot. Stir and cook for one minute more.",1],["Drain and rinse the soaked beans. Add them to the pot with [[6 cups]] water and give it a quick stir.",null],["Put a lid on the pot, turn the heat up to medium-high, and bring it to a boil.",null],["Once boiling, turn the heat down to medium-low and let it boil for one hour, stirring now and then. Put the lid back on every time you stir.",60],["After an hour the beans should be tender. Smash some beans against the side of the pot with the back of a spoon. Keep smashing and let the pot simmer with no lid for 30 minutes to thicken.",30],["While the beans simmer, cook the rice: add [[1.5 cups]] rice and [[3 cups]] water to a sauce pot. Put a lid on, turn the heat to high, and bring it to a boil.",null],["Once boiling, turn the heat down to low and let the rice simmer for 15 minutes.",15],["Turn the heat off and let the rice rest for 5 minutes without removing the lid. Fluff it with a fork before serving.",5],["Once the red beans have thickened, add the cooked sausage back to the pot along with [[0.25 cup]] chopped parsley. Stir to combine.",null],["Taste the beans and add salt to your liking. Start with [[1 tsp]] and add more as needed (the recipe used [[1 tbsp]] total).",null],["Serve the red beans in a bowl topped with a scoop of rice and a sprinkle of sliced green onions.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":702,"protein_g":33,"carbs_g":89,"fat_g":24},"video":"https://www.youtube.com/watch?v=awTM_rrfLKQ","country":"US","effort_steps":7,"ingredients":[{"item":"dry red beans","qty":1,"unit":"lb"},{"item":"cooking oil","qty":2,"unit":"tbsp"},{"item":"Andouille sausage","qty":14,"unit":"oz"},{"item":"yellow onion","qty":1},{"item":"green bell pepper","qty":1},{"item":"celery","qty":3,"unit":"rib"},{"item":"garlic","qty":4,"unit":"clove"},{"item":"smoked paprika","qty":2,"unit":"tsp"},{"item":"dried oregano","qty":1,"unit":"tsp"},{"item":"dried thyme","qty":1,"unit":"tsp"},{"item":"garlic powder","qty":0.5,"unit":"tsp"},{"item":"onion powder","qty":0.5,"unit":"tsp"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"freshly cracked"},{"item":"bay leaves","qty":2},{"item":"water","qty":6,"unit":"cup"},{"item":"parsley","qty":0.25,"unit":"cup","note":"chopped"},{"item":"salt","qty":1,"unit":"tbsp","note":"or to taste"},{"item":"long grain white rice","qty":1.5,"unit":"cup","note":"uncooked"},{"item":"green onions","qty":3,"note":"sliced"}]}'::jsonb),
('jamaicanfoodsandrecipes-com-jamaican-rice-and-peas-recipe', 'Jamaican Rice and Peas Recipe', 'Caribbean', 'Jamaican Foods and Recipes', 'https://jamaicanfoodsandrecipes.com/jamaican-rice-and-peas-recipe/', 50, 3, 1, 1, 3, 10, 38, array['kidney beans', 'rice', 'coconut milk', 'onion', 'garlic']::text[], '{"title":"Jamaican Rice and Peas Recipe","cuisine":"Caribbean","source":"Jamaican Foods and Recipes","url":"https://jamaicanfoodsandrecipes.com/jamaican-rice-and-peas-recipe/","minutes":50,"servings":3,"key":["Dry kidney beans","Rice","Coconut milk","Onion","Garlic"],"minor":["Scallions","Thyme","Scotch bonnet pepper","Ginger","Allspice berries"],"amounts":{"Dry kidney beans":"100 g (or 1 can)","Rice":"263 g long grain","Coconut milk":"231 ml","Onion":"1/2 red","Garlic":"2 cloves"},"steps":[["Wash [[100 g]] dry kidney beans, then cover them with fresh water in a bowl and soak for at least two hours, preferably overnight. (Using canned beans? See the canned version on the recipe page: wash and drain the beans and skip the soaking and pressure cooking.)",120],["On a clean cutting board, chop [[0.5]] red onion and [[1 stalk]] scallions, and crush [[2 cloves]] garlic.",null],["Drain the beans and put them in a pressure cooker with the garlic, [[5]] pimento berries, a very small piece of ginger, [[1 tsp]] salt and about 4½ to 5 cups of water.",null],["Pressure cook for 20 minutes. No pressure cooker? Cook them in a pot for 45-50 minutes instead.",20],["Once the beans are cooked, add [[231 ml]] coconut milk, [[4 sprigs]] thyme, the scallion, the onion and [[1]] whole Scotch bonnet pepper to the pot.",null],["Cover the pot and bring it to a boil. Taste the liquid to see if it''s seasoned to your liking.",null],["Wash [[263 g]] rice and add it to the pot. Put the lid back on and bring it to a boil.",null],["Turn the heat down to low and let the rice steam until all the water has evaporated.",null],["Turn the heat off and let the rice sit for another 3 minutes.",3],["Remove the thyme stems, Scotch bonnet pepper and ginger, then serve!",null]],"technique":1,"prep":1,"precision":3,"nutrition":{"calories":264,"protein_g":5,"carbs_g":58,"fat_g":1},"video":null,"country":"JM","effort_steps":5,"ingredients":[{"item":"dry red kidney beans (peas)","qty":100,"unit":"g"},{"item":"homemade coconut milk","qty":231,"unit":"ml"},{"item":"long grain rice","qty":263,"unit":"g","note":"or 317g (1½) basmati rice"},{"item":"red onion","qty":0.5,"note":"chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"crushed"},{"item":"scallions","qty":1,"unit":"stalk","note":"chopped"},{"item":"thyme","qty":4,"unit":"sprig"},{"item":"Scotch bonnet pepper","qty":1,"note":"whole"},{"item":"ginger","note":"very small piece"},{"item":"pimento berries (allspice)","qty":5},{"item":"salt","qty":1,"unit":"tsp"},{"item":"water","qty":1.12,"unit":"l"},{"item":"kidney beans","qty":1,"unit":"can","note":"replaces the dry beans","group":"For canned beans & coconut milk version"},{"item":"coconut milk","qty":0.5,"unit":"can","note":"replaces the homemade coconut milk","group":"For canned beans & coconut milk version"},{"item":"water","qty":319,"unit":"ml","note":"replaces the 1.12 l water","group":"For canned beans & coconut milk version"}]}'::jsonb),
('www-budgetbytes-com-picadillo', 'Authentic and Delicious Picadillo Recipe', 'Caribbean', 'Budget Bytes', 'https://www.budgetbytes.com/picadillo/', 30, 8, 2, 2, 1, 9, 38, array['beef', 'tomatoes', 'onion', 'bell peppers', 'green olive', 'raisin']::text[], '{"title":"Authentic and Delicious Picadillo Recipe","cuisine":"Caribbean","source":"Budget Bytes","url":"https://www.budgetbytes.com/picadillo/","minutes":30,"servings":8,"key":["Ground beef","Tomato sauce","Onion","Bell peppers","Green olives","Raisins"],"minor":["Garlic","Sazon","Adobo","Sofrito","White vinegar","Bay leaves"],"amounts":{"Ground beef":"1 lb (80/20)","Tomato sauce":"15 oz","Onion":"1 small yellow","Bell peppers":"1 red","Green olives":"1/2 cup sliced pimento-stuffed","Raisins":"1/4 cup"},"steps":[["On a clean cutting board, small-dice [[1]] yellow onion and [[1]] red bell pepper, and mince [[1 tbsp]] garlic.",null],["Put a large skillet over medium-high heat and add [[1.5 tbsp]] olive oil.",null],["When the oil is hot, add the onion and bell pepper. Cook until the onions are transparent.",null],["Add the garlic and cook until fragrant.",null],["Add [[1 lb]] ground beef to the skillet and sprinkle it with [[1 tsp]] coarse salt, [[1.5 tsp]] sazón and [[1 tsp]] adobo. Break up the chunks as the beef browns.",null],["When the beef is browned, add [[0.5 cup]] sofrito. Cook, stirring constantly, about 2 minutes until fragrant.",2],["Add [[0.5 cup]] sliced olives, [[0.25 cup]] raisins, [[0.5 tbsp]] white vinegar, [[15 oz]] tomato sauce, [[2]] bay leaves and [[0.25 cup]] water to the skillet.",null],["Cook for 10 minutes, stirring now and then.",10],["Take the skillet off the heat and let it cool.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":212,"protein_g":11,"carbs_g":7,"fat_g":16},"video":null,"country":"CU","effort_steps":5,"ingredients":[{"item":"olive oil","qty":1.5,"unit":"tbsp"},{"item":"yellow onion","qty":1,"note":"small dice"},{"item":"red bell pepper","qty":1,"note":"small dice"},{"item":"garlic","qty":1,"unit":"tbsp","note":"minced"},{"item":"ground beef (80/20)","qty":1,"unit":"lb"},{"item":"coarse salt","qty":1,"unit":"tsp"},{"item":"sazón","qty":1.5,"unit":"tsp","note":"1 packet"},{"item":"adobo","qty":1,"unit":"tsp"},{"item":"sofrito","qty":0.5,"unit":"cup"},{"item":"pimento-stuffed green olives","qty":0.5,"unit":"cup","note":"sliced"},{"item":"raisins","qty":0.25,"unit":"cup"},{"item":"white vinegar","qty":0.5,"unit":"tbsp"},{"item":"tomato sauce","qty":15,"unit":"oz"},{"item":"bay leaves","qty":2},{"item":"water","qty":0.25,"unit":"cup"}]}'::jsonb),
('muybuenoblog-com-brazilian-feijoada', 'Brazilian Feijoada (Pork and Black Bean Stew)', 'Brazilian', 'Muy Bueno', 'https://muybuenoblog.com/brazilian-feijoada/', 255, 12, 4, 3, 2, 20, 81, array['black beans', 'bacon', 'pork', 'sausage', 'onion', 'tomatoes', 'rice']::text[], '{"title":"Brazilian Feijoada (Pork and Black Bean Stew)","cuisine":"Brazilian","source":"Muy Bueno","url":"https://muybuenoblog.com/brazilian-feijoada/","minutes":255,"servings":12,"key":["Dry black beans","Bacon","Pork chops","Smoked sausage","Onion","Tomatoes","Rice"],"minor":["Garlic","Bay leaves","Bell pepper","Cilantro","Butter","Chicken broth","Scallions"],"amounts":{"Dry black beans":"1 lb","Bacon":"1 lb","Pork chops":"4 thin","Smoked sausage":"14 oz","Onion":"1 large + 1/2","Tomatoes":"3","Rice":"1.5 cups white basmati"},"steps":[["Sort through [[1 lb]] dry black beans and throw out any broken, discolored or shriveled beans, stones and debris.",null],["Put the beans in a colander and rinse them well under cool water for about 3 minutes.",3],["Put the beans, [[1 tsp]] salt, [[0.5]] quartered onion, [[2 cloves]] garlic, [[2]] bay leaves and [[2 l]] water into an Instant Pot. Cook on the manual setting for 30 minutes of pressure, then let the pressure release naturally (about 30 to 40 minutes). Season the beans to taste.",30],["No Instant Pot? Put the same bean ingredients in a Dutch oven, bring to a boil, then reduce the heat to low and simmer for 2 to 3 hours until tender.",null],["On a clean cutting board, chop [[1 lb]] bacon, cut [[4]] thin pork chops into ½-inch cubes, slice [[14 oz]] smoked sausage, chop [[1 large]] onion and [[1]] bell pepper, mince [[4 cloves]] garlic and dice [[3]] tomatoes.",null],["In a large 7-quart Dutch oven or stockpot over medium heat, add [[1 tbsp]] olive oil and the bacon. Cook until crisp, then move the bacon to a plate.",null],["Add the pork to the bacon drippings in the same pot and cook for 5 minutes, stirring constantly so it browns evenly.",5],["Add the sausage and brown it with the pork for 2 to 3 more minutes. Set the pork and sausage aside with the bacon.",2],["Add more oil if needed. On medium-high heat, sauté the onion and garlic in the same pot until tender and translucent, about 4 minutes.",4],["Add the tomatoes and bell pepper and cook for another 3 minutes. Stir in [[1 handful]] cilantro leaves.",3],["Add the cooked beans and their cooking liquid to the pot along with the bacon, pork, sausage, [[1 tsp]] salt and [[1 tsp]] black pepper.",null],["Bring to a boil, then reduce the heat to low. Cover and simmer for 2 to 3 hours until thickened.",120],["For the rice, slice [[6 cloves]] garlic thinly, mince [[2 cloves]] garlic and slice [[0.25 cup]] green onions.",null],["Heat [[2 tbsp]] olive oil in a large saucepan over medium heat. Add the sliced garlic and sauté, stirring constantly, until golden and crisp. Move it to a paper towel to drain.",null],["Add [[4 tbsp]] butter and the minced garlic to the same saucepan. Cook until the garlic turns light golden brown and the butter melts.",null],["Add [[1.5 cups]] basmati rice and stir to coat it in the garlic butter for 1 to 2 minutes to lightly toast.",1],["Add [[2.5 cups]] chicken broth and bring to a boil. Reduce the heat to medium-low, cover, and simmer for 15 to 17 minutes until the liquid is absorbed.",15],["Take the saucepan off the heat but keep the lid on. Let it rest for 10 minutes.",10],["Fluff the rice with a fork and add the crispy garlic slices and green onions. Taste and season with salt if needed.",null],["Serve the feijoada with the garlic butter rice and collard greens.",null]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":381,"protein_g":11,"carbs_g":33,"fat_g":23},"video":null,"country":"BR","effort_steps":7,"ingredients":[{"item":"dry black beans","qty":1,"unit":"lb","group":"Black Beans"},{"item":"salt","qty":1,"unit":"tsp","group":"Black Beans"},{"item":"onion","qty":0.5,"note":"quartered","group":"Black Beans"},{"item":"garlic","qty":2,"unit":"clove","group":"Black Beans"},{"item":"bay leaves","qty":2,"group":"Black Beans"},{"item":"water","qty":2,"unit":"l","group":"Black Beans"},{"item":"olive oil","qty":1,"unit":"tbsp","group":"Stew"},{"item":"bacon","qty":1,"unit":"lb","note":"chopped","group":"Stew"},{"item":"thin pork chops","qty":4,"note":"chopped into ½-inch cubes","group":"Stew"},{"item":"smoked sausage (such as andouille or kielbasa)","qty":14,"unit":"oz","note":"sliced","group":"Stew"},{"item":"onion","qty":1,"unit":"large","note":"chopped","group":"Stew"},{"item":"garlic","qty":4,"unit":"clove","note":"minced","group":"Stew"},{"item":"tomatoes","qty":3,"note":"diced","group":"Stew"},{"item":"bell pepper","qty":1,"note":"chopped","group":"Stew"},{"item":"cilantro leaves","qty":1,"unit":"handful","group":"Stew"},{"item":"salt","qty":1,"unit":"tsp","group":"Stew"},{"item":"ground black pepper","qty":1,"unit":"tsp","group":"Stew"},{"item":"garlic","qty":6,"unit":"clove","note":"thinly sliced","group":"Garlic Butter Rice"},{"item":"olive oil","qty":2,"unit":"tbsp","group":"Garlic Butter Rice"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Garlic Butter Rice"},{"item":"butter","qty":4,"unit":"tbsp","note":"salted or unsalted","group":"Garlic Butter Rice"},{"item":"white basmati rice","qty":1.5,"unit":"cup","group":"Garlic Butter Rice"},{"item":"chicken broth","qty":2.5,"unit":"cup","group":"Garlic Butter Rice"},{"item":"green onions","qty":0.25,"unit":"cup","note":"sliced","group":"Garlic Butter Rice"},{"item":"salt","note":"to taste","group":"Garlic Butter Rice"}]}'::jsonb),
('www-budgetbytes-com-chicken-enchiladas', 'Chicken Enchiladas', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-enchiladas/', 50, 4, 3, 2, 2, 10, 53, array['chicken', 'tortillas', 'enchilada sauce', 'cheddar', 'green chilie']::text[], '{"title":"Chicken Enchiladas","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/chicken-enchiladas/","minutes":50,"servings":4,"key":["Chicken","Flour tortillas","Enchilada sauce","Shredded Mexican cheese","Canned green chilies"],"minor":["Cumin","Garlic powder"],"amounts":{"Chicken":"3 cups cooked, shredded","Flour tortillas":"8","Enchilada sauce":"2 cups, divided","Shredded Mexican cheese":"2½ cups, divided","Canned green chilies":"4 oz can, diced"},"steps":[["Get your [[2 cups]] enchilada sauce ready: make the homemade sauce now, or if you''re using store-bought, just set it aside.",null],["Shred [[3 cups]] cooked chicken with two forks on a clean cutting board.",null],["Put the shredded chicken in a large bowl and sprinkle on [[0.5 tsp]] cumin, [[0.5 tsp]] garlic powder and [[0.25 tsp]] salt. Mix to combine.",null],["Add the [[4 oz can]] diced green chilies and [[0.75 cup]] of the shredded cheese to the same bowl, and mix again.",null],["Preheat the oven to 350°F.",null],["Warm the [[8]] flour tortillas in the microwave following the package instructions, or in a dry skillet on the stovetop, so they''re soft enough to roll.",null],["Spread [[0.5 cup]] enchilada sauce over the bottom of a 9x13-inch baking dish until it covers the surface.",null],["Spoon about [[0.25 cup]] to [[0.333 cup]] of the chicken filling onto a tortilla, roll it closed, and set it in the dish seam side down. Repeat with the rest of the tortillas.",null],["Pour the remaining enchilada sauce over the rolled tortillas, then top with the remaining shredded cheese.",null],["Bake in the preheated oven for 20 minutes, until the cheese on top is fully melted. Serve hot with your favorite toppings.",20]],"technique":3,"prep":2,"precision":2,"nutrition":{"calories":771,"protein_g":53,"carbs_g":60,"fat_g":34},"video":"https://www.youtube.com/watch?v=MO2Z1Zxz9UM","country":"MX","effort_steps":6,"ingredients":[{"item":"homemade enchilada sauce","qty":2,"unit":"cup","note":"divided"},{"item":"cooked shredded chicken","qty":3,"unit":"cup"},{"item":"cumin","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.5,"unit":"tsp"},{"item":"salt","qty":0.25,"unit":"tsp"},{"item":"diced green chilies","qty":1,"unit":"can (4 oz)"},{"item":"flour tortillas","qty":8},{"item":"shredded Mexican cheese","qty":2.5,"unit":"cup","note":"divided"}]}'::jsonb),
('www-budgetbytes-com-2015-09-poor-mans-burrito-bowls', 'Poor Man''s Burrito Bowls', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/2015/09/poor-mans-burrito-bowls/', 25, 6, 1, 1, 1, 9, 27, array['rice', 'black beans', 'salsa', 'cheddar', 'scallions']::text[], '{"title":"Poor Man''s Burrito Bowls","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/2015/09/poor-mans-burrito-bowls/","minutes":25,"servings":6,"key":["Long grain white rice","Canned black beans","Salsa","Shredded cheese","Green onions"],"minor":["Ground cumin","Garlic powder","Jalapeño"],"amounts":{"Long grain white rice":"2 cups uncooked","Canned black beans":"2 (15 oz) cans","Salsa":"1 (16 oz) jar","Shredded cheese":"6 oz","Green onions":"1 bunch"},"steps":[["Put [[2 cups]] uncooked rice, [[0.5 tsp]] salt and [[3 cups]] water in a medium sauce pot and place the lid on top.",null],["Turn the heat to high and let the water come up to a full boil.",null],["Once it''s boiling, turn the heat down to low and let it simmer, lid on, for 15 minutes.",15],["Turn the heat off and let the rice sit with the lid still on for another 5 minutes. Fluff it with a fork just before serving.",5],["While the rice cooks, pour both [[2 cans (15 oz)]] black beans (don''t drain them) into a small sauce pot. Add [[0.5 tsp]] cumin and [[0.25 tsp]] garlic powder.",null],["Heat the beans over medium, stirring often, until they''re warmed through.",null],["On a clean cutting board, slice the [[1 bunch]] green onions and the [[1]] jalapeño, if you''re using it.",null],["Build each bowl: add [[1 cup]] cooked rice, [[0.5 cup]] warm black beans, [[0.333 cup]] salsa and [[1 oz]] shredded cheese (about [[0.25 cup]]).",null],["Top each bowl with a few sliced green onions and jalapeños, then serve.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":522,"protein_g":20,"carbs_g":85,"fat_g":10},"video":null,"country":"MX","effort_steps":5,"ingredients":[{"item":"long grain white rice","qty":2,"unit":"cup","note":"uncooked"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"black beans","qty":2,"unit":"can (15 oz)"},{"item":"ground cumin","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.25,"unit":"tsp"},{"item":"salsa","qty":1,"unit":"jar (16 oz)"},{"item":"shredded cheese","qty":6,"unit":"oz","note":"use your favorite meltable cheese, like cheddar or pepper jack"},{"item":"green onions","qty":1,"unit":"bunch"},{"item":"jalapeño","qty":1,"note":"optional"}]}'::jsonb),
('www-budgetbytes-com-baked-beef-black-bean-tacos', 'Crispy Baked Beef Tacos', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/baked-beef-black-bean-tacos/', 35, 5, 2, 2, 2, 11, 43, array['beef', 'black beans', 'taco shells', 'cheddar', 'onion', 'garlic']::text[], '{"title":"Crispy Baked Beef Tacos","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/baked-beef-black-bean-tacos/","minutes":35,"servings":5,"key":["Ground beef","Canned black beans","Hard taco shells","Cheddar","Onion","Garlic"],"minor":["Chili powder","Smoked paprika","Ground cumin","Dried oregano","Cayenne pepper","Tomato","Jalapeño","Cilantro","Sour cream"],"amounts":{"Ground beef":"½ lb lean","Canned black beans":"15 oz can","Hard taco shells":"1 box (10 shells)","Cheddar":"1 cup shredded (4 oz)","Onion":"1 yellow onion","Garlic":"2 cloves"},"steps":[["In a small bowl, stir together [[1 tbsp]] chili powder, [[1 tsp]] smoked paprika, [[1 tsp]] ground cumin, [[0.5 tsp]] dried oregano, [[0.25 tsp]] cayenne pepper, [[0.5 tsp]] salt and some freshly cracked black pepper. Set this taco seasoning aside.",null],["Preheat the oven to 400°F.",null],["On a clean cutting board, dice the [[1]] yellow onion and mince the [[2 cloves]] garlic.",null],["Put the onion, garlic and [[1 tbsp]] cooking oil in a large skillet. Sauté over medium heat for about 5 minutes, until the onion is soft and translucent.",5],["Add [[0.5 lb]] ground beef and all of the taco seasoning to the same skillet. Keep sautéing for another 5 minutes, until the beef is cooked through.",5],["Stand the [[10]] taco shells upright in a casserole dish.",null],["Drain the [[15 oz can]] black beans well, but don''t rinse them; a little sauciness keeps the beef moist. Stir them into the beef in the skillet and let them heat through.",null],["Fill the taco shells with the beef and bean mixture, then sprinkle [[1 cup]] shredded cheddar over the top.",null],["Bake in the preheated oven for 7-10 minutes, until the cheese is melted and the shells are golden brown on the edges.",7],["While the tacos bake, dice the [[1]] tomato, slice the [[1]] jalapeño and roughly chop [[1 handful]] cilantro leaves on a clean cutting board.",null],["Sprinkle the tomato, jalapeño and cilantro over the baked tacos and add a dollop of sour cream (about [[0.25 cup]] total) just before serving.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":339,"protein_g":24,"carbs_g":26,"fat_g":16},"video":"https://www.youtube.com/watch?v=MU50rxvgCfA","country":"MX","effort_steps":6,"ingredients":[{"item":"chili powder","qty":1,"unit":"tbsp","group":"Taco Seasoning"},{"item":"smoked paprika","qty":1,"unit":"tsp","group":"Taco Seasoning"},{"item":"ground cumin","qty":1,"unit":"tsp","group":"Taco Seasoning"},{"item":"dried oregano","qty":0.5,"unit":"tsp","group":"Taco Seasoning"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp","group":"Taco Seasoning"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Taco Seasoning"},{"item":"black pepper","note":"freshly cracked","group":"Taco Seasoning"},{"item":"cooking oil","qty":1,"unit":"tbsp","group":"Tacos"},{"item":"yellow onion","qty":1,"note":"diced","group":"Tacos"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Tacos"},{"item":"lean ground beef","qty":0.5,"unit":"lb","note":"93% lean or higher","group":"Tacos"},{"item":"black beans","qty":1,"unit":"can (15 oz)","note":"drained well, not rinsed","group":"Tacos"},{"item":"hard taco shells","qty":1,"unit":"box","note":"10 shells","group":"Tacos"},{"item":"shredded cheddar","qty":1,"unit":"cup","note":"4 oz","group":"Tacos"},{"item":"tomato","qty":1,"note":"diced","group":"Optional Toppings"},{"item":"jalapeño","qty":1,"note":"sliced","group":"Optional Toppings"},{"item":"fresh cilantro","qty":1,"unit":"handful","note":"roughly chopped","group":"Optional Toppings"},{"item":"sour cream","qty":0.25,"unit":"cup","group":"Optional Toppings"}]}'::jsonb),
('www-recipetineats-com-spaghetti-bolognese', 'Spaghetti Bolognese', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/spaghetti-bolognese/', 40, 5, 4, 2, 2, 13, 56, array['beef', 'pasta', 'tomatoes', 'onion', 'garlic', 'red wine', 'tomato paste']::text[], '{"title":"Spaghetti Bolognese","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/spaghetti-bolognese/","minutes":40,"servings":5,"key":["Ground beef","Spaghetti","Canned crushed tomatoes","Onion","Garlic","Red wine","Tomato paste"],"minor":["Beef bouillon cubes","Worcestershire sauce","Bay leaves","Fresh thyme","Parmesan","Parsley"],"amounts":{"Ground beef":"1 lb (500g)","Spaghetti":"400g (13 oz)","Canned crushed tomatoes":"800g (28 oz) can","Onion":"1","Garlic":"2 cloves","Red wine":"½ cup (125 ml)","Tomato paste":"2 tbsp"},"steps":[["On a clean cutting board, finely chop the [[1]] onion and mince the [[2 cloves]] garlic.",null],["Heat [[1.5 tbsp]] olive oil in a large pot or deep skillet over medium-high heat.",null],["Add the onion and garlic and cook for 3 minutes, until light golden and softened.",3],["Turn the heat up to high and add [[1 lb]] ground beef. Cook, breaking it up with your spoon as you go, until it''s all browned.",null],["Pour in [[0.5 cup]] red wine. Bring it to a simmer and cook for 1 minute, scraping the bottom of the pot, until the alcohol smell is gone.",1],["Add [[2]] crumbled bouillon cubes, [[28 oz can]] crushed tomato, [[2 tbsp]] tomato paste, [[2 tsp]] Worcestershire sauce, [[2]] bay leaves, [[2 sprigs]] thyme, [[0.75 tsp]] salt and [[0.5 tsp]] black pepper to the pot. Add up to [[2 tsp]] sugar only if needed. Stir well.",null],["Bring the sauce to a simmer, then turn the heat down to medium so it bubbles gently. Cook with no lid for 20-30 minutes, stirring occasionally, and add a splash of water if it gets too thick for your taste.",20],["Taste the sauce and add more salt if you like.",null],["While the sauce simmers, bring a large pot of salted water to a boil. Add [[400 g]] spaghetti and cook for 1 minute less than the packet says.",null],["Scoop out a mug of the pasta cooking water and set it aside, then drain the pasta.",null],["Add the drained pasta into the pot of bolognese sauce with about [[0.5 cup]] of the reserved pasta water, over medium heat.",null],["Toss gently for 1 1/2-2 minutes, until the spaghetti turns red and the sauce thickens.",1.5],["Divide between bowls and garnish with Parmesan and parsley if you like.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":510,"protein_g":41,"carbs_g":53,"fat_g":13},"video":null,"country":"IT","effort_steps":6,"ingredients":[{"item":"olive oil","qty":1.5,"unit":"tbsp"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"onion","qty":1,"note":"finely chopped (brown, yellow or white)"},{"item":"beef mince (ground beef)","qty":1,"unit":"lb","note":"500g; or half pork, half beef"},{"item":"dry red wine","qty":0.5,"unit":"cup","note":"125 ml; sub water or beef broth/stock"},{"item":"beef bouillon cubes","qty":2,"note":"crumbled, or granulated beef bouillon"},{"item":"crushed tomato","qty":1,"unit":"can (28 oz / 800g)","note":"or tomato passata"},{"item":"tomato paste","qty":2,"unit":"tbsp"},{"item":"white sugar","qty":2,"unit":"tsp","note":"if needed"},{"item":"Worcestershire sauce","qty":2,"unit":"tsp"},{"item":"dried bay leaves","qty":2},{"item":"fresh thyme","qty":2,"unit":"sprig","note":"or 1/2 tsp dried thyme or oregano"},{"item":"cooking salt (kosher salt)","qty":0.75,"unit":"tsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"spaghetti","qty":400,"unit":"g","note":"dried; 13 oz","group":"To Serve"},{"item":"Parmesan cheese and finely chopped parsley","note":"optional","group":"To Serve"}]}'::jsonb),
('www-recipetineats-com-aglio-e-olio-garlic-spaghetti', 'Aglio e Olio (Spaghetti with garlic olive oil)', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/', 18, 4, 4, 1, 3, 10, 50, array['pasta', 'garlic', 'oil', 'parmesan']::text[], '{"title":"Aglio e Olio (Spaghetti with garlic olive oil)","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/","minutes":18,"servings":4,"key":["Spaghetti","Garlic","Olive oil","Parmesan"],"minor":["Red chili flakes","Parsley"],"amounts":{"Spaghetti":"500g / 1 lb","Garlic":"6 large cloves, finely sliced","Olive oil":"½ cup extra virgin","Parmesan":"for serving"},"steps":[["On a clean cutting board, finely slice the [[6 large]] garlic cloves and finely chop [[0.333 cup]] parsley.",null],["Bring 4 litres/quarts of water to a boil in a large pot. Add [[2 tsp]] salt and [[500 g]] spaghetti, and cook for 1 minute less than the packet directions.",null],["About 4 minutes before the pasta is done, heat [[0.5 cup]] olive oil in a large (about 30cm/12\") deep pan over medium heat.",null],["Add the garlic to the pan and sauté gently for 2-3 minutes, until very light golden.",2],["Add [[0.5 tsp]] chilli flakes and stir for 20-30 seconds, until the garlic is light golden. Don''t let it brown.",null],["Just before draining, scoop out 1 cup of the pasta cooking water and set it aside. Then drain the pasta.",null],["Add the drained pasta to the garlic pan along with [[0.5 cup]] of the reserved pasta water and [[1 tsp]] salt.",null],["Toss over medium-high heat for 1-1 1/2 minutes, until the water and oil combine into a sauce that coats the pasta.",1],["Add the parsley and toss quickly. The pasta should look slippery and slick.",null],["Serve right away with grated Parmesan. If the pasta turns sticky, add another splash of pasta water and toss to loosen it.",null]],"technique":4,"prep":1,"precision":3,"nutrition":{"calories":564,"protein_g":13,"carbs_g":75,"fat_g":23},"video":null,"country":"IT","effort_steps":6,"ingredients":[{"item":"spaghetti","qty":500,"unit":"g","note":"1 lb; No. 5 or any long strand pasta","group":"Main"},{"item":"cooking salt/kosher salt","qty":2,"unit":"tsp","note":"for cooking pasta (halve for table salt, +50% for flakes)","group":"Main"},{"item":"extra virgin olive oil","qty":0.5,"unit":"cup","group":"Garlic Oil Sauce"},{"item":"garlic cloves","qty":6,"unit":"large","note":"finely sliced","group":"Garlic Oil Sauce"},{"item":"red chilli flakes","qty":0.5,"unit":"tsp","note":"optional; sub a pinch of black pepper for non-spicy","group":"Garlic Oil Sauce"},{"item":"cooking salt/kosher salt","qty":1,"unit":"tsp","note":"halve for table salt, +50% for flakes","group":"Garlic Oil Sauce"},{"item":"parsley","qty":0.333,"unit":"cup","note":"finely chopped","group":"Garlic Oil Sauce"},{"item":"reserved pasta cooking water","qty":0.5,"unit":"cup","group":"Garlic Oil Sauce"},{"item":"Parmesan or parmigiano reggiano","note":"finely grated","group":"For Serving"}]}'::jsonb),
('www-recipetineats-com-lasagna', 'Lasagna!', 'Italian', 'RecipeTin Eats', 'https://www.recipetineats.com/lasagna/', 260, 10, 4, 4, 3, 20, 87, array['beef', 'lasagna sheets', 'tomatoes', 'milk', 'butter', 'flour', 'mozzarella']::text[], '{"title":"Lasagna!","cuisine":"Italian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/lasagna/","minutes":260,"servings":10,"key":["Ground beef","Lasagna sheets","Canned crushed tomatoes","Milk","Butter","Flour","Mozzarella"],"minor":["Onion","Carrot","Celery","Garlic","Tomato paste","Red wine","Beef bouillon cubes","Bay leaves","Dried thyme","Dried oregano","Worcestershire sauce","Gruyere or cheddar","Nutmeg","Basil or parsley"],"amounts":{"Ground beef":"1 kg","Lasagna sheets":"350g fresh (or 250g dried)","Canned crushed tomatoes":"800g","Milk":"4 cups","Butter":"60g","Flour":"½ cup","Mozzarella":"1½ cups shredded"},"steps":[["On a clean cutting board, finely chop the [[1]] onion, peel and very finely dice the [[1 medium]] carrot, very finely dice the [[1]] celery stick, and mince the [[2 cloves]] garlic.",null],["Heat [[1 tbsp]] olive oil in a large heavy-based pot over medium heat. Add the garlic, onion, celery and carrot.",null],["Cook for 10 minutes, until softened and sweet. They should not brown; if they do, turn the heat down.",10],["Add [[1 kg]] ground beef, turn the heat up, and cook, breaking it up as you go, until it has all turned brown.",null],["Add [[800 g]] crushed tomato, [[0.25 cup]] tomato paste, [[1 cup]] red wine, [[3]] crumbled bouillon cubes, [[2]] bay leaves, [[0.5 tsp]] dried thyme, [[0.5 tsp]] dried oregano, [[2 tsp]] Worcestershire sauce, [[0.5 tsp]] salt and [[0.5 tsp]] pepper to the pot. Save the sugar for later.",null],["Stir, then adjust the heat so the sauce bubbles very gently. Put the lid on and cook for 1.5-2 hours, stirring every now and then.",90],["Remove the lid and simmer for 30 minutes more. The ragu is ready when the meat is really tender and the sauce is thick and rich.",30],["Taste the ragu, adjust the salt and pepper, and stir in [[1 tsp]]-[[2 tsp]] sugar only if it needs it.",null],["For the cheese sauce, warm [[4 cups]] milk in a saucepan (optional, it just helps the sauce thicken faster).",null],["In a new large saucepan, melt [[60 g]] butter over medium-low heat. Add [[0.5 cup]] flour and stir constantly for 1 minute.",1],["Pour in about 1 cup of the milk, mixing as you go. Once it''s mostly lump free, add the rest of the milk, using a whisk if needed to get rid of lumps.",null],["Turn the heat up to medium-high. Stir occasionally at first, then regularly after a few minutes, until the sauce thickens and coats the back of a wooden spoon, about 5-8 minutes.",5],["Take the saucepan off the heat and stir in [[2 cups]] shredded cheese, [[1 pinch]] nutmeg, and salt and pepper until the cheese melts. It should be thick but still easy to pour, like heavy cream.",null],["Preheat the oven to 350°F (180°C). Get out a 13 x 9 x 2.5-inch (33 x 22 x 7 cm) baking dish.",null],["Smear a little ragu on the bottom of the baking dish, then cover it with lasagna sheets, tearing them to fit.",null],["Spread [[2.5 cups]] ragu over the sheets, then drizzle [[1 cup]] cheese sauce over it.",null],["Top with more lasagna sheets, spread on another [[2.5 cups]] ragu and [[1 cup]] cheese sauce. Add another layer of sheets and repeat the ragu and cheese sauce one more time.",null],["Top with a 4th layer of lasagna sheets, then pour over all the remaining cheese sauce.",null],["Sprinkle [[1.5 cups]] mozzarella over the top and bake for 25 minutes, until golden and bubbling.",25],["Let the lasagna stand for 5-10 minutes before cutting. Garnish with basil or parsley if you like.",5]],"technique":4,"prep":4,"precision":3,"nutrition":{"calories":594,"protein_g":39,"carbs_g":40,"fat_g":29},"video":null,"country":"IT","effort_steps":8,"ingredients":[{"item":"olive oil","qty":1,"unit":"tbsp","group":"Ragu Bolognese"},{"item":"onion","qty":1,"note":"finely chopped (white, yellow or brown)","group":"Ragu Bolognese"},{"item":"carrot","qty":1,"unit":"medium","note":"peeled and very finely diced","group":"Ragu Bolognese"},{"item":"celery stick","qty":1,"note":"very finely diced","group":"Ragu Bolognese"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Ragu Bolognese"},{"item":"beef mince (ground beef)","qty":1,"unit":"kg","note":"2 lb","group":"Ragu Bolognese"},{"item":"canned crushed tomato","qty":800,"unit":"g","note":"28 oz","group":"Ragu Bolognese"},{"item":"tomato paste","qty":0.25,"unit":"cup","group":"Ragu Bolognese"},{"item":"pinot noir red wine","qty":1,"unit":"cup","note":"or other dry red wine","group":"Ragu Bolognese"},{"item":"beef bouillon cubes","qty":3,"note":"crumbled","group":"Ragu Bolognese"},{"item":"bay leaves","qty":2,"note":"dried or fresh","group":"Ragu Bolognese"},{"item":"dried thyme","qty":0.5,"unit":"tsp","group":"Ragu Bolognese"},{"item":"dried oregano","qty":0.5,"unit":"tsp","group":"Ragu Bolognese"},{"item":"Worcestershire sauce","qty":2,"unit":"tsp","group":"Ragu Bolognese"},{"item":"sugar","qty":1,"qtyMax":2,"unit":"tsp","note":"if needed","group":"Ragu Bolognese"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Ragu Bolognese"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Ragu Bolognese"},{"item":"butter","qty":60,"unit":"g","note":"4 tbsp","group":"Cheese Sauce (Besciamella)"},{"item":"flour","qty":0.5,"unit":"cup","group":"Cheese Sauce (Besciamella)"},{"item":"milk","qty":4,"unit":"cup","note":"preferably full fat but low fat ok","group":"Cheese Sauce (Besciamella)"},{"item":"gruyere or Colby cheese","qty":2,"unit":"cup","note":"shred yourself (or cheddar, Monterey Jack, or 1 cup / 100g shredded parmesan)","group":"Cheese Sauce (Besciamella)"},{"item":"freshly ground nutmeg","qty":1,"unit":"pinch","group":"Cheese Sauce (Besciamella)"},{"item":"salt and pepper","group":"Cheese Sauce (Besciamella)"},{"item":"fresh lasagna sheets","qty":350,"unit":"g","note":"12 oz (or 250g/8oz dried)","group":"Lasagna"},{"item":"mozzarella cheese","qty":1.5,"unit":"cup","note":"tightly packed, shred yourself","group":"Lasagna"},{"item":"basil or parsley","note":"finely chopped, for garnish (optional)","group":"Lasagna"}]}'::jsonb),
('www-foodnetwork-com-recipes-tortilla-espanola-spanish-omelet', 'Tortilla Espanola: Spanish Omelette', 'Spanish', 'Food Network', 'https://www.foodnetwork.com/recipes/tortilla-espanola-spanish-omelette-recipe-1938426', 35, 4, 3, 2, 4, 11, 53, array['potatoes', 'eggs', 'onion']::text[], '{"title":"Tortilla Espanola: Spanish Omelette","cuisine":"Spanish","source":"Food Network","url":"https://www.foodnetwork.com/recipes/tortilla-espanola-spanish-omelette-recipe-1938426","minutes":35,"servings":4,"key":["Potatoes","Eggs","Onion"],"minor":["Green olives"],"amounts":{"Potatoes":"3 large, peeled and thinly sliced","Eggs":"3 large","Onion":"1, finely chopped"},"steps":[["On a clean cutting board, peel and thinly slice the [[3 large]] potatoes, and peel and finely chop the [[1]] onion.",null],["Crack the [[3 large]] eggs into a bowl, whisk with a fork, and add a pinch of salt.",null],["Heat [[3 tbsp]]-[[4 tbsp]] olive oil in a frying pan. Avoid a heavy-based pan, since it makes the flip harder later.",null],["Add the potato slices and fry for a couple of minutes.",2],["Add the onion to the same pan and mash it together with the potato.",null],["When the potato starts browning a little on the edges and is mashed up with the onion in a lumpy way, pour in the eggs. Make sure the potato and onion are fully covered, and poke the potato so some egg seeps in.",null],["Fry gently on low heat, shaking the pan to loosen the tortilla from the bottom and tidying the edges with a wooden spoon. Don''t overcook it; the middle should stay runny and gooey.",null],["As the egg starts to set, put a large plate over the pan, big enough to cover it well. With a quick, coordinated twist of both wrists, flip the tortilla onto the plate.",null],["Slide the tortilla back into the pan to cook the underside, shaking the pan lightly so it doesn''t stick.",null],["Once it feels firm on the edges and soft in the middle (after about 1 minute), slide it back onto the plate. You can flip it again if you''re feeling brave.",1],["Let the tortilla rest for about 5-10 minutes. Cut it into cake slices or cubes and garnish with green olives.",5]],"technique":3,"prep":2,"precision":4,"nutrition":null,"video":null,"country":"ES","effort_steps":6,"ingredients":[{"item":"eggs","qty":3,"unit":"large"},{"item":"salt","note":"to taste"},{"item":"olive oil","qty":3,"qtyMax":4,"unit":"tbsp"},{"item":"potatoes","qty":3,"unit":"large","note":"peeled and thinly sliced"},{"item":"onion","qty":1,"note":"peeled and finely chopped"},{"item":"green olives","note":"for garnish"}]}'::jsonb),
('www-recipetineats-com-coq-au-vin', 'Coq au Vin', 'French', 'RecipeTin Eats', 'https://www.recipetineats.com/coq-au-vin/', 105, 4, 4, 4, 3, 20, 82, array['chicken', 'red wine', 'bacon', 'mushrooms', 'onion', 'broth']::text[], '{"title":"Coq au Vin","cuisine":"French","source":"RecipeTin Eats","url":"https://www.recipetineats.com/coq-au-vin/","minutes":105,"servings":4,"key":["Chicken thighs","Chicken drumsticks","Red wine","Bacon","Mushrooms","Pearl onions","Beef stock"],"minor":["Bay leaf","Thyme","Butter","Garlic","Tomato paste","Flour","Parsley"],"amounts":{"Chicken thighs":"4, bone-in skin-on","Chicken drumsticks":"4","Red wine":"750 ml","Bacon":"150g","Mushrooms":"400g","Pearl onions":"16","Beef stock":"750 ml"},"steps":[["Place the [[4]] chicken thighs, [[4]] drumsticks, [[16]] pearl onions, [[1]] bay leaf, [[3 sprigs]] thyme and [[750 ml]] red wine in a large glass or ceramic bowl.",null],["Cover and marinate overnight in the fridge, at least 12 hours and no more than 24 hours.",720],["Strain the red wine into a saucepan. Keep the herbs and the wine separate from the chicken and onions.",null],["Spread the chicken on a tray lined with paper towels and pat it dry with more paper towels.",null],["Bring the wine in the saucepan to a boil over medium-high heat. Let it simmer hard, skimming off any foam, until it''s reduced by half. Set aside.",null],["While the wine reduces, cut the [[150 g]] bacon into 1 x 2.5cm (0.4 x 1\") batons, halve the [[400 g]] mushrooms (quarter large ones), and finely mince the [[3 cloves]] garlic on a clean cutting board.",null],["Preheat the oven to 350°F (180°C; 160°C fan).",null],["Sprinkle the chicken with [[0.75 tsp]] salt and [[0.5 tsp]] black pepper.",null],["Heat [[3 tbsp]] oil in a large, heavy-based, oven-proof pot (26cm/10.5\" or larger) over medium-high heat. Add the thighs skin side down and cook for 2-3 minutes until deeply browned, then flip and cook 1 minute. Move them to a tray.",2],["Brown the drumsticks in the same pot for about 5 minutes total, turning them to brown 3-4 sides. Move them to the tray.",5],["Remove any loose burnt black bits from the pot. Add a little extra oil if needed, then cook the bacon for 3 minutes until golden. Add it to the tray with the chicken.",3],["Add the mushrooms to the same pot and cook for 5 minutes until golden. Remove them into a separate bowl.",5],["Add extra oil if needed, then cook the pearl onions for 5 minutes, until golden patches appear.",5],["Add [[60 g]] butter to the pot. Once it melts, add the garlic and cook for 1 minute.",1],["Add [[2 tbsp]] tomato paste and cook for 2 minutes, then add [[7 tbsp]] flour and cook for 2 minutes more.",2],["While stirring, slowly pour in [[750 ml]] beef stock so the flour dissolves without lumps. Then add the reduced wine and mix until it''s mostly lump-free.",null],["Return the chicken, bacon and mushrooms to the pot, along with the thyme, bay leaf, [[0.25 tsp]] salt and [[0.25 tsp]] pepper. Stir.",null],["Bring to a simmer, put the lid on, and transfer the pot to the oven for 45 minutes. The chicken will be very tender but not falling apart.",45],["Take the pot out of the oven, taste the sauce, and add salt if needed. If you have time, you can leave the stew overnight and reheat it gently, covered, on low on the stove, adding water if the sauce needs loosening.",null],["Serve over mashed potato or tagliatelle, sprinkled with [[2 tbsp]] chopped parsley.",null]],"technique":4,"prep":4,"precision":3,"nutrition":{"calories":977,"protein_g":59,"carbs_g":32,"fat_g":54},"video":null,"country":"FR","effort_steps":7,"ingredients":[{"item":"chicken thighs","qty":4,"note":"bone-in, skin on (~220g/7 oz each)","group":"Red Wine Chicken Marinade"},{"item":"chicken drumsticks","qty":4,"group":"Red Wine Chicken Marinade"},{"item":"pearl onions or pickling onions","qty":16,"group":"Red Wine Chicken Marinade"},{"item":"bay leaf","qty":1,"note":"fresh (dry also ok)","group":"Red Wine Chicken Marinade"},{"item":"thyme","qty":3,"unit":"sprig","note":"sub 1 tsp dried thyme","group":"Red Wine Chicken Marinade"},{"item":"pinot noir red wine or other dry red wine","qty":750,"unit":"ml","note":"3 cups","group":"Red Wine Chicken Marinade"},{"item":"vegetable oil (or canola oil)","qty":3,"qtyMax":4,"unit":"tbsp","group":"Browning Chicken"},{"item":"salt","qty":0.75,"unit":"tsp","note":"cooking/kosher salt, or 1/2 tsp table salt","group":"Browning Chicken"},{"item":"pepper","qty":0.5,"unit":"tsp","group":"Browning Chicken"},{"item":"white mushrooms","qty":400,"unit":"g","note":"14 oz; halved (quartered if large)","group":"Coq au Vin Stew"},{"item":"bacon piece","qty":150,"unit":"g","note":"5 oz; cut into 1 x 2.5cm/0.4 x 1\" batons","group":"Coq au Vin Stew"},{"item":"unsalted butter","qty":60,"unit":"g","note":"4 tbsp","group":"Coq au Vin Stew"},{"item":"garlic","qty":3,"unit":"clove","note":"finely minced","group":"Coq au Vin Stew"},{"item":"tomato paste","qty":2,"unit":"tbsp","group":"Coq au Vin Stew"},{"item":"flour","qty":7,"unit":"tbsp","note":"plain/all purpose","group":"Coq au Vin Stew"},{"item":"beef stock","qty":750,"unit":"ml","note":"3 cups; low sodium, preferably homemade","group":"Coq au Vin Stew"},{"item":"salt","qty":0.25,"unit":"tsp","note":"cooking/kosher salt, or 1/8 tsp table salt","group":"Coq au Vin Stew"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Coq au Vin Stew"},{"item":"parsley","qty":2,"unit":"tbsp","note":"chopped","group":"Garnish and Serving"},{"item":"mashed potato (or tagliatelle)","group":"Garnish and Serving"}]}'::jsonb),
('www-recipetineats-com-chicken-souvlaki', 'Chicken Souvlaki with Tzatziki', 'Greek', 'RecipeTin Eats', 'https://www.recipetineats.com/chicken-souvlaki/', 25, 4, 3, 3, 2, 10, 47, array['chicken', 'lemon', 'garlic', 'yogurt', 'cucumber', 'pita']::text[], '{"title":"Chicken Souvlaki with Tzatziki","cuisine":"Greek","source":"RecipeTin Eats","url":"https://www.recipetineats.com/chicken-souvlaki/","minutes":25,"servings":4,"key":["Chicken thighs","Lemon","Garlic","Greek yogurt","Cucumber","Pita bread"],"minor":["Dried oregano","White wine vinegar","Lettuce","Tomato"],"amounts":{"Chicken thighs":"1.5 lb (750 g), cut in 1-inch pieces","Lemon":"¼ cup juice + 1 tbsp","Garlic":"3 cloves + ½ clove","Greek yogurt":"1¼ cups (300 g)","Cucumber":"2 Lebanese cucumbers","Pita bread":"flatbreads/wraps/pita to serve"},"steps":[["On a clean cutting board, cut [[1.5 lb]] chicken into 1-inch (2.5cm) pieces, and mince [[3 cloves]] garlic for the marinade plus [[0.5 clove]] for the tzatziki (keep them separate).",null],["In a bowl, combine the chicken with [[2 tbsp]] olive oil, [[0.25 cup]] lemon juice, the [[3 cloves]] minced garlic, [[2 tbsp]] dried oregano, [[0.5 tsp]]-[[0.75 tsp]] salt and some black pepper.",null],["Set the chicken aside to marinate for at least 3 hours, or up to overnight.",180],["For the tzatziki, cut the [[2]] cucumbers in half lengthwise and scrape out the watery seeds with a teaspoon.",null],["Coarsely grate the cucumber on a box grater, then wrap it in paper towels or a tea towel and squeeze out the extra liquid.",null],["Put the cucumber in a new bowl. Add [[1.25 cups]] Greek yoghurt, [[2 tsp]] white wine vinegar, [[1 tbsp]] lemon juice, the [[0.5 clove]] minced garlic, [[1 tbsp]] extra virgin olive oil, [[0.5 tsp]] salt and some black pepper. Mix to combine.",null],["Set the tzatziki aside for at least 20 minutes so the flavours meld.",20],["Thread the marinated chicken onto 8 skewers.",null],["Heat [[1 tbsp]] olive oil in a large skillet over high heat (or use a BBQ). Cook the skewers for 3 minutes on each side, or until cooked through.",6],["Serve the souvlaki with the tzatziki, flatbreads, lettuce and tomato slices.",null]],"technique":3,"prep":3,"precision":2,"nutrition":{"calories":367,"protein_g":50,"carbs_g":3,"fat_g":16},"video":null,"country":"GR","effort_steps":5,"ingredients":[{"item":"chicken thigh fillets (or breast)","qty":1.5,"unit":"lb","note":"750 g; cut into 1\"/2.5cm pieces","group":"Marinade"},{"item":"olive oil","qty":2,"unit":"tbsp","group":"Marinade"},{"item":"lemon juice","qty":0.25,"unit":"cup","group":"Marinade"},{"item":"garlic","qty":3,"unit":"clove","note":"minced","group":"Marinade"},{"item":"dried oregano","qty":2,"unit":"tbsp","group":"Marinade"},{"item":"salt","qty":0.5,"qtyMax":0.75,"unit":"tsp","group":"Marinade"},{"item":"black pepper","group":"Marinade"},{"item":"olive oil","qty":1,"unit":"tbsp","group":"To Cook / Serve"},{"item":"flatbreads / wraps / pita bread","group":"To Cook / Serve"},{"item":"lettuce","group":"To Cook / Serve"},{"item":"tomato slices","group":"To Cook / Serve"},{"item":"Lebanese cucumbers","qty":2,"note":"to make about 1/2 cup grated cucumber after squeezing out juice","group":"Tzatziki"},{"item":"plain Greek yoghurt","qty":1.25,"unit":"cup","note":"300 g","group":"Tzatziki"},{"item":"white wine vinegar","qty":2,"unit":"tsp","note":"or red wine or apple cider vinegar","group":"Tzatziki"},{"item":"lemon juice","qty":1,"unit":"tbsp","group":"Tzatziki"},{"item":"garlic","qty":0.5,"unit":"clove","note":"minced","group":"Tzatziki"},{"item":"extra virgin olive oil","qty":1,"unit":"tbsp","note":"or more if you want richer","group":"Tzatziki"},{"item":"salt","qty":0.5,"unit":"tsp","group":"Tzatziki"},{"item":"black pepper","group":"Tzatziki"}]}'::jsonb),
('www-budgetbytes-com-falafel', 'Easy Homemade Falafel', 'Mediterranean', 'Budget Bytes', 'https://www.budgetbytes.com/falafel/', 100, 19, 4, 3, 3, 10, 74, array['chickpeas', 'onion', 'garlic', 'flour', 'parsley', 'cilantro']::text[], '{"title":"Easy Homemade Falafel","cuisine":"Mediterranean","source":"Budget Bytes","url":"https://www.budgetbytes.com/falafel/","minutes":100,"servings":19,"key":["Canned chickpeas","Red onion","Garlic","Flour","Parsley","Cilantro"],"minor":["Ground cumin","Cayenne pepper","Baking powder"],"amounts":{"Canned chickpeas":"2 (15 oz) cans","Red onion":"¼","Garlic":"4 cloves","Flour":"½ cup","Parsley":"1 handful (about ¼ bunch)","Cilantro":"1 handful (about ¼ bunch)"},"steps":[["Rinse and drain the [[2 cans (15 oz)]] chickpeas in a colander.",null],["Put the chickpeas in a food processor with [[0.25]] red onion, [[1 handful]] parsley, [[1 handful]] cilantro, [[1 tsp]] salt, [[0.5 tsp]] cayenne, [[4 cloves]] garlic and [[1 tsp]] cumin.",null],["Process until it forms a chunky paste, scraping down the sides of the bowl now and then so the texture is even.",null],["Move the mixture into a bowl and stir in [[1 tsp]] baking powder.",null],["Add up to [[0.5 cup]] flour, 2 tbsp at a time, until the mixture holds together enough to form patties and doesn''t stick to your hands.",null],["Refrigerate the mixture for at least 1 hour.",60],["Using a small measuring cup or scoop (about 1/8 cup or 2 tbsp), shape the mixture into small patties.",null],["Optional: to freeze some, lay the patties on a parchment-lined baking sheet to freeze without sticking together, then move them to an airtight container or freezer bag.",null],["Heat [[0.25 cup]] oil in a skillet until it''s very hot and shimmering, but not smoking.",null],["Cook the patties on each side until they''re deep golden brown and crispy.",null]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":108,"protein_g":4,"carbs_g":14,"fat_g":4},"video":"https://www.youtube.com/watch?v=QS2V0pBCDeY","country":"EG","effort_steps":5,"ingredients":[{"item":"chickpeas","qty":2,"unit":"can (15 oz)"},{"item":"red onion","qty":0.25},{"item":"fresh parsley","qty":1,"unit":"handful","note":"about 1/4 bunch"},{"item":"fresh cilantro","qty":1,"unit":"handful","note":"about 1/4 bunch"},{"item":"garlic","qty":4,"unit":"clove"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"cayenne pepper","qty":0.5,"unit":"tsp"},{"item":"ground cumin","qty":1,"unit":"tsp"},{"item":"baking powder","qty":1,"unit":"tsp"},{"item":"flour","qty":0.5,"unit":"cup"},{"item":"neutral cooking oil","qty":0.25,"unit":"cup","note":"for frying"}]}'::jsonb),
('thewoksoflife-com-stir-fried-tomato-and-egg', 'Chinese Tomato Egg Stir-fry (番茄炒鸡蛋)', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/stir-fried-tomato-and-egg/', 10, 2, 2, 1, 1, 11, 32, array['eggs', 'tomatoes', 'scallions']::text[], '{"title":"Chinese Tomato Egg Stir-fry (番茄炒鸡蛋)","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/stir-fried-tomato-and-egg/","minutes":10,"servings":2,"key":["Eggs","Tomatoes","Scallions"],"minor":["White pepper","Sesame oil","Shaoxing wine"],"amounts":{"Eggs":"4","Tomatoes":"4 small to medium (about 1 lb)","Scallions":"1"},"steps":[["On a clean cutting board, cut the [[4]] tomatoes into small wedges.",null],["Finely chop the [[1]] scallion and keep it with the tomatoes.",null],["Crack the [[4]] eggs into a new bowl and season them with [[1/4 tsp]] salt, [[1/4 tsp]] white pepper, [[1/2 tsp]] sesame oil and [[1 tsp]] Shaoxing wine.",null],["Beat the eggs in that bowl for a minute.",1],["Preheat your wok over medium heat until it just starts to smoke.",null],["Add [[2 tbsp]] of the oil to the wok and immediately pour in the beaten eggs. Scramble them, then take them out of the wok right away and set them aside.",null],["Add [[1 tbsp]] more oil to the same wok, turn the heat up to high, and add the tomatoes and scallions. Stir-fry for 1 minute.",1],["Add [[2 tsp]] sugar, [[1/2 tsp]] salt and [[1/4 cup]] water to the wok. If your stove gets very hot and liquid cooks off quickly, add a little more water.",null],["Add the cooked eggs back into the wok and mix everything together.",null],["Cover the wok and cook for 1-2 minutes, until the tomatoes are completely softened.",1],["Uncover and keep stir-frying over high heat until the sauce thickens to your liking. Serve!",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":333,"protein_g":11,"carbs_g":6,"fat_g":30},"video":null,"country":"CN","effort_steps":6,"ingredients":[{"item":"tomatoes","qty":4,"unit":"small to medium","note":"about 500 g, 1 pound"},{"item":"scallion","qty":1},{"item":"eggs","qty":4},{"item":"salt","qty":0.75,"unit":"tsp","note":"divided, or to taste"},{"item":"white pepper","qty":0.25,"unit":"tsp"},{"item":"sesame oil","qty":0.5,"unit":"tsp"},{"item":"Shaoxing wine","qty":1,"unit":"tsp"},{"item":"vegetable oil","qty":3,"unit":"tbsp","note":"divided"},{"item":"sugar","qty":2,"unit":"tsp"},{"item":"water","qty":0.25,"qtyMax":0.5,"unit":"cup"}]}'::jsonb),
('thewoksoflife-com-kung-pao-chicken', 'Kung Pao Chicken: An Authentic Chinese Recipe', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/kung-pao-chicken/', 40, 4, 3, 3, 3, 12, 57, array['chicken', 'peanuts', 'scallions', 'garlic', 'soy sauce']::text[], '{"title":"Kung Pao Chicken: An Authentic Chinese Recipe","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/kung-pao-chicken/","minutes":40,"servings":4,"key":["Chicken breast","Peanuts","Scallions","Garlic","Soy sauce"],"minor":["Ginger","Dried red chilies","Sichuan peppercorn powder","Shaoxing wine","Dark soy sauce","Rice vinegar","Cornstarch","White pepper"],"amounts":{"Chicken breast":"12 oz","Peanuts":"1 cup raw, shelled","Scallions":"6 (white parts)","Garlic":"3 cloves","Soy sauce":"1 tbsp light soy sauce"},"steps":[["On a clean cutting board, cut the [[12 oz]] chicken breast into 3/4-inch (2 cm) cubes.",null],["Smash and slice the [[3 cloves]] garlic, mince the [[2 thin slices]] ginger, and deseed and chop the [[2]] dried red chilies.",null],["Cut the white parts of the [[6]] scallions into 3/4-inch (2 cm) pieces.",null],["Heat [[1 tsp]] vegetable oil in a wok over medium heat and add [[1 cup]] raw shelled peanuts. Stir constantly for 3 minutes.",3],["Turn off the heat and keep stirring the peanuts for another minute using the leftover heat. Set them aside to cool until crunchy. (You can use pre-roasted peanuts instead and skip this.)",1],["In a new bowl, mix the chicken with [[1 tsp]] vegetable oil, [[1 tsp]] cornstarch, [[1 tsp]] Shaoxing wine, [[1/8 tsp]] salt and [[1 pinch]] white pepper. Set aside for 20 minutes.",20],["In a new medium bowl, mix [[1 tbsp]] light soy sauce, [[1/2 tsp]] dark soy sauce, [[1 tbsp]] rice wine vinegar, [[1 tsp]] sugar, [[3 tbsp]] water and [[1 tsp]] cornstarch. Set the sauce aside.",null],["Heat [[2 tbsp]] oil in the wok over high heat. Sear the chicken, then move it to a bowl and set aside.",null],["Turn the heat to low and add [[1 tbsp]] more oil to the wok. Add the garlic, ginger, chilies, [[1/2 tsp]] Sichuan peppercorn powder and scallions. Cook for a minute or two until fragrant.",1],["Add the chicken back into the wok, turn the heat to high and stir-fry for a minute.",1],["Stir up the sauce in its bowl (the cornstarch settles to the bottom), pour it into the wok and stir-fry for another minute until thickened.",1],["Add the roasted peanuts, give everything a final stir, and serve.",null]],"technique":3,"prep":3,"precision":3,"nutrition":{"calories":440,"protein_g":29,"carbs_g":11,"fat_g":33},"video":null,"country":"CN","effort_steps":7,"ingredients":[{"item":"vegetable oil","qty":1,"unit":"tsp","group":"To roast the peanuts"},{"item":"raw peanuts","qty":1,"unit":"cup","note":"shelled, with or without the skin","group":"To roast the peanuts"},{"item":"chicken breast","qty":12,"unit":"oz","note":"cut into 3/4-inch (2 cm) cubes","group":"To marinate the chicken"},{"item":"vegetable oil","qty":1,"unit":"tsp","group":"To marinate the chicken"},{"item":"cornstarch","qty":1,"unit":"tsp","group":"To marinate the chicken"},{"item":"Shaoxing wine","qty":1,"unit":"tsp","group":"To marinate the chicken"},{"item":"salt","qty":0.125,"unit":"tsp","group":"To marinate the chicken"},{"item":"white pepper","qty":1,"unit":"pinch","group":"To marinate the chicken"},{"item":"light soy sauce","qty":1,"unit":"tbsp","group":"To prepare the sauce"},{"item":"dark soy sauce","qty":0.5,"unit":"tsp","group":"To prepare the sauce"},{"item":"rice wine vinegar","qty":1,"unit":"tbsp","group":"To prepare the sauce"},{"item":"sugar","qty":1,"unit":"tsp","group":"To prepare the sauce"},{"item":"water","qty":3,"unit":"tbsp","group":"To prepare the sauce"},{"item":"cornstarch","qty":1,"unit":"tsp","group":"To prepare the sauce"},{"item":"oil","qty":3,"unit":"tbsp","group":"The rest of your ingredients"},{"item":"garlic","qty":3,"unit":"clove","note":"smashed and sliced","group":"The rest of your ingredients"},{"item":"ginger","qty":2,"unit":"thin slice","note":"minced","group":"The rest of your ingredients"},{"item":"dried red chilies","qty":2,"note":"deseeded and chopped","group":"The rest of your ingredients"},{"item":"Sichuan peppercorn powder","qty":0.5,"unit":"tsp","group":"The rest of your ingredients"},{"item":"scallions","qty":6,"note":"white portions only, cut into 3/4-inch (2 cm) pieces","group":"The rest of your ingredients"}]}'::jsonb),
('thewoksoflife-com-ma-po-tofu-real-deal', 'Mapo Tofu Recipe: The Real Deal', 'Chinese', 'The Woks of Life', 'https://thewoksoflife.com/ma-po-tofu-real-deal/', 35, 6, 4, 3, 4, 16, 64, array['tofu', 'pork', 'garlic', 'ginger', 'broth', 'scallions']::text[], '{"title":"Mapo Tofu Recipe: The Real Deal","cuisine":"Chinese","source":"The Woks of Life","url":"https://thewoksoflife.com/ma-po-tofu-real-deal/","minutes":35,"servings":6,"key":["Silken tofu","Ground pork","Garlic","Ginger","Chicken broth","Scallions"],"minor":["Thai bird chilies","Dried red chilies","Sichuan peppercorns","Spicy bean sauce (doubanjiang)","Cornstarch","Sesame oil"],"amounts":{"Silken tofu":"1 lb","Ground pork":"8 oz","Garlic":"3 tbsp minced","Ginger":"3 tbsp minced","Chicken broth":"2/3 cup low-sodium","Scallions":"1"},"steps":[["On a clean cutting board, thinly slice the [[1]] fresh Thai bird chili and roughly chop the [[6]] dried red chilies.",null],["Finely mince [[3 tbsp]] ginger and [[3 tbsp]] garlic, and finely chop the [[1]] scallion.",null],["Cut the [[1 lb]] silken tofu into 1 inch (2.5 cm) cubes.",null],["Grind [[1/2 tbsp]] Sichuan peppercorns into a powder, and save 1/4 tsp of it for garnish at the end.",null],["Heat a wok or small saucepan over low heat. Add half of the oil ([[1/4 cup]]) and the fresh and dried chilies.",null],["Stir now and then until fragrant, about 5 minutes, making sure the peppers don''t burn. Remove this chili oil and set it aside.",5],["Heat the remaining [[1/4 cup]] oil in the wok over medium heat. Add the ginger and cook for 1 minute.",1],["Add the garlic and fry for another minute.",1],["Turn the heat to high and add [[8 oz]] ground pork. Break up the meat until it is cooked through.",null],["Add the ground Sichuan peppercorns and stir for 15-30 seconds, without letting them burn.",null],["Add [[1 tbsp]] spicy bean sauce and stir well. Add [[2/3 cup]] chicken broth and simmer for 1 minute.",1],["In a new small bowl, combine [[1/4 cup]] water and [[1 1/2 tsp]] cornstarch.",null],["Add the cornstarch mixture to the sauce in the wok and stir until thickened. If it gets too thick, add more water or stock.",null],["Add the reserved chili oil with its peppers and stir the oil into the sauce. Add the tofu and gently toss. Cook for 3-5 minutes.",3],["Add [[1/4 tsp]] sesame oil, [[1/4 tsp]] sugar and the scallions, and stir until the scallions are wilted.",null],["Serve, garnished with the saved Sichuan peppercorn powder as you like.",null]],"technique":4,"prep":3,"precision":4,"nutrition":{"calories":335,"protein_g":11,"carbs_g":8,"fat_g":29},"video":null,"country":"CN","effort_steps":7,"ingredients":[{"item":"oil","qty":0.5,"unit":"cup","note":"divided"},{"item":"fresh Thai bird chili peppers","qty":1,"qtyMax":2,"note":"thinly sliced"},{"item":"dried red chilies","qty":6,"qtyMax":8,"note":"roughly chopped"},{"item":"Sichuan peppercorns","qty":0.5,"qtyMax":1.5,"unit":"tbsp","note":"powdered or finely ground, reserving 1/4 tsp for garnish; or 1/2-1 tsp for milder flavor"},{"item":"ginger","qty":3,"unit":"tbsp","note":"finely minced"},{"item":"garlic","qty":3,"unit":"tbsp","note":"finely minced"},{"item":"ground pork","qty":8,"unit":"oz"},{"item":"spicy bean sauce","qty":1,"qtyMax":2,"unit":"tbsp"},{"item":"low sodium chicken broth","qty":0.667,"unit":"cup","note":"or water"},{"item":"silken tofu","qty":1,"unit":"lb","note":"cut into 1 inch (2.5 cm) cubes"},{"item":"water","qty":0.25,"unit":"cup"},{"item":"cornstarch","qty":1.5,"unit":"tsp"},{"item":"sesame oil","qty":0.25,"unit":"tsp","note":"optional"},{"item":"sugar","qty":0.25,"unit":"tsp","note":"optional"},{"item":"scallion","qty":1,"note":"finely chopped"}]}'::jsonb),
('www-justonecookbook-com-oyakodon', 'Oyakodon (Chicken and Egg Rice Bowl) 親子丼', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/oyakodon/', 25, 2, 2, 2, 3, 13, 42, array['chicken', 'eggs', 'onion', 'rice', 'soy sauce', 'scallions']::text[], '{"title":"Oyakodon (Chicken and Egg Rice Bowl) 親子丼","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/oyakodon/","minutes":25,"servings":2,"key":["Chicken thighs","Eggs","Onion","Rice","Soy sauce","Scallions"],"minor":["Dashi","Mirin","Sake","Shichimi togarashi","Sansho pepper"],"amounts":{"Chicken thighs":"10 oz boneless, skinless","Eggs":"3-4 large","Onion":"1/2 yellow onion (4 oz)","Rice":"2 servings cooked short-grain","Soy sauce":"2 Tbsp","Scallions":"4 sprigs (or mitsuba)"},"steps":[["In a new bowl, combine [[1/2 cup]] dashi, [[2 tbsp]] soy sauce, [[2 tbsp]] mirin and [[2 tsp]] sugar. Mix until the sugar dissolves.",null],["On a clean cutting board, slice the [[1/2]] yellow onion lengthwise into strips about 1/4 inch (6 mm) wide.",null],["Chop the [[4 sprigs]] mitsuba (or green onion) into 1/2 inch (1.3 cm) pieces.",null],["Trim the [[10 oz]] chicken thighs and cut them at an angle into roughly 3/4-1 inch (2-2.5 cm) square pieces.",null],["Sprinkle the chicken with [[1 tbsp]] sake and set it aside for 5 minutes.",5],["Crack the [[3]] eggs into a new bowl. Using chopsticks, ''cut'' through the egg whites 5-6 times to break them into smaller clumps. Don''t whisk.",null],["With the stove off, spread the onion slices in a single layer in a medium frying pan (11 inches / 28 cm), then pour in the seasonings mixture.",null],["Turn the heat to medium and bring it to a simmer. Add the chicken on top of the onions.",null],["Once simmering, lower the heat to medium-low. Cook uncovered for 5 minutes, flipping the chicken halfway, until the chicken is no longer pink and the onions are tender.",5],["Increase the heat to medium. With the liquid simmering, drizzle two-thirds of the eggs in a circle over the chicken and onions, avoiding the edges of the pan.",null],["When the eggs are still runny but just set, add the remaining one-third of the eggs to the center and edges.",null],["Add the mitsuba on top and cook on medium-low until the egg is done to your liking.",null],["Put the [[2 servings]] steamed rice into bowls. Spoon the chicken and egg over the rice and drizzle with as much sauce as you like. Sprinkle with shichimi togarashi or sansho pepper if you like.",null]],"technique":2,"prep":2,"precision":3,"nutrition":{"calories":537,"protein_g":42,"carbs_g":50,"fat_g":13},"video":"https://www.youtube.com/watch?v=SgIMT1L7kXM","country":"JP","effort_steps":6,"ingredients":[{"item":"yellow onion","qty":0.5,"note":"4 oz, 113 g; peeled"},{"item":"boneless, skinless chicken thighs","qty":10,"unit":"oz","note":"typically 1-2 thighs"},{"item":"sake","qty":1,"unit":"tbsp"},{"item":"eggs","qty":3,"qtyMax":4,"unit":"large","note":"50 g each w/o shell; at room temperature"},{"item":"dashi (Japanese soup stock)","qty":0.5,"unit":"cup","group":"Seasonings"},{"item":"soy sauce","qty":2,"unit":"tbsp","group":"Seasonings"},{"item":"mirin","qty":2,"unit":"tbsp","group":"Seasonings"},{"item":"sugar","qty":2,"unit":"tsp","group":"Seasonings"},{"item":"cooked Japanese short-grain rice","qty":2,"unit":"serving","note":"typically 1 2/3 cups (250 g) per donburi serving","group":"For Serving"},{"item":"mitsuba (Japanese parsley) or green onion/scallion","qty":4,"unit":"sprig","group":"For Serving"},{"item":"shichimi togarashi","note":"optional","group":"For Serving"},{"item":"Japanese sansho pepper","note":"optional","group":"For Serving"}]}'::jsonb),
('www-justonecookbook-com-tonkatsu', 'Tonkatsu (Japanese Pork Cutlet)', 'Japanese', 'Just One Cookbook', 'https://www.justonecookbook.com/tonkatsu/', 30, 2, 4, 3, 4, 13, 63, array['pork', 'panko breadcrumb', 'eggs', 'flour', 'cabbage']::text[], '{"title":"Tonkatsu (Japanese Pork Cutlet)","cuisine":"Japanese","source":"Just One Cookbook","url":"https://www.justonecookbook.com/tonkatsu/","minutes":30,"servings":2,"key":["Pork loin chops","Panko breadcrumbs","Eggs","Flour","Cabbage"],"minor":["Tonkatsu sauce","Sesame seeds","Japanese cucumber"],"amounts":{"Pork loin chops":"2 boneless, 1/2 inch thick (100 g each)","Panko breadcrumbs":"1/2 cup","Eggs":"1 large","Flour":"2 Tbsp all-purpose","Cabbage":"1/4 head green cabbage"},"steps":[["Grind [[1 tbsp]] white sesame seeds and [[1 tbsp]] black sesame seeds in a mortar and pestle.",null],["Divide the ground sesame into small bowls and top with [[4 tbsp]] tonkatsu sauce. This is your dipping sauce.",null],["On a clean cutting board, trim the extra fat from the [[2]] pork chops and cut small slits into the connective tissue on both sides.",null],["Pound the pork with a meat mallet, then season with [[1/2 tsp]] kosher salt and [[1/8 tsp]] black pepper.",null],["Set up a breading station with three shallow trays: [[2 tbsp]] flour in the first, [[1]] egg whisked with [[1/2 tbsp]] oil in the second, and [[1/2 cup]] panko in the third.",null],["Heat [[3 cups]] oil in a deep pot to 340°F (170°C).",null],["Dredge each cutlet in the flour (shake off the extra), then the egg mixture, then the panko. Let them rest for 5-10 minutes.",5],["First fry: cook one cutlet for 1 minute without moving it, then flip and cook 1 more minute. Move it to a wire rack.",2],["Clean the fried crumbs out of the oil. Fry the second cutlet the same way, then let both rest on the rack for 4 minutes.",4],["Second fry: raise the oil temperature to 355°F (180°C).",null],["Fry the first cutlet for 30 seconds per side, then drain it on the wire rack for 2 minutes.",1],["Clean the oil again, then fry the second cutlet for 30 seconds per side and drain it the same way.",1],["Slice the cutlets into 3/4-inch pieces. Serve with shredded [[1/4 head]] cabbage, the [[1]] cucumber, sesame dressing and the dipping sauce.",null]],"technique":4,"prep":3,"precision":4,"nutrition":{"calories":523,"protein_g":27,"carbs_g":15,"fat_g":37},"video":"https://www.youtube.com/watch?v=OlEEEiHlGn4","country":"JP","effort_steps":7,"ingredients":[{"item":"green cabbage","qty":0.25,"unit":"head","group":"Shredded Cabbage Salad (optional)"},{"item":"Japanese or Persian cucumber","qty":1,"group":"Shredded Cabbage Salad (optional)"},{"item":"Japanese sesame dressing","note":"or homemade Wafu or Japanese Sesame Dressing","group":"Shredded Cabbage Salad (optional)"},{"item":"toasted white sesame seeds","qty":1,"unit":"tbsp","group":"Sesame Dipping Sauce"},{"item":"toasted black sesame seeds","qty":1,"unit":"tbsp","group":"Sesame Dipping Sauce"},{"item":"tonkatsu sauce","qty":4,"unit":"tbsp","note":"store bought or homemade","group":"Sesame Dipping Sauce"},{"item":"panko (Japanese breadcrumbs)","qty":0.5,"unit":"cup","note":"use fresh nama panko if available","group":"Breading"},{"item":"egg","qty":1,"unit":"large","note":"50 g w/o shell","group":"Breading"},{"item":"neutral oil","qty":0.5,"unit":"tbsp","note":"for the egg","group":"Breading"},{"item":"all-purpose flour","qty":2,"unit":"tbsp","group":"Breading"},{"item":"boneless pork loin chops","qty":2,"note":"1/2 inch thick, 100 g / 3.5 oz per piece","group":"Tonkatsu"},{"item":"Diamond Crystal kosher salt","qty":0.5,"unit":"tsp","group":"Tonkatsu"},{"item":"freshly ground black pepper","qty":0.125,"unit":"tsp","group":"Tonkatsu"},{"item":"neutral oil","qty":3,"unit":"cup","note":"or 1 3/4-2 inches of oil for deep-frying","group":"Tonkatsu"}]}'::jsonb),
('www-recipetineats-com-korean-beef-bowl', 'Korean Bulgogi Beef Stir Fry', 'Korean', 'RecipeTin Eats', 'https://www.recipetineats.com/korean-beef-bowl/', 20, 3, 2, 2, 2, 12, 37, array['beef', 'onion', 'carrots', 'scallions', 'soy sauce', 'garlic']::text[], '{"title":"Korean Bulgogi Beef Stir Fry","cuisine":"Korean","source":"RecipeTin Eats","url":"https://www.recipetineats.com/korean-beef-bowl/","minutes":20,"servings":3,"key":["Beef","Onion","Carrots","Scallions","Soy sauce","Garlic"],"minor":["Brown sugar","Mirin","Sesame oil","Apple or nashi pear","Ginger","Sesame seeds"],"amounts":{"Beef":"14 oz (400 g) thinly sliced","Onion":"1/2 large + 2 tbsp grated","Carrots":"1/2 medium","Scallions":"1","Soy sauce":"3 tbsp","Garlic":"2 cloves"},"steps":[["On a clean cutting board, peel and thinly slice the [[1/2 large]] onion.",null],["Peel the [[1/2 medium]] carrot, cut it lengthwise, then cut it into thin slices on the diagonal.",null],["Finely slice the [[1]] scallion, keeping the green and white parts separate.",null],["Mince the [[2 cloves]] garlic, grate [[2 tbsp]] onion and grate [[3 tbsp]] red apple or nashi pear.",null],["Blot the [[14 oz]] beef dry with a paper towel, then put it into a new bowl.",null],["In a new small bowl, mix [[3 tbsp]] soy sauce, [[1 1/2 tbsp]] brown sugar, [[1 tbsp]] mirin, [[1/2 tbsp]] sesame oil, the grated onion, garlic, grated apple, [[1/2 tsp]] minced ginger and some black pepper.",null],["Pour the marinade into the bowl with the beef and stir gently to coat. Cover with cling wrap and marinate for at least 1 hour, preferably overnight.",60],["Heat [[1 tbsp]] oil in a wok or large fry pan over high heat.",null],["Add the sliced onion and the white part of the scallion. Cook for 1 minute.",1],["Add the beef with all of its marinade, plus the carrots. Cook for around 3 to 5 minutes, stirring constantly, until the beef is just cooked.",3],["Take the pan off the heat and toss through [[1/2 tbsp]] sesame seeds.",null],["Serve right away with rice or cauliflower rice. Sprinkle with extra sesame seeds and the green part of the scallion you set aside.",null]],"technique":2,"prep":2,"precision":2,"nutrition":null,"video":null,"country":"KR","effort_steps":5,"ingredients":[{"item":"thinly sliced beef","qty":14,"unit":"oz","note":"400 g; any good quality tender cut suitable for grilling","group":"Beef"},{"item":"scallion/shallot stem","qty":1,"note":"green and white part separated, both finely sliced","group":"Beef"},{"item":"onion (brown, yellow or white)","qty":0.5,"unit":"large","note":"peeled and thinly sliced","group":"Beef"},{"item":"carrot","qty":0.5,"unit":"medium","note":"peeled, cut vertically then cut into thin slices on the diagonal","group":"Beef"},{"item":"cooking oil (peanut or vegetable oil)","qty":1,"unit":"tbsp","group":"Beef"},{"item":"sesame seeds","qty":0.5,"unit":"tbsp","group":"Beef"},{"item":"ordinary soy sauce","qty":3,"unit":"tbsp","group":"Marinade"},{"item":"brown sugar","qty":1.5,"unit":"tbsp","group":"Marinade"},{"item":"mirin","qty":1,"unit":"tbsp","group":"Marinade"},{"item":"sesame oil","qty":0.5,"unit":"tbsp","group":"Marinade"},{"item":"grated onion (brown, white or yellow)","qty":2,"unit":"tbsp","group":"Marinade"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Marinade"},{"item":"grated red apple (not green) or nashi pear","qty":3,"unit":"tbsp","group":"Marinade"},{"item":"minced ginger","qty":0.5,"unit":"tsp","group":"Marinade"},{"item":"black pepper","group":"Marinade"}]}'::jsonb),
('rasamalaysia-com-wprm-print-japchae-chap-chae', 'Japchae (Chap Chae)', 'Korean', 'Rasa Malaysia', 'https://rasamalaysia.com/wprm_print/japchae-chap-chae', 20, 3, 2, 3, 2, 12, 42, array['glass noodles', 'spinach', 'mushrooms', 'carrots', 'onion', 'soy sauce']::text[], '{"title":"Japchae (Chap Chae)","cuisine":"Korean","source":"Rasa Malaysia","url":"https://rasamalaysia.com/wprm_print/japchae-chap-chae","minutes":20,"servings":3,"key":["Sweet potato noodles","Spinach","Shiitake mushrooms","Carrots","Onion","Soy sauce"],"minor":["Garlic","Scallions","Sesame oil","Sesame seeds"],"amounts":{"Sweet potato noodles":"8 oz (230 g)","Spinach":"4 oz (125 g)","Shiitake mushrooms":"3-4 fresh","Carrots":"1 small","Onion":"1/2 small","Soy sauce":"4 tablespoons"},"steps":[["On a clean cutting board, mince the [[2 cloves]] garlic and thinly slice the [[1/2 small]] onion.",null],["Slice the [[3]] shiitake mushrooms and cut the [[1 small]] carrot into thin strips.",null],["Cut the [[1 stalk]] scallion into 1-inch (2.5 cm) lengths.",null],["In a new small bowl, mix [[4 tbsp]] soy sauce and [[2 1/2 tbsp]] sugar to make the sauce.",null],["Cook the [[8 oz]] sweet potato noodles in a large pot of boiling water for about 5 minutes.",5],["Drain the noodles and rinse them under cold running water. Use scissors to cut them into about 6-inch lengths, then set aside.",null],["Bring a pot of water to a boil. Blanch the [[4 oz]] spinach until wilted, about 1 minute.",1],["Drain the spinach and rinse it under cold running water. Form it into a ball, squeeze out the remaining water, and cut the ball in half.",null],["Heat [[1 1/2 tbsp]] oil in a skillet or wok and add the garlic, onion, mushrooms and carrot. Cook for about two minutes.",2],["Add the scallion and stir-fry for another minute.",1],["Turn the heat to low and add the noodles and spinach to the same skillet or wok, followed by [[1/2 tbsp]] sesame oil, the sauce, and salt to taste. Stir to combine well.",null],["Dish it out, sprinkle with [[1 tsp]] toasted sesame seeds, and serve at room temperature.",null]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":396,"protein_g":5,"carbs_g":83,"fat_g":10},"video":null,"country":"KR","effort_steps":6,"ingredients":[{"item":"sweet potato noodles","qty":8,"unit":"oz","note":"230 g"},{"item":"spinach","qty":4,"unit":"oz","note":"125 g"},{"item":"oil","qty":1.5,"unit":"tbsp"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"onion","qty":0.5,"unit":"small","note":"thinly sliced"},{"item":"fresh shiitake mushrooms","qty":3,"qtyMax":4,"note":"sliced"},{"item":"carrot","qty":1,"unit":"small","note":"cut into thin strips"},{"item":"scallion","qty":1,"unit":"stalk","note":"cut into 1-inch (2.5 cm) lengths"},{"item":"sesame oil","qty":0.5,"unit":"tbsp"},{"item":"salt","note":"to taste"},{"item":"toasted white sesame","qty":1,"unit":"tsp"},{"item":"soy sauce","qty":4,"unit":"tbsp","group":"Sauce"},{"item":"sugar","qty":2.5,"unit":"tbsp","group":"Sauce"}]}'::jsonb),
('www-recipetineats-com-chicken-pad-thai', 'Pad Thai', 'Thai', 'RecipeTin Eats', 'https://www.recipetineats.com/chicken-pad-thai/', 30, 2, 2, 3, 3, 14, 47, array['rice noodles', 'chicken', 'eggs', 'bean sprout', 'tofu', 'peanuts', 'fish sauce']::text[], '{"title":"Pad Thai","cuisine":"Thai","source":"RecipeTin Eats","url":"https://www.recipetineats.com/chicken-pad-thai/","minutes":30,"servings":2,"key":["Rice noodles","Chicken breast","Eggs","Bean sprouts","Tofu","Peanuts","Fish sauce"],"minor":["Tamarind puree","Brown sugar","Oyster sauce","Onion","Garlic","Garlic chives","Lime","Chili powder"],"amounts":{"Rice noodles":"125 g dried rice sticks","Chicken breast":"150 g (breast or thigh)","Eggs":"2","Bean sprouts":"1 1/2 cups","Tofu":"1/2 cup firm","Peanuts":"1/4 cup chopped","Fish sauce":"2 tbsp"},"steps":[["On a clean cutting board, slice the [[1/2]] onion and finely chop the [[2 cloves]] garlic.",null],["Thinly slice the [[150 g]] chicken.",null],["Cut the [[1/2 cup]] firm tofu into 3 cm (1 1/4 inch) batons and the [[1/4 cup]] garlic chives into 3 cm (1 1/4 inch) pieces.",null],["Finely chop [[1/4 cup]] peanuts, and lightly whisk the [[2]] eggs in a new bowl.",null],["Put the [[125 g]] dried rice sticks in a new large bowl and pour plenty of boiling water over them. Soak for 5 minutes.",5],["Drain the noodles in a colander and quickly rinse them under cold water. Don''t leave them sitting for more than 5-10 minutes.",null],["In a new small bowl, mix [[1 1/2 tbsp]] tamarind puree, [[3 tbsp]] brown sugar, [[2 tbsp]] fish sauce and [[1 1/2 tbsp]] oyster sauce.",null],["Heat [[2 tbsp]] oil in a large non-stick pan (or well-seasoned skillet) over high heat. Add the garlic and onion and cook for 30 seconds.",null],["Add the chicken and cook for 1 1/2 minutes until mostly cooked through.",1.5],["Push the chicken to one side of the pan and pour the egg into the other side. Scramble it with a wooden spoon (add a touch of extra oil if the pan is too dry), then mix it into the chicken.",null],["Add [[1 1/2 cups]] bean sprouts, the tofu, the noodles, and then the sauce.",null],["Toss gently for about 1 1/2 minutes until the sauce is absorbed by the noodles.",1.5],["Add the garlic chives and half the peanuts. Toss through quickly, then remove from the heat.",null],["Serve right away, sprinkled with the rest of the peanuts, with lime wedges on the side. Add a sprinkle of chilli and extra bean sprouts if you like, and squeeze over lime juice to taste.",null]],"technique":2,"prep":3,"precision":3,"nutrition":{"calories":650,"protein_g":33,"carbs_g":65,"fat_g":28},"video":null,"country":"TH","effort_steps":6,"ingredients":[{"item":"Chang''s Pad Thai dried rice sticks","qty":125,"unit":"g","note":"4 oz","group":"Noodles"},{"item":"tamarind puree","qty":1.5,"unit":"tbsp","note":"NOT concentrate","group":"Sauce"},{"item":"brown sugar","qty":3,"unit":"tbsp","note":"packed","group":"Sauce"},{"item":"fish sauce","qty":2,"unit":"tbsp","group":"Sauce"},{"item":"oyster sauce","qty":1.5,"unit":"tbsp","group":"Sauce"},{"item":"vegetable or canola oil","qty":2,"qtyMax":3,"unit":"tbsp","group":"Stir Fry"},{"item":"onion (brown, yellow)","qty":0.5,"note":"sliced","group":"Stir Fry"},{"item":"garlic","qty":2,"unit":"clove","note":"finely chopped","group":"Stir Fry"},{"item":"chicken breast (or thigh)","qty":150,"unit":"g","note":"5 oz, thinly sliced","group":"Stir Fry"},{"item":"eggs","qty":2,"note":"lightly whisked","group":"Stir Fry"},{"item":"beansprouts","qty":1.5,"unit":"cup","group":"Stir Fry"},{"item":"firm tofu","qty":0.5,"unit":"cup","note":"cut into 3 cm / 1 1/4 inch batons","group":"Stir Fry"},{"item":"garlic chives","qty":0.25,"unit":"cup","note":"cut into 3 cm / 1 1/4 inch pieces","group":"Stir Fry"},{"item":"peanuts","qty":0.25,"unit":"cup","note":"finely chopped","group":"Stir Fry"},{"item":"lime wedges","note":"essential","group":"For Serving"},{"item":"ground chilli or cayenne pepper","note":"optional","group":"For Serving"},{"item":"more beansprouts","group":"For Serving"}]}'::jsonb),
('eatingthaifood-com-thai-basil-chicken-recipe', 'Authentic Thai Basil Chicken Recipe (ผัดกระเพราไก่)', 'Thai', 'Eating Thai Food', 'https://eatingthaifood.com/thai-basil-chicken-recipe', 20, 1, 2, 2, 2, 12, 39, array['chicken', 'eggs', 'garlic', 'thai basil', 'rice']::text[], '{"title":"Authentic Thai Basil Chicken Recipe (ผัดกระเพราไก่)","cuisine":"Thai","source":"Eating Thai Food","url":"https://eatingthaifood.com/thai-basil-chicken-recipe","minutes":20,"servings":1,"key":["Chicken breast","Eggs","Garlic","Thai basil","Rice"],"minor":["Thai chilies","Oyster sauce","Light soy sauce","Dark soy sauce"],"amounts":{"Chicken breast":"1 boneless (about 200 g)","Eggs":"1","Garlic":"5 cloves","Thai basil":"1 handful holy basil leaves","Rice":"jasmine rice, for serving"},"steps":[["Heat about [[2 tbsp]] vegetable oil in a wok or frying pan on high-medium heat.",null],["When the oil is hot and sizzling, drop in the [[1]] egg. Let it sizzle and bubble up, splashing some of the hot oil over the top (no need to flip it).",null],["When the egg is cooked the way you like it, take it out, drain the extra oil, and put it on a plate for later.",null],["On a clean cutting board, cut the [[1]] chicken breast into small bite-sized pieces.",null],["Rinse and peel the [[5 cloves]] garlic and [[4]] Thai chilies, and pound them in a mortar and pestle (or just mince them with a knife).",null],["Pluck a good-sized [[1 handful]] of holy basil leaves off the stems.",null],["Heat your wok on high heat and add about [[1 tbsp]] oil.",null],["When the oil is hot, add the chilies and garlic. Stir-fry for about 20 seconds until really fragrant, but don''t let them burn or get too dry.",null],["Toss in the chicken and keep stir-frying continuously until it''s just about fully cooked through, about 2-3 minutes.",2],["Add [[1 tsp]] oyster sauce, [[1/2 tsp]] light soy sauce, [[1/2 tsp]] sugar and finally [[1 splash]] dark soy sauce. Keep stir-frying for about another 30 seconds.",null],["Toss the basil into the pan, fold it into the chicken, and then immediately turn off the heat. The basil only needs about 5 seconds.",null],["Serve on a plate with steamed jasmine rice, the basil chicken, and the fried egg on the side.",null]],"technique":2,"prep":2,"precision":2,"nutrition":null,"video":"https://www.youtube.com/watch?v=OV5fQ6EHFyk","country":"TH","effort_steps":6,"ingredients":[{"item":"egg","qty":1,"group":"For the egg"},{"item":"oil","qty":2,"unit":"tbsp","note":"for frying","group":"For the egg"},{"item":"chicken breast","qty":1,"note":"or any other cut of boneless chicken, about 200 grams","group":"Basil chicken"},{"item":"garlic","qty":5,"unit":"clove","group":"Basil chicken"},{"item":"Thai chilies","qty":4,"group":"Basil chicken"},{"item":"oil","qty":1,"unit":"tbsp","note":"for frying","group":"Basil chicken"},{"item":"oyster sauce","qty":1,"unit":"tsp","group":"Basil chicken"},{"item":"light soy sauce","qty":0.5,"unit":"tsp","group":"Basil chicken"},{"item":"dark soy sauce","qty":1,"unit":"splash","group":"Basil chicken"},{"item":"sugar","qty":0.5,"unit":"tsp","group":"Basil chicken"},{"item":"Thai holy basil leaves","qty":1,"unit":"handful","group":"Basil chicken"}]}'::jsonb),
('www-recipetineats-com-vietnamese-chicken-noodle-bowl', 'Vietnamese Noodles with Lemongrass Chicken', 'Vietnamese', 'RecipeTin Eats', 'https://www.recipetineats.com/vietnamese-chicken-noodle-bowl/', 30, 4, 3, 3, 2, 13, 51, array['chicken', 'rice noodles', 'lettuce', 'carrots', 'cucumber', 'bean sprout', 'fish sauce']::text[], '{"title":"Vietnamese Noodles with Lemongrass Chicken","cuisine":"Vietnamese","source":"RecipeTin Eats","url":"https://www.recipetineats.com/vietnamese-chicken-noodle-bowl/","minutes":30,"servings":4,"key":["Chicken thighs","Rice vermicelli","Lettuce","Carrots","Cucumbers","Bean sprouts","Fish sauce"],"minor":["Lemongrass","Garlic","Lime","Soy sauce","Brown sugar","Rice vinegar","Bird''s eye chili","Mint","Cilantro"],"amounts":{"Chicken thighs":"600-800 g boneless, skinless","Rice vermicelli":"200 g","Lettuce":"5 cups sliced iceberg","Carrots":"2","Cucumbers":"2","Bean sprouts":"3 cups","Fish sauce":"2 tbsp + 1/4 cup"},"steps":[["On a clean cutting board, bruise and slice the white part of the [[1 stalk]] lemongrass, and finely chop [[2 cloves]] garlic for the marinade.",null],["In a new bowl, combine the [[600 g]] chicken thighs with the lemongrass, garlic, [[2 tbsp]] lime juice, [[2 tbsp]] fish sauce, [[1 tbsp]] soy sauce, [[2 tbsp]] brown sugar and [[1 tbsp]] vegetable oil. Set aside to marinate for 1 to 24 hours.",60],["For the nuoc cham, finely chop another [[2 cloves]] garlic and the [[1]] red bird''s eye chilli.",null],["In a new bowl, combine [[1/4 cup]] fish sauce, [[4 tbsp]] rice vinegar, [[2 tbsp]] white sugar, [[1/2 cup]] water, the garlic, the chilli and [[3 tbsp]] lime juice. Mix well to dissolve the sugar, adjust to taste, and set aside for at least 20 minutes.",20],["Julienne the [[2]] carrots and [[2]] cucumbers, and finely slice [[5 cups]] iceberg lettuce.",null],["Heat [[1/2 tbsp]] oil in a fry pan over medium heat (or heat a BBQ). Take the chicken out of the marinade, shaking off the large lemongrass pieces.",null],["Cook the chicken on each side until dark golden brown and cooked through, about 6 to 8 minutes in total.",6],["Remove the chicken, shake off any lemongrass you can still see, and let it rest for 5 minutes.",5],["Slice the rested chicken into thin pieces.",null],["Soak the [[200 g]] vermicelli noodles in hot water for 3 minutes (or per the packet instructions).",3],["Drain the noodles and rinse them under cold water.",null],["Place noodles in each serving bowl, then top with the vegetables, [[3 cups]] bean sprouts, [[1 handful]] mint, [[1 handful]] cilantro and the chicken.",null],["Drizzle about 4 tbsp nuoc cham over each serving and serve with lime wedges and sliced chilli if you like. (Or set everything out in separate bowls and let everyone build their own.)",null]],"technique":3,"prep":3,"precision":2,"nutrition":{"calories":540,"protein_g":40,"carbs_g":65,"fat_g":14},"video":null,"country":"VN","effort_steps":6,"ingredients":[{"item":"chicken thigh fillets","qty":600,"qtyMax":800,"unit":"g","note":"skinless and boneless (1.2-1.6 lb)","group":"Chicken and Marinade"},{"item":"lemongrass","qty":1,"unit":"stalk","note":"white part only, bruised and sliced","group":"Chicken and Marinade"},{"item":"garlic","qty":2,"unit":"clove","note":"finely chopped","group":"Chicken and Marinade"},{"item":"lime juice","qty":2,"unit":"tbsp","group":"Chicken and Marinade"},{"item":"fish sauce","qty":2,"unit":"tbsp","group":"Chicken and Marinade"},{"item":"soy sauce","qty":1,"unit":"tbsp","group":"Chicken and Marinade"},{"item":"brown sugar","qty":2,"unit":"tbsp","group":"Chicken and Marinade"},{"item":"vegetable oil","qty":1,"unit":"tbsp","group":"Chicken and Marinade"},{"item":"fish sauce","qty":0.25,"unit":"cup","group":"Nuoc Cham"},{"item":"rice vinegar","qty":4,"unit":"tbsp","group":"Nuoc Cham"},{"item":"white sugar","qty":2,"unit":"tbsp","group":"Nuoc Cham"},{"item":"water","qty":0.5,"unit":"cup","group":"Nuoc Cham"},{"item":"garlic","qty":2,"unit":"clove","note":"finely chopped","group":"Nuoc Cham"},{"item":"red bird''s eye chilli","qty":1,"note":"finely chopped","group":"Nuoc Cham"},{"item":"lime juice","qty":3,"unit":"tbsp","group":"Nuoc Cham"},{"item":"oil","qty":0.5,"unit":"tbsp","group":"Noodle Bowl"},{"item":"vermicelli noodles","qty":200,"unit":"g","note":"dried (7 oz)","group":"Noodle Bowl"},{"item":"carrots","qty":2,"note":"julienned","group":"Noodle Bowl"},{"item":"cucumbers","qty":2,"note":"julienned","group":"Noodle Bowl"},{"item":"iceberg lettuce","qty":5,"unit":"cup","note":"finely sliced","group":"Noodle Bowl"},{"item":"bean sprouts","qty":3,"unit":"cup","group":"Noodle Bowl"},{"item":"mint leaves","qty":1,"unit":"handful","group":"Noodle Bowl"},{"item":"cilantro/coriander","qty":1,"unit":"handful","group":"Noodle Bowl"},{"item":"sliced red chilli","note":"optional garnish","group":"Noodle Bowl"},{"item":"lime wedges","note":"optional","group":"Noodle Bowl"}]}'::jsonb),
('www-recipetineats-com-butter-chicken', 'Butter Chicken (Murgh Makhani)', 'Indian', 'RecipeTin Eats', 'https://www.recipetineats.com/butter-chicken/', 35, 4, 4, 2, 2, 9, 51, array['chicken', 'yogurt', 'tomatoes', 'cream', 'butter', 'garlic', 'ginger']::text[], '{"title":"Butter Chicken (Murgh Makhani)","cuisine":"Indian","source":"RecipeTin Eats","url":"https://www.recipetineats.com/butter-chicken/","minutes":35,"servings":4,"key":["Chicken thighs","Yogurt","Tomato passata","Heavy cream","Butter","Garlic","Ginger"],"minor":["Lemon juice","Turmeric","Garam masala","Chili powder","Ground cumin","Cilantro","Basmati rice (to serve)"],"amounts":{"Chicken thighs":"1.5 lb (750g), bite-sized","Yogurt":"1/2 cup plain full fat","Tomato passata":"1 cup","Heavy cream":"1 cup","Butter":"2 tbsp ghee or butter","Garlic":"2 cloves, crushed","Ginger":"1 tbsp fresh grated"},"steps":[["On a clean cutting board, cut [[1.5 lb]] chicken thigh fillets into bite size pieces.",null],["Grate [[1 tbsp]] fresh ginger and crush [[2 cloves]] garlic.",null],["In a bowl, stir together [[0.5 cup]] full fat yoghurt, [[1 tbsp]] lemon juice, [[1 tsp]] turmeric, [[2 tsp]] garam masala, [[0.5 tsp]] chilli powder, [[1 tsp]] ground cumin, the ginger and the garlic. (Optional: blend these marinade ingredients in a food processor until smooth first.)",null],["Add the chicken to the same bowl and mix to coat. Cover and refrigerate for at least 3 hours, or overnight (up to 24 hours).",180],["Heat [[2 tbsp]] ghee or butter (or 1 tbsp vegetable oil) in a large fry pan over high heat.",null],["Lift the chicken out of the marinade into the hot pan without wiping off the excess, but leave the leftover marinade in the bowl for now. Cook for about 3 minutes until the chicken is white throughout.",3],["Add [[1 cup]] tomato passata, [[1 cup]] cream, [[1 tbsp]] sugar, [[1.25 tsp]] salt and any marinade left in the bowl into the same pan.",null],["Reduce the heat to low and simmer for 20 minutes. Taste and add more salt if needed.",20],["Garnish with coriander/cilantro if you like and serve with basmati rice.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":402,"protein_g":40,"carbs_g":10,"fat_g":23},"video":null,"country":"IN","effort_steps":4,"ingredients":[{"item":"plain yoghurt","qty":0.5,"unit":"cup","note":"full fat","group":"Marinade"},{"item":"lemon juice","qty":1,"unit":"tbsp","group":"Marinade"},{"item":"turmeric powder","qty":1,"unit":"tsp","group":"Marinade"},{"item":"garam masala","qty":2,"unit":"tsp","group":"Marinade"},{"item":"chilli powder or cayenne pepper powder","qty":0.5,"unit":"tsp","group":"Marinade"},{"item":"ground cumin","qty":1,"unit":"tsp","group":"Marinade"},{"item":"ginger","qty":1,"unit":"tbsp","note":"freshly grated","group":"Marinade"},{"item":"garlic","qty":2,"unit":"clove","note":"crushed","group":"Marinade"},{"item":"chicken thigh fillets","qty":1.5,"unit":"lb","note":"750 g; cut into bite size pieces","group":"Marinade"},{"item":"ghee or butter","qty":2,"unit":"tbsp","note":"30 g; OR 1 tbsp vegetable oil","group":"Curry"},{"item":"tomato passata (tomato puree)","qty":1,"unit":"cup","group":"Curry"},{"item":"heavy / thickened cream","qty":1,"unit":"cup","group":"Curry"},{"item":"sugar","qty":1,"unit":"tbsp","group":"Curry"},{"item":"salt","qty":1.25,"unit":"tsp","group":"Curry"},{"item":"basmati rice or white rice","group":"To Serve"},{"item":"coriander/cilantro","note":"optional","group":"To Serve"}]}'::jsonb),
('www-indianhealthyrecipes-com-dal-tadka', 'Dal Tadka Recipe (Restaurant Style)', 'Indian', 'Swasthi''s Recipes', 'https://www.indianhealthyrecipes.com/dal-tadka/', 40, 4, 2, 2, 2, 20, 44, array['lentils', 'onion', 'tomatoes', 'garlic', 'ginger', 'butter', 'lemon']::text[], '{"title":"Dal Tadka Recipe (Restaurant Style)","cuisine":"Indian","source":"Swasthi''s Recipes","url":"https://www.indianhealthyrecipes.com/dal-tadka/","minutes":40,"servings":4,"key":["Lentils","Onion","Tomatoes","Garlic","Ginger","Ghee","Lemon"],"minor":["Cumin seeds","Green chili","Turmeric","Red chili powder","Garam masala","Kasuri methi","Coriander leaves","Dried red chilies","Asafoetida","Mustard seeds","Curry leaves"],"amounts":{"Lentils":"1 cup (200g) mixed toor, moong and chana dal","Onion":"1/3 to 1/2 cup chopped","Tomatoes":"2 medium, deseeded and chopped","Garlic":"1 tsp chopped, plus 1/2 to 1 tbsp for tadka","Ginger":"1 tsp chopped","Ghee":"2 tbsp","Lemon":"1 medium"},"steps":[["On a clean cutting board, fine chop [[1 tsp]] garlic for the dal and [[0.5 tbsp]] to [[1 tbsp]] garlic for the tadka (keep them separate). Peel and fine chop [[1 tsp]] ginger.",null],["Fine chop [[1 medium]] onion and [[1]] green chilli (optional). Deseed and fine chop [[2 medium]] tomatoes, and fine chop [[1 tbsp]] to [[2 tbsp]] coriander leaves.",null],["Add [[1 cup]] toor dal to a pressure cooker and rinse it thoroughly with lots of water, rubbing the lentils with your hand. Drain completely.",null],["Pour [[3 cups]] water into the pressure cooker and cook on medium heat for 3 to 4 whistles (Instant Pot: high pressure for 10 minutes).",null],["When the pressure drops naturally, open the lid; the dal should be soft cooked. Lightly mash it, keeping some dal intact, and add up to [[0.75 cup]] hot water only if needed for your desired consistency.",null],["While the lentils cook, heat [[1.5 tbsp]] to [[2 tbsp]] oil in a medium pan and add [[0.5 tsp]] cumin seeds.",null],["When the cumin splutters, add the dal''s ginger and garlic and saute on low heat until fragrant.",null],["Add the onion and green chilli to the same pan and fry until slightly golden.",null],["Reduce the heat. Add [[0.5 tsp]] to [[0.75 tsp]] red chilli powder, [[0.25 tsp]] turmeric and [[0.5 tsp]] garam masala, and stir quickly.",null],["Stir in the tomatoes and [[1 tsp]] salt, and saute until the tomatoes become soft.",null],["Transfer this mixture into the pot of cooked dal and simmer for 6 to 7 minutes. Taste and add more salt if needed.",6],["Crush [[1 tbsp]] kasuri methi and add it to the dal with the coriander leaves. Turn off the heat.",null],["Optional smoky flavor: place a tall steel cup in the center of the pot. Hold a wood coal over direct fire with tongs until part of it turns red hot (about 2 minutes), put it in the cup, pour 0.5 tsp ghee over it, cover the pot and let it smoke for 3 to 4 minutes. Then remove the cup.",3],["Transfer the hot dal to a serving bowl.",null],["For the tadka, melt [[2 tbsp]] ghee in a small pan on medium heat.",null],["Add [[0.5 tsp]] to [[0.75 tsp]] cumin seeds and [[0.25 tsp]] mustard seeds (optional). Fry on low heat until aromatic and crackling.",null],["Add [[2]] whole dried red chilies to the small pan and stir.",null],["Add the tadka garlic and [[1 sprig]] curry leaves (optional). Fry until light and aromatic; do not let the garlic brown.",null],["Stir in [[0.125 tsp]] asafoetida and [[0.333 tsp]] red chilli powder, then immediately remove the pan from the heat.",null],["Pour the hot tadka over the dal in the serving bowl. Garnish with coriander leaves and squeeze [[1 medium]] lemon over while serving.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":351,"protein_g":16,"carbs_g":43,"fat_g":14},"video":"https://www.youtube.com/watch?v=63_KsWxTOyk","country":"IN","effort_steps":6,"ingredients":[{"item":"toor dal","qty":1,"unit":"cup","note":"200 grams (or 3/4 cup toor dal, 1/4 cup moong dal and 2 tbsp chana dal)","group":"For the Dal"},{"item":"water","qty":3,"unit":"cup","note":"to cook dal","group":"For the Dal"},{"item":"hot water","qty":0.75,"unit":"cup","note":"use only if required to adjust consistency","group":"For the Dal"},{"item":"oil","qty":1.5,"qtyMax":2,"unit":"tbsp","group":"For the Dal"},{"item":"cumin seeds","qty":0.5,"unit":"tsp","group":"For the Dal"},{"item":"garlic","qty":1,"unit":"tsp","note":"4 cloves, fine chopped","group":"For the Dal"},{"item":"ginger","qty":1,"unit":"tsp","note":"1 inch, peeled and fine chopped","group":"For the Dal"},{"item":"onion","qty":1,"unit":"medium","note":"1/3 to 1/2 cup, fine chopped","group":"For the Dal"},{"item":"green chilli","qty":1,"note":"chopped (optional)","group":"For the Dal"},{"item":"tomatoes","qty":2,"unit":"medium","note":"1 cup, deseeded and fine chopped","group":"For the Dal"},{"item":"turmeric","qty":0.25,"unit":"tsp","group":"For the Dal"},{"item":"red chilli powder","qty":0.5,"qtyMax":0.75,"unit":"tsp","group":"For the Dal"},{"item":"garam masala","qty":0.5,"unit":"tsp","group":"For the Dal"},{"item":"salt","qty":1,"unit":"tsp","note":"more to adjust","group":"For the Dal"},{"item":"kasuri methi (dried fenugreek leaves)","qty":1,"unit":"tbsp","group":"For the Dal"},{"item":"coriander leaves","qty":1,"qtyMax":2,"unit":"tbsp","note":"fine chopped","group":"For the Dal"},{"item":"lemon","qty":1,"unit":"medium","note":"to serve (or 1 tsp amchur)","group":"For the Dal"},{"item":"ghee","qty":2,"unit":"tbsp","note":"or oil for vegan","group":"For the Tadka"},{"item":"cumin seeds","qty":0.5,"qtyMax":0.75,"unit":"tsp","group":"For the Tadka"},{"item":"dried red chilies","qty":2,"group":"For the Tadka"},{"item":"garlic","qty":0.5,"qtyMax":1,"unit":"tbsp","note":"fine chopped","group":"For the Tadka"},{"item":"hing (asafoetida)","qty":0.125,"unit":"tsp","group":"For the Tadka"},{"item":"red chilli powder","qty":0.333,"unit":"tsp","group":"For the Tadka"},{"item":"mustard seeds","qty":0.25,"unit":"tsp","note":"optional","group":"For the Tadka"},{"item":"curry leaves","qty":1,"unit":"sprig","note":"optional, pat dry","group":"For the Tadka"}]}'::jsonb),
('www-cookwithmanali-com-chana-masala', 'Chana Masala (using raw chickpeas)', 'Indian', 'Cook With Manali', 'https://www.cookwithmanali.com/chana-masala/', 60, 3, 4, 2, 2, 13, 63, array['chickpeas', 'onion', 'tomatoes', 'tomato paste', 'garlic', 'ginger']::text[], '{"title":"Chana Masala (using raw chickpeas)","cuisine":"Indian","source":"Cook With Manali","url":"https://www.cookwithmanali.com/chana-masala/","minutes":60,"servings":3,"key":["Chickpeas","Onion","Tomatoes","Tomato paste","Garlic","Ginger"],"minor":["Green chili","Bay leaf","Green cardamom","Cloves","Cinnamon stick","Black peppercorns","Cumin seeds","Coriander powder","Cumin powder","Paprika","Turmeric","Garam masala","Kasuri methi","Cilantro"],"amounts":{"Chickpeas":"1 cup raw (200g), soaked overnight, or 2.5 cups canned","Onion":"1 large red onion, finely chopped","Tomatoes":"2 medium, pureed","Tomato paste":"1 tbsp","Garlic":"3-4 large cloves","Ginger":"1 inch"},"steps":[["The night before, soak [[1 cup]] raw chickpeas in [[3 cups]] water. (Skip the chickpea cooking steps if using [[2.5 cups]] canned chickpeas.)",null],["Drain the chickpeas and put them in a pressure cooker with [[0.5 tsp]] salt and [[2 cups]] to [[2.5 cups]] water.",null],["Stove-top: cook on high heat for 2 whistles, then lower to medium and cook 10 more minutes; let the pressure release naturally. (Instant Pot: high pressure for 25 minutes with natural release.) The chickpeas are done when they break easily between your thumb and index finger.",10],["On a clean cutting board, finely chop [[1 large]] red onion. Puree [[2 medium]] tomatoes and set aside. Chop [[1 tbsp]] to [[2 tbsp]] cilantro.",null],["Using a mortar and pestle, crush [[1 inch]] ginger, [[3]] to [[4]] large garlic cloves and [[1]] green chili together. Set aside.",null],["Heat a pot over medium heat and add [[2 tbsp]] oil. Add [[1]] bay leaf, [[4]] green cardamoms, [[3]] cloves, [[1 inch]] cinnamon stick, [[7]] to [[8]] black peppercorns and [[0.75 tsp]] cumin seeds. Let them sizzle for 30 seconds until fragrant.",0.5],["Add the chopped onion to the pot, stir and cook for 3 minutes until softened. Add [[0.25 tsp]] salt.",3],["Add the crushed ginger-garlic-chili mixture and cook, stirring, for 1-2 minutes until the raw smell is gone.",1],["Add the pureed tomatoes and [[1 tbsp]] tomato paste. Cook for 5 minutes on medium heat, stirring often.",5],["Add [[1 tsp]] coriander powder, [[0.5 tsp]] cumin powder, [[0.5 tsp]] paprika, [[0.25 tsp]] turmeric and [[0.25 tsp]] garam masala. Cook for 30 seconds, until oil oozes from the sides of the masala.",0.5],["Stir in the boiled chickpeas and add [[2 cups]] water (use the water the chickpeas were boiled in). Taste and add [[0.125 tsp]] more salt if needed.",null],["Cover the pot, set the heat to medium-low and simmer for 10-15 minutes so the flavors blend.",10],["Stir in [[1 tsp]] crushed kasuri methi and the chopped cilantro. Garnish with more cilantro and serve hot.",null]],"technique":4,"prep":2,"precision":2,"nutrition":{"calories":234,"protein_g":7,"carbs_g":29,"fat_g":11},"video":null,"country":"IN","effort_steps":7,"ingredients":[{"item":"white chickpeas, raw","qty":1,"unit":"cup","note":"200 grams, soaked overnight, or use 2.5 cups canned chickpeas"},{"item":"salt","qty":0.875,"unit":"tsp","note":"or as needed, divided"},{"item":"water","qty":2.5,"unit":"cup","note":"to boil the chickpeas, skip if using canned chickpeas"},{"item":"ginger","qty":1,"unit":"inch"},{"item":"garlic","qty":3,"qtyMax":4,"unit":"large clove"},{"item":"green chili","qty":1,"note":"or more to taste"},{"item":"oil","qty":2,"unit":"tbsp","note":"30 ml"},{"item":"bay leaf","qty":1},{"item":"whole green cardamoms","qty":4},{"item":"cloves","qty":3},{"item":"cinnamon stick","qty":1,"unit":"inch"},{"item":"whole black peppercorns","qty":7,"qtyMax":8},{"item":"cumin seeds","qty":0.75,"unit":"tsp"},{"item":"red onion","qty":1,"unit":"large","note":"finely chopped"},{"item":"tomatoes","qty":2,"unit":"medium","note":"pureed"},{"item":"tomato paste","qty":1,"unit":"tbsp"},{"item":"coriander powder","qty":1,"unit":"tsp"},{"item":"cumin powder","qty":0.5,"unit":"tsp"},{"item":"paprika","qty":0.5,"unit":"tsp"},{"item":"turmeric powder","qty":0.25,"unit":"tsp"},{"item":"garam masala","qty":0.25,"unit":"tsp"},{"item":"kasuri methi (dried fenugreek leaves)","qty":1,"unit":"tsp","note":"crushed"},{"item":"cilantro","qty":1,"qtyMax":2,"unit":"tbsp","note":"chopped"}]}'::jsonb),
('www-themediterraneandish-com-shakshuka-recipe', 'Shakshuka Recipe (Easy and Authentic)', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/shakshuka-recipe/', 40, 6, 2, 2, 2, 9, 42, array['eggs', 'tomatoes', 'onion', 'bell peppers', 'garlic']::text[], '{"title":"Shakshuka Recipe (Easy and Authentic)","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/shakshuka-recipe/","minutes":40,"servings":6,"key":["Eggs","Tomatoes","Onion","Green bell peppers","Garlic","Tomato sauce"],"minor":["Ground coriander","Sweet paprika","Ground cumin","Red pepper flakes","Parsley","Mint","Olive oil"],"amounts":{"Eggs":"6 large","Tomatoes":"6 medium, chopped (about 6 cups)","Onion":"1 large yellow onion, chopped","Green bell peppers":"2, chopped","Garlic":"2 cloves, chopped","Tomato sauce":"1/2 cup"},"steps":[["On a clean cutting board, chop [[1 large]] yellow onion, [[2]] green peppers and [[2 cloves]] garlic.",null],["Chop [[6 medium]] tomatoes (about 6 cups), and chop [[0.25 cup]] parsley leaves and [[0.25 cup]] mint leaves.",null],["Heat [[3 tbsp]] olive oil in a large skillet over medium heat until shimmering.",null],["Add the onion, peppers and garlic, plus [[1 tsp]] ground coriander, [[1 tsp]] sweet paprika, [[0.5 tsp]] ground cumin, a [[1 pinch]] of red pepper flakes (optional), salt and pepper. Cook, stirring occasionally, until the vegetables soften, about 5 minutes.",5],["Add the chopped tomatoes and [[0.5 cup]] tomato sauce to the skillet. Cover and simmer for about 15 minutes.",15],["Uncover and cook a little longer so the sauce reduces and thickens. Taste and adjust the seasoning.",null],["Using a wooden spoon, make 6 indentations in the sauce, spaced apart. Gently crack [[6]] eggs into the indentations, one in each.",null],["Reduce the heat to medium-low, cover the skillet and cook until the egg whites are set.",null],["Uncover and scatter the parsley and mint on top. Add more black pepper or red pepper flakes if you like, and serve with warm pita, challah or crusty bread.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":173,"protein_g":8,"carbs_g":11,"fat_g":12},"video":null,"country":"TN","effort_steps":5,"ingredients":[{"item":"extra virgin olive oil","qty":3,"unit":"tbsp"},{"item":"yellow onion","qty":1,"unit":"large","note":"chopped"},{"item":"green peppers","qty":2,"note":"chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"chopped"},{"item":"ground coriander","qty":1,"unit":"tsp"},{"item":"sweet paprika","qty":1,"unit":"tsp"},{"item":"ground cumin","qty":0.5,"unit":"tsp"},{"item":"red pepper flakes","qty":1,"unit":"pinch","note":"optional"},{"item":"kosher salt"},{"item":"black pepper"},{"item":"tomatoes","qty":6,"unit":"medium","note":"chopped (about 6 cups chopped tomatoes)"},{"item":"tomato sauce","qty":0.5,"unit":"cup"},{"item":"eggs","qty":6,"unit":"large"},{"item":"fresh parsley leaves","qty":0.25,"unit":"cup","note":"chopped"},{"item":"fresh mint leaves","qty":0.25,"unit":"cup","note":"chopped"}]}'::jsonb),
('www-themediterraneandish-com-chicken-shawarma-recipe', 'Chicken Shawarma', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/chicken-shawarma-recipe/', 40, 6, 3, 2, 2, 13, 50, array['chicken', 'onion', 'lemon', 'pita', 'arugula']::text[], '{"title":"Chicken Shawarma","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/chicken-shawarma-recipe/","minutes":40,"servings":6,"key":["Chicken thighs","Onion","Lemon","Pita bread","Arugula"],"minor":["Ground cumin","Turmeric","Ground coriander","Garlic powder","Paprika","Ground cloves","Cayenne","Olive oil","Tahini or tzatziki","Pickles or kalamata olives"],"amounts":{"Chicken thighs":"8 boneless, skinless","Onion":"1 large, thinly sliced","Lemon":"juice of 1 large","Pita bread":"6 pita pockets","Arugula":"baby arugula, to serve"},"steps":[["Thinly slice [[1 large]] onion and squeeze the juice from [[1 large]] lemon.",null],["In a small bowl, mix [[0.75 tbsp]] ground cumin, [[0.75 tbsp]] turmeric, [[0.75 tbsp]] ground coriander, [[0.75 tbsp]] garlic powder, [[0.75 tbsp]] paprika, [[0.5 tsp]] ground cloves and [[0.5 tsp]] cayenne pepper. Set aside.",null],["Pat [[8]] chicken thighs dry and season both sides with salt.",null],["On a clean cutting board, thinly slice the chicken into bite-sized pieces.",null],["Put the chicken in a large bowl, add the spice mixture from the small bowl and toss.",null],["Add the onion, lemon juice and [[0.333 cup]] olive oil to the same large bowl and toss again.",null],["Optional: cover and refrigerate for 3 hours or overnight.",null],["Preheat the oven to 425°F. If the chicken was in the fridge, take it out and let it sit at room temperature briefly.",null],["Lightly oil a sheet pan and spread the chicken and onions on it in a single layer.",null],["Roast for 30 minutes, until the chicken reaches an internal temperature of 165°F.",30],["For crispier edges, broil briefly on the top rack, watching carefully.",null],["While the chicken roasts, get the pita pockets, tahini or tzatziki sauce and salad ready.",null],["Open [[6]] pita pockets, spread sauce inside, and fill with chicken shawarma, arugula, pickles or olives, and salad. Serve immediately.",null]],"technique":3,"prep":2,"precision":2,"nutrition":{"calories":467,"protein_g":35,"carbs_g":37,"fat_g":20},"video":null,"country":"LB","effort_steps":6,"ingredients":[{"item":"ground cumin","qty":0.75,"unit":"tbsp","group":"Spice Mixture"},{"item":"turmeric powder","qty":0.75,"unit":"tbsp","group":"Spice Mixture"},{"item":"ground coriander","qty":0.75,"unit":"tbsp","group":"Spice Mixture"},{"item":"garlic powder","qty":0.75,"unit":"tbsp","group":"Spice Mixture"},{"item":"paprika","qty":0.75,"unit":"tbsp","group":"Spice Mixture"},{"item":"ground cloves","qty":0.5,"unit":"tsp","group":"Spice Mixture"},{"item":"cayenne pepper","qty":0.5,"unit":"tsp","group":"Spice Mixture"},{"item":"salt"},{"item":"chicken thighs","qty":8,"note":"boneless, skinless"},{"item":"onion","qty":1,"unit":"large","note":"thinly sliced"},{"item":"lemon","qty":1,"unit":"large","note":"juice of"},{"item":"extra virgin olive oil","qty":0.333,"unit":"cup"},{"item":"pita pockets","qty":6,"group":"To Serve"},{"item":"tahini sauce or Greek tzatziki sauce","group":"To Serve"},{"item":"baby arugula","group":"To Serve"},{"item":"3-ingredient Mediterranean salad","group":"To Serve"},{"item":"pickles or kalamata olives","note":"optional","group":"To Serve"}]}'::jsonb),
('www-themediterraneandish-com-mujadara', 'Authentic Mujadara (Middle Eastern Lentils, Rice and Onions)', 'Middle Eastern', 'The Mediterranean Dish', 'https://www.themediterraneandish.com/mujadara/', 120, 6, 2, 2, 3, 15, 66, array['lentils', 'rice', 'onion']::text[], '{"title":"Authentic Mujadara (Middle Eastern Lentils, Rice and Onions)","cuisine":"Middle Eastern","source":"The Mediterranean Dish","url":"https://www.themediterraneandish.com/mujadara/","minutes":120,"servings":6,"key":["Lentils","Rice","Onion"],"minor":["Cumin","Parsley","Olive oil","Black pepper"],"amounts":{"Lentils":"1 cup black lentils, rinsed","Rice":"1 cup long-grain white rice, soaked and drained","Onion":"2 large diced (4 cups), plus 1 large thinly sliced for garnish"},"steps":[["On a clean cutting board, dice [[2 large]] yellow onions (about 4 cups). For the optional garnish, cut [[1 large]] yellow onion into very thin rings.",null],["Soak [[1 cup]] long-grain white rice in water for 10-15 minutes, then drain.",10],["Sort and rinse [[1 cup]] black lentils.",null],["Put the lentils and [[2 cups]] water in a small saucepan over high heat and bring to a boil.",null],["Reduce the heat to medium-low, cover and simmer until the lentils are par-boiled, about 10-12 minutes.",10],["Remove from the heat, drain the lentils and set aside.",null],["In a large saute pan with a lid, heat [[0.25 cup]] olive oil over medium-high heat.",null],["Add the diced onions and cook until dark golden brown (darker than typical caramelized onions), about 40 minutes. Sprinkle the onions with [[1 tsp]] salt as they cook.",40],["Carefully add [[2 cups]] water to the pan with the onions. Bring to a boil over high heat, then reduce the heat to low and simmer for 2 minutes.",2],["Stir the drained rice and par-cooked lentils into the onion pan. Add a good dash of kosher salt, black pepper and [[0.5 tsp]] to [[1 tsp]] cumin.",null],["Keep the heat on low, cover and cook until the liquid is absorbed and the rice and lentils are cooked through, about 15 to 20 minutes.",15],["Meanwhile, for the crispy onions, heat [[2 tbsp]] to [[3 tbsp]] olive oil in a large skillet over medium-high heat. Drop in a small piece of onion; when it bubbles vigorously, the oil is ready.",null],["Fry the onion rings in batches until crispy and deeply golden brown, then move them to a paper towel-lined plate.",null],["Let the rice and lentils rest, covered and undisturbed, for about 10 minutes.",10],["Spoon into serving bowls, top each with crispy onion rings and garnish with parsley.",null]],"technique":2,"prep":2,"precision":3,"nutrition":{"calories":378,"protein_g":11,"carbs_g":47,"fat_g":17},"video":null,"country":"LB","effort_steps":6,"ingredients":[{"item":"black lentils","qty":1,"unit":"cup","note":"sorted and rinsed"},{"item":"extra virgin olive oil","qty":0.25,"unit":"cup","note":"more for later"},{"item":"yellow onions","qty":2,"unit":"large","note":"diced (4 cups)"},{"item":"kosher salt","qty":1,"unit":"tsp","note":"more to taste"},{"item":"long-grain white rice","qty":1,"unit":"cup","note":"soaked in water for 10-15 minutes and then drained"},{"item":"black pepper"},{"item":"cumin","qty":0.5,"qtyMax":1,"unit":"tsp"},{"item":"parsley","note":"for garnish"},{"item":"extra virgin olive oil","group":"For the fried crispy onion garnish (optional)"},{"item":"yellow onion","qty":1,"unit":"large","note":"cut in very thin rings","group":"For the fried crispy onion garnish (optional)"}]}'::jsonb),
('www-chilipeppermadness-com-recipes-misir-wat', 'Misir Wat Recipe (Ethiopian Spicy Red Lentils)', 'Ethiopian', 'Chili Pepper Madness', 'https://www.chilipeppermadness.com/recipes/misir-wat/', 45, 4, 2, 1, 2, 10, 40, array['lentils', 'onion', 'garlic', 'ginger', 'tomato paste', 'broth']::text[], '{"title":"Misir Wat Recipe (Ethiopian Spicy Red Lentils)","cuisine":"Ethiopian","source":"Chili Pepper Madness","url":"https://www.chilipeppermadness.com/recipes/misir-wat/","minutes":45,"servings":4,"key":["Red lentils","Onion","Garlic","Ginger","Tomato paste","Broth"],"minor":["Berbere spice","Black pepper","Nigella seeds","Cardamom","Cilantro","Niter kibbeh (optional)"],"amounts":{"Red lentils":"1 cup dry, rinsed","Onion":"2 medium, chopped","Garlic":"4 cloves, minced","Ginger":"1 tsp minced","Tomato paste":"3 tbsp","Broth":"3 cups chicken or vegetable"},"steps":[["On a clean cutting board, chop [[2 medium]] onions, mince [[4 cloves]] garlic and [[1 tsp]] ginger, and chop some cilantro for garnish.",null],["Rinse and drain [[1 cup]] dry red lentils.",null],["Heat [[2 tbsp]] vegetable oil or niter kibbeh in a large pan or Dutch oven over medium heat.",null],["Add the onions and cook for 5 minutes to soften.",5],["Add the garlic and ginger and cook for 30 seconds, until fragrant.",0.5],["Stir in [[3 tbsp]] tomato paste, [[2 tbsp]] berbere spice, [[1 tsp]] black pepper, [[0.5 tsp]] ground nigella seeds and [[0.5 tsp]] ground cardamom. Cook for 1 minute, until slightly darkened.",1],["Add the lentils, [[3 cups]] broth and salt to taste to the same pan.",null],["Bring to a boil, then reduce the heat, cover and simmer for 30-40 minutes, stirring occasionally, until the lentils are tender.",30],["For a creamier texture, mash some of the lentils with a wooden spoon (optional).",null],["Garnish with cilantro and serve immediately, or let it rest off the heat for 30 minutes and then reheat gently.",null]],"technique":2,"prep":1,"precision":2,"nutrition":null,"video":null,"country":"ET","effort_steps":5,"ingredients":[{"item":"vegetable oil or niter kibbeh","qty":2,"unit":"tbsp"},{"item":"onions","qty":2,"unit":"medium","note":"chopped (yellow or red)"},{"item":"garlic","qty":4,"unit":"clove","note":"minced"},{"item":"ginger","qty":1,"unit":"tsp","note":"minced"},{"item":"tomato paste","qty":3,"unit":"tbsp"},{"item":"berbere spice","qty":2,"unit":"tbsp","note":"or 1/4 cup for extra spicy"},{"item":"black pepper","qty":1,"unit":"tsp"},{"item":"ground nigella seeds","qty":0.5,"unit":"tsp","note":"cumin as substitute"},{"item":"ground cardamom","qty":0.5,"unit":"tsp","note":"optional"},{"item":"dry red lentils","qty":1,"unit":"cup","note":"rinsed and drained"},{"item":"chicken broth (or vegetable broth)","qty":3,"unit":"cup"},{"item":"salt","note":"to taste"},{"item":"fresh cilantro","note":"chopped, for garnish"}]}'::jsonb),
('www-chilipeppermadness-com-recipes-doro-wat', 'Doro Wat Recipe (Ethiopian Chicken Stew)', 'Ethiopian', 'Chili Pepper Madness', 'https://www.chilipeppermadness.com/recipes/doro-wat/', 115, 4, 4, 3, 3, 11, 82, array['chicken', 'onion', 'eggs', 'tomato paste', 'garlic', 'ginger', 'lemon']::text[], '{"title":"Doro Wat Recipe (Ethiopian Chicken Stew)","cuisine":"Ethiopian","source":"Chili Pepper Madness","url":"https://www.chilipeppermadness.com/recipes/doro-wat/","minutes":115,"servings":4,"key":["Chicken thighs","Red onions","Eggs","Tomato paste","Garlic","Ginger","Lemon"],"minor":["Berbere seasoning","Paprika","Niter kibbeh or ghee","Chicken stock","Parsley","Canola oil"],"amounts":{"Chicken thighs":"2 lbs thighs and legs, skin removed","Red onions":"2 large, chopped","Eggs":"4-6 large, hard-boiled and peeled","Tomato paste":"2 tbsp","Garlic":"6 cloves, chopped","Ginger":"1 tbsp minced","Lemon":"juice of 1"},"steps":[["On a clean cutting board, chop [[2 large]] red onions and [[6 cloves]] garlic, and mince [[1 tbsp]] ginger. Have [[4]] to [[6]] hard-boiled eggs peeled and ready.",null],["Put [[2 lb]] chicken thighs and legs in a large bowl and cover with water. Stir in the juice from [[1]] lemon and let soak for at least 30 minutes.",30],["Drain the chicken and rinse it thoroughly with fresh water. Set aside.",null],["Heat a large pot or Dutch oven over medium heat. Add the onions and cook, stirring very often so they don''t stick, for 15-20 minutes until browned and caramelized.",15],["Add [[3 tbsp]] canola oil, the garlic, ginger, [[2 tbsp]] to [[3 tbsp]] berbere seasoning, [[1 tbsp]] paprika, and salt and pepper. Cook, stirring, for 2-3 minutes until very aromatic.",2],["Stir in [[2 tbsp]] tomato paste and cook for 5 minutes, stirring occasionally.",5],["Add [[1 cup]] to [[2 cups]] water or stock (2 cups for a soupier stew) and bring to a boil.",null],["Season the chicken with salt and pepper and add it to the pot.",null],["Reduce the heat and simmer on low, partially covered, for 40 minutes, stirring a few times. Cook longer for more tender chicken.",40],["Stir in [[2 tbsp]] niter kibbeh (or ghee) and add the peeled eggs, pushing them under the sauce. Heat for 10 minutes, until the chicken is cooked through and very tender.",10],["Serve with chopped fresh parsley and a squeeze of fresh lemon.",null]],"technique":4,"prep":3,"precision":3,"nutrition":{"calories":434,"protein_g":34,"carbs_g":11,"fat_g":27},"video":null,"country":"ET","effort_steps":7,"ingredients":[{"item":"chicken thighs and legs","qty":2,"unit":"lb","note":"skins removed, if desired"},{"item":"lemon","qty":1,"note":"juice from"},{"item":"red onions","qty":2,"unit":"large","note":"chopped"},{"item":"canola oil","qty":3,"unit":"tbsp"},{"item":"garlic","qty":6,"unit":"clove","note":"chopped, or more to taste"},{"item":"ginger","qty":1,"unit":"tbsp","note":"minced"},{"item":"berbere seasoning","qty":2,"qtyMax":3,"unit":"tbsp"},{"item":"paprika","qty":1,"unit":"tbsp"},{"item":"salt and pepper","note":"to taste"},{"item":"tomato paste","qty":2,"unit":"tbsp"},{"item":"water or chicken stock","qty":1,"qtyMax":2,"unit":"cup","note":"use 2 cups for soupier consistency"},{"item":"niter kibbeh spiced butter","qty":2,"unit":"tbsp","note":"optional, or use ghee"},{"item":"hard-boiled eggs","qty":4,"qtyMax":6,"unit":"large","note":"peeled"},{"item":"fresh parsley and freshly squeezed lemon","note":"chopped parsley, for serving"}]}'::jsonb),
('www-recipetineats-com-shepherds-pie', 'Shepherd''s Pie', 'British', 'RecipeTin Eats', 'https://www.recipetineats.com/shepherds-pie/', 80, 6, 4, 3, 2, 18, 71, array['lamb', 'potatoes', 'onion', 'carrots', 'peas', 'broth', 'butter']::text[], '{"title":"Shepherd''s Pie","cuisine":"British","source":"RecipeTin Eats","url":"https://www.recipetineats.com/shepherds-pie/","minutes":80,"servings":6,"key":["Ground lamb","Potatoes","Onion","Carrots","Frozen peas","Beef stock","Butter"],"minor":["Garlic","Celery","Dried thyme","Dried rosemary","Flour","Tomato paste","Red wine","Beef bouillon cube","Worcestershire sauce","Bay leaves","Milk","Parmesan","Olive oil"],"amounts":{"Ground lamb":"750g ground lamb or beef","Potatoes":"1.2kg, peeled and cubed","Onion":"1, finely chopped","Carrots":"1, finely chopped","Frozen peas":"1 cup","Beef stock":"2 cups","Butter":"2 tbsp for mash, plus 2 tbsp melted for topping"},"steps":[["On a clean cutting board, mince [[2 cloves]] garlic and finely chop [[1]] onion, [[1]] carrot and [[1 rib]] celery.",null],["Peel [[1.2 kg]] potatoes and cut them into 2.5cm/1\" cubes. Melt [[2 tbsp]] butter for the topping and set aside.",null],["Heat [[1.5 tbsp]] olive oil in a large skillet over medium high heat. Add the onion and garlic and cook for 1 minute.",1],["Add the carrot, celery, [[0.75 tsp]] dried thyme and [[0.75 tsp]] dried rosemary. Cook for 3 minutes until softened and sweet.",3],["Turn the heat to high. Add [[750 g]] ground lamb (or beef) and break it up as it cooks, until browned.",null],["Add [[0.25 cup]] flour and mix it in.",null],["Add [[0.25 cup]] tomato paste, [[2 cups]] beef stock, [[0.5 cup]] red wine, [[1]] crumbled bouillon cube, [[1 tbsp]] Worcestershire sauce and [[2]] bay leaves. Stir well.",null],["Bring to a simmer, then turn the heat to medium for a rapid simmer. Cook for 30 minutes, stirring occasionally, until reduced to a thick gravy.",30],["Add [[0.75 tsp]] salt and [[0.5 tsp]] black pepper; taste and adjust. Transfer the filling to a 1.5 litre/1.5 quart pie baking dish and stir through [[1 cup]] frozen peas.",null],["Optional: cover and refrigerate the filling for 1-2 hours or overnight.",null],["Preheat the oven to 350°F (180°C), fan or standard.",null],["Put the potatoes in a large pot and add water to 10cm/4\" above them. Bring to a boil and cook for 15 minutes until soft.",15],["Drain, then return the potatoes to the pot on the turned-off stove and let them steam dry for 30 seconds.",0.5],["Add [[2 tbsp]] butter and mash until melted. Add [[0.667 cup]] milk, salt and pepper and mash until soft, smooth and spreadable (not sloppy), adding more milk if needed.",null],["Spread the mash over the filling in the pie dish and use a fork to draw squiggles over the surface.",null],["Sprinkle with [[2 tbsp]] to [[3 tbsp]] grated parmesan (optional) and drizzle with the melted butter.",null],["Bake for 30-40 minutes until deep golden on top and bubbling at the edges. Insert a knife in the middle to make sure it''s piping hot.",30],["Let it stand for 5 minutes before serving, and garnish with fresh thyme if you like.",5]],"technique":4,"prep":3,"precision":2,"nutrition":{"calories":653,"protein_g":31,"carbs_g":14,"fat_g":50},"video":null,"country":"GB","effort_steps":7,"ingredients":[{"item":"olive oil","qty":1.5,"unit":"tbsp","group":"Filling"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Filling"},{"item":"onion","qty":1,"note":"finely chopped","group":"Filling"},{"item":"carrot","qty":1,"note":"finely chopped","group":"Filling"},{"item":"celery","qty":1,"unit":"rib","note":"finely chopped","group":"Filling"},{"item":"dried thyme","qty":0.75,"unit":"tsp","note":"or 2 sprigs fresh thyme","group":"Filling"},{"item":"dried rosemary","qty":0.75,"unit":"tsp","note":"or 1 sprig fresh rosemary","group":"Filling"},{"item":"ground lamb (mince) or beef","qty":750,"unit":"g","note":"1.5 lb","group":"Filling"},{"item":"flour, plain/all purpose","qty":0.25,"unit":"cup","group":"Filling"},{"item":"tomato paste","qty":0.25,"unit":"cup","group":"Filling"},{"item":"beef stock/broth","qty":2,"unit":"cup","group":"Filling"},{"item":"red wine (or water)","qty":0.5,"unit":"cup","group":"Filling"},{"item":"beef bouillon cube","qty":1,"note":"crumbled","group":"Filling"},{"item":"Worcestershire sauce","qty":1,"unit":"tbsp","group":"Filling"},{"item":"bay leaves","qty":2,"note":"dried or fresh","group":"Filling"},{"item":"cooking salt/kosher salt","qty":0.75,"unit":"tsp","group":"Filling"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Filling"},{"item":"frozen peas","qty":1,"unit":"cup","group":"Filling"},{"item":"potatoes","qty":1.2,"unit":"kg","note":"2.2 lb; peeled and cut into 2.5cm/1\" cubes","group":"Mashed Potato"},{"item":"milk (whole or low fat)","qty":0.667,"unit":"cup","group":"Mashed Potato"},{"item":"unsalted butter","qty":2,"unit":"tbsp","note":"30 g","group":"Mashed Potato"},{"item":"parmesan","qty":2,"qtyMax":3,"unit":"tbsp","note":"grated, optional","group":"Cheesy Crust"},{"item":"unsalted butter","qty":2,"unit":"tbsp","note":"30 g, melted","group":"Cheesy Crust"},{"item":"fresh thyme leaves","note":"optional garnish","group":"Cheesy Crust"}]}'::jsonb),
('www-recipetineats-com-toad-in-the-hole', 'Toad in the Hole', 'British', 'RecipeTin Eats', 'https://www.recipetineats.com/toad-in-the-hole/', 55, 4, 5, 2, 4, 15, 70, array['sausage', 'eggs', 'flour', 'milk', 'onion', 'broth']::text[], '{"title":"Toad in the Hole","cuisine":"British","source":"RecipeTin Eats","url":"https://www.recipetineats.com/toad-in-the-hole/","minutes":55,"servings":4,"key":["Pork sausages","Eggs","Flour","Milk","Onion","Beef stock"],"minor":["Beef drippings or canola oil","Mayonnaise","White pepper","Garlic","Worcestershire sauce","Butter","Black pepper"],"amounts":{"Pork sausages":"700g (8 x 85g)","Eggs":"250ml whisked (4-5 large)","Flour":"1 cup plain flour, plus 3 tbsp for gravy","Milk":"3/4 cup full-fat","Onion":"2, cut into wedges","Beef stock":"2 cups low-sodium"},"steps":[["On a clean cutting board, halve [[2]] onions and cut them into 7 mm / 1/4\" wedges, and finely mince [[1 clove]] garlic. Set aside for the gravy.",null],["For the batter, whisk [[250 ml]] eggs in a bowl, then whisk in [[1 cup]] plain flour until there are no lumps.",null],["Whisk [[0.25 cup]] water, [[0.75 cup]] milk, [[1 tbsp]] mayonnaise, [[0.5 tsp]] salt and a [[1 pinch]] of white pepper into the same bowl. Put the batter in the fridge until needed.",null],["Preheat the oven to 425°F (220°C, or 200°C fan).",null],["Put [[50 g]] beef drippings (or oil) in a 9 x 13\" (23 x 33cm) metal pan and place it in the oven for 15 minutes to melt and get very hot.",15],["Meanwhile, heat [[2 tsp]] drippings (or oil) in a frying pan over medium high heat. Brown [[700 g]] sausages all over, but keep one side only lightly browned and keep them raw inside. Move them onto a plate, and keep the frying pan for the gravy.",null],["Take the batter out of the fridge and whisk it again. Working quickly, take the hot metal pan out of the oven.",null],["Spread the sausages in the hot pan, lightly browned side up, keeping them clear of the pan walls. Pour the batter in around the sausages.",null],["Bake on the top shelf for 25 minutes, until the sides puff up and are golden brown with crispy edges.",25],["For the gravy, add [[2 tbsp]] beef drippings (or butter) to the frying pan you used for the sausages and melt over high heat.",null],["Add the onions and cook, stirring constantly, until nicely browned, about 5 minutes.",5],["Add the garlic and stir for 30 seconds. Add [[3 tbsp]] plain flour and stir for 1 minute so it mixes through the onions.",1],["Slowly pour in [[2 cups]] beef stock, stirring as you go. Add [[0.5 tsp]] Worcestershire sauce, [[0.25 tsp]] salt and [[0.5 tsp]] black pepper.",null],["Bring to a simmer, stirring, for 2 minutes until it thickens into a gravy. Keep warm until ready to use.",2],["Serve the toad in the hole immediately with the onion gravy. Expect it to deflate a little.",null]],"technique":5,"prep":2,"precision":4,"nutrition":{"calories":1017,"protein_g":41,"carbs_g":36,"fat_g":78},"video":null,"country":"GB","effort_steps":6,"ingredients":[{"item":"pork sausages, or other sausage","qty":700,"unit":"g","note":"1.4 lb (8 x 85g/3oz)"},{"item":"beef drippings OR canola/veg oil","qty":2,"unit":"tsp","note":"10 g"},{"item":"eggs","qty":250,"unit":"ml","note":"1 cup, lightly whisked (4-5 large eggs)","group":"Yorkshire Pudding Batter"},{"item":"plain flour (all-purpose flour)","qty":1,"unit":"cup","group":"Yorkshire Pudding Batter"},{"item":"milk","qty":0.75,"unit":"cup","note":"full fat","group":"Yorkshire Pudding Batter"},{"item":"water","qty":0.25,"unit":"cup","group":"Yorkshire Pudding Batter"},{"item":"mayonnaise","qty":1,"unit":"tbsp","note":"full-fat","group":"Yorkshire Pudding Batter"},{"item":"cooking salt (kosher salt)","qty":0.5,"unit":"tsp","group":"Yorkshire Pudding Batter"},{"item":"white pepper","qty":1,"unit":"pinch","group":"Yorkshire Pudding Batter"},{"item":"beef drippings OR canola/veg oil","qty":50,"unit":"g","note":"1/4 cup","group":"Yorkshire Pudding Batter"},{"item":"beef drippings OR unsalted butter","qty":2,"unit":"tbsp","note":"30 g","group":"Onion Gravy"},{"item":"onions","qty":2,"note":"halved, cut into 7 mm / 1/4\" wedges","group":"Onion Gravy"},{"item":"garlic","qty":1,"unit":"clove","note":"finely minced","group":"Onion Gravy"},{"item":"plain flour (all-purpose flour)","qty":3,"unit":"tbsp","group":"Onion Gravy"},{"item":"beef stock (broth)","qty":2,"unit":"cup","note":"low sodium","group":"Onion Gravy"},{"item":"Worcestershire sauce","qty":0.5,"unit":"tsp","group":"Onion Gravy"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Onion Gravy"},{"item":"cooking salt (kosher salt)","qty":0.25,"unit":"tsp","group":"Onion Gravy"}]}'::jsonb),
('www-spendwithpennies-com-hamburger-soup', 'Easy Hamburger Soup', 'American', 'Spend With Pennies', 'https://www.spendwithpennies.com/hamburger-soup/', 35, 8, 2, 2, 1, 9, 39, array['beef', 'potatoes', 'onion', 'tomatoes', 'broth', 'mixed vegetable', 'garlic']::text[], '{"title":"Easy Hamburger Soup","cuisine":"American","source":"Spend With Pennies","url":"https://www.spendwithpennies.com/hamburger-soup/","minutes":35,"servings":8,"key":["Ground beef","Potatoes","Onion","Canned tomatoes","Beef broth","Frozen mixed vegetables","Garlic"],"minor":["Condensed tomato soup","Worcestershire sauce","Italian seasoning","Bay leaf","Salt","Black pepper"],"amounts":{"Ground beef":"1 pound lean","Potatoes":"2 medium, peeled and diced","Onion":"1, diced","Canned tomatoes":"28 ounces diced, with juices","Beef broth":"3½ cups","Frozen mixed vegetables":"3 cups","Garlic":"2 cloves, minced"},"steps":[["On a clean cutting board, dice [[1]] onion and mince [[2 cloves]] garlic.",null],["Peel [[2 medium]] potatoes and dice them into small pieces. Set them aside in a bowl.",null],["In a pot, cook [[1 lb]] lean ground beef with the diced onion and minced garlic, breaking up the meat, until no pink remains.",null],["Carefully drain any fat out of the pot.",null],["Add the diced potatoes, [[3.5 cups]] beef broth, [[28 oz]] canned diced tomatoes with their juices and [[10.75 oz]] condensed tomato soup to the pot.",null],["Stir in [[2 tsp]] Worcestershire sauce, [[1 tsp]] Italian seasoning and [[1]] bay leaf.",null],["Cover the pot and let it simmer for 10 minutes.",10],["Stir in [[3 cups]] frozen mixed vegetables. Simmer 15-20 minutes, until the potatoes are tender.",15],["Taste the soup and season with salt and black pepper to taste.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":245,"protein_g":16,"carbs_g":25,"fat_g":9},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"lean ground beef","qty":1,"unit":"lb"},{"item":"onion","qty":1,"note":"diced"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"potatoes","qty":2,"unit":"medium","note":"peeled and diced"},{"item":"beef broth","qty":3.5,"unit":"cup"},{"item":"canned diced tomatoes","qty":28,"unit":"oz","note":"with juices, 1 can"},{"item":"condensed tomato soup","qty":10.75,"unit":"oz","note":"1 can"},{"item":"Worcestershire sauce","qty":2,"unit":"tsp"},{"item":"Italian seasoning","qty":1,"unit":"tsp"},{"item":"bay leaf","qty":1},{"item":"salt and black pepper","note":"to taste"},{"item":"frozen mixed vegetables","qty":3,"unit":"cup","note":"or fresh chopped vegetables"}]}'::jsonb),
('www-budgetbytes-com-extra-cheesy-homemade-mac-and-cheese', 'Homemade Mac and Cheese', 'American', 'Budget Bytes', 'https://www.budgetbytes.com/extra-cheesy-homemade-mac-and-cheese/', 25, 4, 4, 1, 3, 9, 51, array['pasta', 'cheddar', 'milk', 'butter', 'flour']::text[], '{"title":"Homemade Mac and Cheese","cuisine":"American","source":"Budget Bytes","url":"https://www.budgetbytes.com/extra-cheesy-homemade-mac-and-cheese/","minutes":25,"servings":4,"key":["Pasta","Cheddar","Milk","Butter","Flour"],"minor":["Onion powder","Garlic powder","Paprika","Hot sauce","Salt","Black pepper"],"amounts":{"Pasta":"8 oz macaroni","Cheddar":"2½ cups sharp, shredded (280g)","Milk":"2 cups whole","Butter":"3 Tbsp","Flour":"3 Tbsp all-purpose (30g)"},"steps":[["Shred [[2.5 cups]] sharp cheddar cheese and set it aside so it''s ready to go.",null],["Cook [[8 oz]] macaroni according to the package directions, about 7-8 minutes, until tender.",7],["Drain the macaroni in a colander and set it aside.",null],["Put [[3 tbsp]] butter and [[3 tbsp]] all-purpose flour in a medium pot over medium heat. Whisk until melted and bubbling, then keep cooking for 1 minute.",1],["Slowly whisk [[2 cups]] whole milk into the same pot a few tablespoons at a time, letting each addition thicken before adding more.",null],["Keep cooking and whisking over medium heat until the milk gently simmers and thickens to the consistency of heavy cream, about 5 minutes.",5],["Turn off the heat. Whisk in [[0.5 tsp]] onion powder, [[0.5 tsp]] garlic powder, [[0.5 tsp]] paprika, [[0.75 tsp]] salt, [[0.25 tsp]] black pepper and [[0.5 tsp]] hot sauce.",null],["Add the shredded cheddar one handful at a time, whisking until each handful melts before adding more. Don''t let it boil, or the sauce can turn grainy.",null],["Add the cooked macaroni to the pot of cheese sauce and stir to combine. Serve hot.",null]],"technique":4,"prep":1,"precision":3,"nutrition":{"calories":670,"protein_g":29,"carbs_g":55,"fat_g":37},"video":"https://www.youtube.com/embed/SI4NEdnmL_g","country":"US","effort_steps":6,"ingredients":[{"item":"macaroni","qty":8,"unit":"oz","note":"uncooked (230 g)"},{"item":"butter","qty":3,"unit":"tbsp"},{"item":"all-purpose flour","qty":3,"unit":"tbsp","note":"30g"},{"item":"whole milk","qty":2,"unit":"cup","note":"500 ml"},{"item":"onion powder","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.5,"unit":"tsp"},{"item":"paprika","qty":0.5,"unit":"tsp"},{"item":"salt","qty":0.75,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"freshly cracked"},{"item":"hot sauce","qty":0.5,"unit":"tsp"},{"item":"sharp cheddar cheese","qty":2.5,"unit":"cup","note":"shredded (280 g)"}]}'::jsonb),
('www-spendwithpennies-com-chicken-rice-soup', 'Chicken and Rice Soup', 'American', 'Spend With Pennies', 'https://www.spendwithpennies.com/chicken-rice-soup/', 45, 6, 1, 2, 2, 9, 37, array['chicken', 'rice', 'carrots', 'onion', 'broth', 'celery', 'garlic']::text[], '{"title":"Chicken and Rice Soup","cuisine":"American","source":"Spend With Pennies","url":"https://www.spendwithpennies.com/chicken-rice-soup/","minutes":45,"servings":6,"key":["Chicken breast","Rice","Carrots","Onion","Chicken broth","Celery","Garlic"],"minor":["Dried parsley","Dried thyme","Evaporated milk or cream (optional)","Salt","Black pepper"],"amounts":{"Chicken breast":"2 boneless skinless, uncooked","Rice":"1 cup brown rice","Carrots":"3 large, diced","Onion":"1, diced","Chicken broth":"5 cups reduced sodium","Celery":"1 rib, diced","Garlic":"1 clove, minced"},"steps":[["On a clean cutting board, dice [[1]] onion. Peel and dice [[3 large]] carrots, and dice [[1 rib]] celery.",null],["Mince [[1 clove]] garlic and set it aside.",null],["In a large pot, heat [[1 tbsp]] olive oil over medium-high heat.",null],["Add the onion, carrots and celery to the pot and cook for 3-4 minutes, until the onion is translucent.",3],["Add the garlic, [[1 tsp]] dried parsley and [[0.5 tsp]] dried thyme leaves and cook 1 minute.",1],["Add [[5 cups]] reduced sodium chicken broth, [[2]] whole uncooked chicken breasts, [[1 cup]] brown rice, [[1 tsp]] salt and [[0.25 tsp]] black pepper. Stir and bring to a boil over medium-high heat.",null],["Reduce the heat to medium-low and cover the pot. Simmer for 30 minutes, until the vegetables and rice are tender and the chicken has reached 165°F.",30],["Lift the chicken out of the pot onto a clean cutting board and shred it.",null],["Add the shredded chicken back to the pot, along with [[1 cup]] evaporated milk or cream if using.",null]],"technique":1,"prep":2,"precision":2,"nutrition":{"calories":332,"protein_g":25,"carbs_g":35,"fat_g":9},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"onion","qty":1,"note":"diced"},{"item":"carrots","qty":3,"unit":"large","note":"peeled and diced"},{"item":"celery","qty":1,"unit":"rib","note":"diced"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"dried parsley","qty":1,"unit":"tsp"},{"item":"dried thyme leaves","qty":0.5,"unit":"tsp"},{"item":"reduced sodium chicken broth","qty":5,"unit":"cup"},{"item":"boneless skinless chicken breasts","qty":2,"note":"uncooked"},{"item":"brown rice","qty":1,"unit":"cup"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp"},{"item":"evaporated milk or cream","qty":1,"unit":"cup","note":"optional"}]}'::jsonb),
('www-spendwithpennies-com-lemon-pepper-chicken', 'Lemon Pepper Chicken', 'American', 'Spend With Pennies', 'https://www.spendwithpennies.com/lemon-pepper-chicken/', 50, 4, 3, 2, 3, 15, 55, array['chicken', 'lemon', 'flour', 'zucchini', 'scallions', 'broth']::text[], '{"title":"Lemon Pepper Chicken","cuisine":"American","source":"Spend With Pennies","url":"https://www.spendwithpennies.com/lemon-pepper-chicken/","minutes":50,"servings":4,"key":["Chicken breast","Lemon","Flour","Zucchini","Green onions","Chicken broth"],"minor":["Lemon pepper seasoning","White wine","Garlic powder","Black pepper","Fresh parsley"],"amounts":{"Chicken breast":"4 boneless skinless","Lemon":"1 small, juiced","Flour":"⅓ cup + 1 tbsp all-purpose","Zucchini":"1 medium, sliced","Green onions":"6, thinly sliced","Chicken broth":"½ cup chicken stock"},"steps":[["Preheat the oven to 350°F.",null],["On a clean cutting board, thinly slice [[6]] green onions and slice [[1 medium]] zucchini. Juice [[1 small]] lemon.",null],["In a bowl, combine the zucchini, [[1 tsp]] lemon pepper seasoning and the green onions.",null],["In an ovenproof skillet, heat [[1 tbsp]] olive oil over medium-high heat. Add the zucchini mixture and cook for 2-3 minutes, until slightly softened.",2],["Transfer the zucchini to a 2-quart casserole dish or Dutch oven.",null],["In a shallow bowl, combine [[0.333 cup]] all-purpose flour and [[1.5 tsp]] lemon pepper seasoning.",null],["Dip [[4]] chicken breasts in the flour mixture and shake off the extra. Save the leftover flour mixture for the sauce.",null],["Add the remaining [[2 tbsp]] olive oil to the same skillet. Brown the chicken over medium-high heat until golden, about 3 minutes per side.",3],["Place the browned chicken on top of the zucchini in the casserole dish.",null],["In a jar, put [[0.5 cup]] chicken stock, [[0.25 cup]] white wine, the lemon juice, [[1 tbsp]] of the leftover flour mixture and [[0.5 tsp]] garlic powder. Close it and shake well to combine.",null],["Pour the jar mixture into the warm skillet while whisking and bring to a boil. Simmer 1 minute, whisking and scraping up any brown bits in the pan.",1],["Season the sauce with salt and [[0.5 tsp]] black pepper to taste, then spoon it over the chicken.",null],["Cover the dish and bake for 20 minutes.",20],["Remove the cover and bake 10-15 minutes more, until the chicken reaches 165°F.",10],["Garnish with chopped fresh parsley.",null]],"technique":3,"prep":2,"precision":3,"nutrition":{"calories":435,"protein_g":51,"carbs_g":14,"fat_g":17},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"olive oil","qty":3,"unit":"tbsp","note":"divided"},{"item":"lemon pepper seasoning","qty":2.5,"unit":"tsp","note":"divided"},{"item":"green onions","qty":6,"note":"thinly sliced"},{"item":"zucchini","qty":1,"unit":"medium","note":"sliced (or 8 oz mushrooms)"},{"item":"all-purpose flour","qty":0.333,"unit":"cup"},{"item":"boneless skinless chicken breasts","qty":4},{"item":"chicken stock","qty":0.5,"unit":"cup","group":"Sauce"},{"item":"white wine","qty":0.25,"unit":"cup","group":"Sauce"},{"item":"lemon","qty":1,"unit":"small","note":"juiced","group":"Sauce"},{"item":"all-purpose flour","qty":1,"unit":"tbsp","group":"Sauce"},{"item":"garlic powder","qty":0.5,"unit":"tsp","group":"Sauce"},{"item":"black pepper","qty":0.5,"unit":"tsp","group":"Sauce"},{"item":"fresh parsley","note":"chopped, for garnish","group":"Sauce"}]}'::jsonb),
('www-spendwithpennies-com-cheesy-potato-soup', 'Cheesy Potato Soup', 'American', 'Spend With Pennies', 'https://www.spendwithpennies.com/cheesy-potato-soup/', 30, 4, 4, 2, 3, 12, 56, array['potatoes', 'broth', 'cheddar', 'milk', 'cream cheese', 'butter', 'flour']::text[], '{"title":"Cheesy Potato Soup","cuisine":"American","source":"Spend With Pennies","url":"https://www.spendwithpennies.com/cheesy-potato-soup/","minutes":30,"servings":4,"key":["Potatoes","Chicken broth","Cheddar","Milk","Cream cheese","Butter","Flour"],"minor":["Gruyere","Garlic","Onion powder","Dry mustard powder","Salt","Black pepper"],"amounts":{"Potatoes":"1 lb baking potatoes, cut into 2\" pieces","Chicken broth":"3 cups","Cheddar":"1 cup shredded","Milk":"1 cup","Cream cheese":"4 oz, softened","Butter":"1 tbsp","Flour":"1 tbsp all-purpose"},"steps":[["On a clean cutting board, peel [[1 lb]] baking potatoes and cut them into 2-inch pieces.",null],["Mince [[2 cloves]] garlic, and cut [[4 oz]] softened cream cheese into small cubes.",null],["In a medium pot, mix [[3 cups]] chicken broth, [[0.25 tsp]] black pepper and [[0.5 tsp]] dry mustard powder, and bring it to a boil.",null],["Add the potatoes and reduce the heat to a simmer. Cook for 15 minutes, until the potatoes are fork-tender.",15],["Mash the potatoes slightly right in the pot using a hand masher.",null],["In a separate medium saucepan, melt [[1 tbsp]] butter with the garlic over medium heat just until fragrant.",null],["Stir [[1 tbsp]] all-purpose flour into the saucepan and cook for 1 minute more.",1],["Gradually add [[1 cup]] milk to the saucepan, stirring after each addition, until smooth. Bring it to a boil over medium heat and cook until thick and bubbly.",null],["Stir the cream cheese and [[0.5 tsp]] onion powder into the saucepan and whisk until smooth.",null],["Turn off the heat and add [[1 cup]] shredded cheddar and [[0.5 cup]] shredded Gruyere. Stir until the cheese is melted.",null],["Add the smashed potatoes to the cheese mixture, then add the potato broth until it''s as thick as you like. Use a little less broth for a thicker soup.",null],["Simmer for 1 minute to combine. Taste and season with [[0.25 tsp]] salt and more pepper if needed.",1]],"technique":4,"prep":2,"precision":3,"nutrition":{"calories":494,"protein_g":23,"carbs_g":33,"fat_g":30},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"chicken broth or stock","qty":3,"unit":"cup","note":"not reduced sodium","group":"Main"},{"item":"onion powder","qty":0.5,"unit":"tsp","group":"Main"},{"item":"dry mustard powder","qty":0.5,"unit":"tsp","group":"Main"},{"item":"baking potatoes","qty":1,"unit":"lb","note":"peeled, cut into 2\" pieces","group":"Main"},{"item":"butter","qty":1,"unit":"tbsp","group":"Cheese Base"},{"item":"garlic","qty":2,"unit":"clove","note":"minced","group":"Cheese Base"},{"item":"all-purpose flour","qty":1,"unit":"tbsp","group":"Cheese Base"},{"item":"milk","qty":1,"unit":"cup","group":"Cheese Base"},{"item":"cream cheese","qty":4,"unit":"oz","note":"softened and cut into small cubes","group":"Cheese Base"},{"item":"shredded cheddar cheese","qty":1,"unit":"cup","group":"Cheese Base"},{"item":"shredded Gruyere cheese","qty":0.5,"unit":"cup","group":"Cheese Base"},{"item":"salt","qty":0.25,"unit":"tsp","group":"Cheese Base"},{"item":"black pepper","qty":0.25,"unit":"tsp","group":"Cheese Base"}]}'::jsonb),
('www-budgetbytes-com-hearty-black-bean-quesadillas', 'Hearty Black Bean Quesadillas', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/hearty-black-bean-quesadillas/', 15, 10, 2, 2, 1, 8, 32, array['tortillas', 'black beans', 'cheddar', 'corn', 'onion', 'garlic']::text[], '{"title":"Hearty Black Bean Quesadillas","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/hearty-black-bean-quesadillas/","minutes":15,"servings":10,"key":["Tortillas","Black beans","Cheddar","Frozen corn","Red onion","Garlic"],"minor":["Taco seasoning","Fresh cilantro","Sour cream or salsa (to serve)"],"amounts":{"Tortillas":"10 flour (7-inch)","Black beans":"1 (15 oz) can, drained","Cheddar":"2 cups shredded","Frozen corn":"1 cup","Red onion":"½ cup, finely diced","Garlic":"1 clove, minced"},"steps":[["Drain [[1 can (15 oz)]] black beans and add them to a bowl with [[1 cup]] frozen corn (no need to thaw).",null],["On a clean cutting board, finely dice [[0.5 cup]] red onion, mince [[1 clove]] garlic and roughly chop [[0.25 bunch]] fresh cilantro.",null],["Add the onion, garlic, cilantro, [[2 cups]] shredded cheddar and [[1 batch]] taco seasoning to the bowl with the beans and corn.",null],["Stir until everything is evenly combined and coated in seasoning.",null],["Place [[0.5 cup]] of the filling on one side of each of the [[10]] tortillas and fold them over.",null],["Cook the quesadillas in a skillet over medium heat on each side until brown and crispy and the cheesy filling has melted.",null],["Slice into triangles and serve.",null],["To freeze: stack the filled, uncooked quesadillas with parchment paper between each, put them in a freezer bag and freeze up to three months. Reheat in the microwave (soft) or in a skillet on low heat.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":289,"protein_g":12,"carbs_g":34,"fat_g":12},"video":"https://www.youtube.com/embed/4AQiIjGnR7A","country":"MX","effort_steps":4,"ingredients":[{"item":"black beans","qty":1,"unit":"can (15 oz)"},{"item":"frozen corn","qty":1,"unit":"cup"},{"item":"red onion","qty":0.5,"unit":"cup"},{"item":"garlic","qty":1,"unit":"clove"},{"item":"fresh cilantro","qty":0.25,"unit":"bunch","note":"about ½ cup chopped"},{"item":"shredded cheddar cheese","qty":2,"unit":"cup"},{"item":"taco seasoning","qty":1,"unit":"batch"},{"item":"flour tortillas","qty":10,"note":"7-inch diameter"}]}'::jsonb),
('www-budgetbytes-com-enfrijoladas-tortillas-in-black-bean-sauce', 'Enfrijoladas – Tortillas in Black Bean Sauce', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/enfrijoladas-tortillas-in-black-bean-sauce/', 35, 4, 2, 3, 2, 13, 46, array['black beans', 'tortillas', 'broth', 'onion', 'cheddar']::text[], '{"title":"Enfrijoladas – Tortillas in Black Bean Sauce","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/enfrijoladas-tortillas-in-black-bean-sauce/","minutes":35,"servings":4,"key":["Black beans","Corn tortillas","Broth","Onion","Cheese"],"minor":["Chipotle peppers in adobo","Ground cumin","Garlic powder","Cilantro","Salt"],"amounts":{"Black beans":"2 (15oz) cans, drained","Corn tortillas":"12","Broth":"2 cups chicken or vegetable","Onion":"1 small sweet onion, divided","Cheese":"4 oz"},"steps":[["On a clean cutting board, dice 1/4 of [[1 small]] sweet onion for the sauce. Keep the rest of the onion for later.",null],["In a blender or food processor, combine [[2 cans (15 oz)]] drained black beans, [[2]] chipotle peppers plus about [[1 tbsp]] of the adobo sauce, the diced onion, [[0.5 tsp]] ground cumin and [[0.25 tsp]] garlic powder.",null],["Start blending with 1 cup of the broth, then keep adding broth (up to [[2 cups]] total) until a smooth, thick sauce forms. Taste and adjust the salt as needed.",null],["Preheat the oven to 350°F.",null],["Warm [[12]] corn tortillas by microwaving the stack for 30 seconds, toasting them in a skillet, or directly on a gas burner until lightly browned. Cover the warm stack with foil.",null],["Finely dice the rest of the sweet onion and roughly chop the leaves from [[0.25 bunch]] cilantro.",null],["In a small bowl, stir the onion and cilantro together with a pinch of salt. Set it aside to marinate.",null],["Spread a small amount of the black bean sauce over the bottom of a casserole dish. Pour more sauce into a wide shallow bowl for dipping.",null],["One at a time, dip each tortilla in the sauce until both sides are coated.",null],["Sprinkle a little of the [[4 oz]] cheese and a little onion-cilantro mix over half of the tortilla. Fold it closed, then fold in half again to make a triangle, and place it in the casserole dish.",null],["Once all the tortillas are in the dish, pour any remaining black bean sauce over the top.",null],["Bake for about 15 minutes, just until heated through.",15],["Top with the remaining cheese and onion-cilantro mix, then serve.",null]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":481,"protein_g":30,"carbs_g":75,"fat_g":10},"video":null,"country":"MX","effort_steps":6,"ingredients":[{"item":"black beans","qty":2,"unit":"can (15 oz)","note":"drained"},{"item":"chipotle peppers in adobo sauce","qty":2,"note":"plus 1 Tbsp sauce"},{"item":"sweet onion","qty":1,"unit":"small","note":"divided"},{"item":"ground cumin","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.25,"unit":"tsp"},{"item":"chicken or vegetable broth","qty":2,"unit":"cup"},{"item":"corn tortillas","qty":12},{"item":"cilantro","qty":0.25,"unit":"bunch"},{"item":"cheese","qty":4,"unit":"oz"}]}'::jsonb),
('www-budgetbytes-com-chipotle-chicken-tacos', 'Chipotle Chicken Tacos', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/chipotle-chicken-tacos/', 50, 6, 2, 2, 2, 12, 47, array['chicken', 'tortillas', 'onion', 'garlic', 'chipotle peppers in adobo']::text[], '{"title":"Chipotle Chicken Tacos","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/chipotle-chicken-tacos/","minutes":50,"servings":6,"key":["Chicken thighs","Corn tortillas","Onion","Garlic","Chipotle peppers in adobo"],"minor":["Bay leaf","Peppercorns","Salt","Pineapple salsa (optional)"],"amounts":{"Chicken thighs":"4 boneless skinless","Corn tortillas":"12 (5-inch)","Onion":"1 yellow, divided","Garlic":"4 cloves, divided","Chipotle peppers in adobo":"2 oz"},"steps":[["Cut [[1]] yellow onion in half. Keep one half whole for cooking the chicken and set the other half aside.",null],["In a pan, add [[4]] chicken thighs, [[2 cloves]] garlic, the onion half, [[1]] bay leaf, [[4]] peppercorns and [[1 tsp]] salt. Add water to cover, about 4 cups.",null],["Place the pan over medium heat, cover it, and cook for 20 minutes, until the chicken is 160°F inside and fork tender.",20],["Lift the chicken out of the pan and save the broth. Shred the chicken with two forks.",null],["On a clean cutting board, dice the remaining onion half and mince the remaining [[2 cloves]] garlic.",null],["Heat [[2 tbsp]] olive oil in a saucepan over medium heat. Add the onion and garlic and cook about 2 minutes, until the onions steam and the garlic is fragrant.",2],["Chop [[2 oz]] chipotle peppers in their sauce and add them to the saucepan. Stir well.",null],["Add the shredded chicken and 1/4 cup of the reserved broth to the saucepan and mix thoroughly. Taste it: add more adobo sauce for more heat, or a touch more broth for saucier chicken.",null],["Once the sauce has thickened to a velvety consistency, take the chicken off the heat.",null],["Optional salsa: finely chop [[2 cups]] pineapple, [[0.25]] red onion, [[1]] jalapeño and [[0.25 bunch]] cilantro.",null],["In a bowl, combine the chopped pineapple, onion, jalapeño and cilantro with the juice of [[1]] lime and [[1 tsp]] salt, or to taste.",null],["Assemble the tacos: add 1/4 cup pulled chicken to each of the [[12]] tortillas and top with pineapple salsa.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":186,"protein_g":9,"carbs_g":14,"fat_g":11},"video":null,"country":"MX","effort_steps":6,"ingredients":[{"item":"boneless skinless chicken thighs","qty":4},{"item":"garlic","qty":4,"unit":"clove","note":"divided"},{"item":"yellow onion","qty":1,"note":"divided"},{"item":"bay leaf","qty":1},{"item":"peppercorns","qty":4},{"item":"salt","qty":1,"unit":"tsp"},{"item":"olive oil","qty":2,"unit":"tbsp"},{"item":"chipotle peppers in adobo","qty":2,"unit":"oz"},{"item":"5-inch corn tortillas or flour tortillas","qty":12},{"item":"chopped pineapple","qty":2,"unit":"cup","note":"fresh or frozen","group":"Pineapple Salsa (optional)"},{"item":"red onion","qty":0.25,"note":"chopped","group":"Pineapple Salsa (optional)"},{"item":"jalapeño","qty":1,"group":"Pineapple Salsa (optional)"},{"item":"lime","qty":1,"group":"Pineapple Salsa (optional)"},{"item":"cilantro","qty":0.25,"unit":"bunch","note":"about ¼ cup","group":"Pineapple Salsa (optional)"},{"item":"salt","qty":1,"unit":"tsp","note":"or to taste","group":"Pineapple Salsa (optional)"}]}'::jsonb),
('www-budgetbytes-com-sopa-de-fideo', 'Simple Sopa de Fideo (Mexican Noodle Soup)', 'Mexican', 'Budget Bytes', 'https://www.budgetbytes.com/sopa-de-fideo/', 40, 6, 2, 1, 2, 11, 41, array['pasta', 'tomatoes', 'broth', 'onion', 'garlic']::text[], '{"title":"Simple Sopa de Fideo (Mexican Noodle Soup)","cuisine":"Mexican","source":"Budget Bytes","url":"https://www.budgetbytes.com/sopa-de-fideo/","minutes":40,"servings":6,"key":["Pasta","Canned tomatoes","Chicken broth","Onion","Garlic"],"minor":["Cumin","Jalapeño (optional)","Lime","Fresh cilantro (optional)","Vegetable oil"],"amounts":{"Pasta":"8 oz vermicelli noodles","Canned tomatoes":"28 oz can whole peeled","Chicken broth":"6 cups","Onion":"1 medium, diced","Garlic":"2 cloves, minced"},"steps":[["On a clean cutting board, small-dice [[1 medium]] onion and mince [[2 cloves]] garlic.",null],["Juice [[1 large]] lime and roughly chop [[0.25 bunch]] fresh cilantro, if using.",null],["Add [[2 tbsp]] vegetable oil to a large soup pot. Break [[8 oz]] vermicelli noodles into 1-2 inch pieces and add them to the pot.",null],["Cook the dry noodles over medium-low heat, stirring constantly, for 3-5 minutes until golden brown and slightly blistered. Toast in batches if needed.",3],["Add the onion, garlic and [[1 tsp]] cumin to the pot with the noodles. Keep cooking and stirring for a few minutes, until the onions soften.",null],["Pour in a little juice from the [[1 can (28 oz)]] whole peeled tomatoes to stop the browning.",null],["Purée the tomatoes and the rest of their juice in a blender or with an immersion blender.",null],["Add the puréed tomatoes and [[6 cups]] chicken broth to the pot.",null],["Add [[1 medium]] whole jalapeño, if using. Cover the pot, turn the heat to medium-high and bring it to a boil.",null],["Simmer for about 15 minutes, until the noodles are tender.",15],["Just before serving, stir in the lime juice and cilantro. Slice the jalapeño to use as a garnish if you like.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":162,"protein_g":5,"carbs_g":38,"fat_g":9},"video":null,"country":"MX","effort_steps":6,"ingredients":[{"item":"vegetable oil","qty":2,"unit":"tbsp"},{"item":"vermicelli noodles","qty":8,"unit":"oz","note":"uncooked"},{"item":"onion","qty":1,"unit":"medium","note":"small dice, about 1 cup, 150g"},{"item":"garlic","qty":2,"unit":"clove","note":"minced, about 1 Tbsp"},{"item":"cumin","qty":1,"unit":"tsp"},{"item":"whole peeled tomatoes","qty":1,"unit":"can (28 oz)"},{"item":"chicken broth","qty":6,"unit":"cup","note":"48 oz"},{"item":"jalapeño","qty":1,"unit":"medium","note":"whole, optional"},{"item":"lime","qty":1,"unit":"large","note":"juiced, about 2 Tbsp of juice"},{"item":"fresh cilantro","qty":0.25,"unit":"bunch","note":"optional"}]}'::jsonb),
('www-budgetbytes-com-pasta-e-fagioli', 'Pasta e Fagioli', 'Italian', 'Budget Bytes', 'https://www.budgetbytes.com/pasta-e-fagioli/', 50, 6, 2, 3, 2, 11, 50, array['pasta', 'white beans', 'tomatoes', 'broth', 'onion', 'carrots', 'bacon']::text[], '{"title":"Pasta e Fagioli","cuisine":"Italian","source":"Budget Bytes","url":"https://www.budgetbytes.com/pasta-e-fagioli/","minutes":50,"servings":6,"key":["Pasta","Cannellini beans","Canned tomatoes","Vegetable broth","Onion","Carrots","Bacon"],"minor":["Celery","Garlic","Dried oregano","Red pepper flakes","Parmesan","Flat-leaf parsley","Olive oil","Salt","Pepper"],"amounts":{"Pasta":"1 cup ditalini, uncooked","Cannellini beans":"1 (15 oz) can, drained and rinsed","Canned tomatoes":"1 (28 oz) can crushed","Vegetable broth":"2 cups","Onion":"1","Carrots":"2","Bacon":"4 oz"},"steps":[["On a clean cutting board, chop [[4 oz]] bacon into smaller pieces.",null],["Add the bacon and [[1 tbsp]] olive oil to a large pot. Fry on medium heat until brown and crispy, around 10 minutes.",10],["While the bacon cooks, finely dice [[1]] onion, [[2]] carrots and [[3 stalks]] celery, and mince [[4 cloves]] garlic. Roughly chop [[0.25 cup]] parsley.",null],["Use a slotted spoon to remove half of the cooked bacon and set it aside. Leave the rest of the bacon and its fat in the pot.",null],["Add the onion, carrots, celery, garlic, [[0.5 tsp]] dried oregano, [[0.25 tsp]] red pepper flakes, [[0.5 tsp]] salt and [[0.5 tsp]] pepper to the pot.",null],["Sauté on medium-high heat until softened, around 6 minutes.",6],["Add [[1 can (15 oz)]] drained and rinsed cannellini beans, [[1 can (28 oz)]] crushed tomatoes with juices, [[1.5 cups]] water and [[2 cups]] vegetable broth. Stir and bring to a boil.",null],["Once boiling, cook for another 5 minutes until the vegetables have softened.",5],["Add [[1 cup]] ditalini to the pot and cook uncovered according to the package directions, stirring often so it doesn''t stick.",null],["Take the pot off the heat and stir in [[0.25 cup]] grated Parmesan and the chopped parsley. If the broth has reduced too much, add another 1/2 cup water and adjust the seasoning.",null],["Serve in bowls topped with the reserved bacon, plus extra parsley, Parmesan, fresh-cracked black pepper and warm, crusty bread if you like.",null]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":248,"protein_g":8,"carbs_g":28,"fat_g":12},"video":null,"country":"IT","effort_steps":6,"ingredients":[{"item":"bacon","qty":4,"unit":"oz"},{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"onion","qty":1},{"item":"carrots","qty":2},{"item":"celery","qty":3,"unit":"stalk"},{"item":"garlic","qty":4,"unit":"clove"},{"item":"dried oregano","qty":0.5,"unit":"tsp"},{"item":"red pepper flakes","qty":0.25,"unit":"tsp"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"pepper","qty":0.5,"unit":"tsp"},{"item":"cannellini beans","qty":1,"unit":"can (15 oz)","note":"drained and rinsed"},{"item":"crushed tomatoes","qty":1,"unit":"can (28 oz)","note":"with juices"},{"item":"water","qty":1.5,"unit":"cup"},{"item":"vegetable broth","qty":2,"unit":"cup"},{"item":"ditalini","qty":1,"unit":"cup","note":"uncooked"},{"item":"grated Parmesan cheese","qty":0.25,"unit":"cup"},{"item":"flat-leaf Italian parsley","qty":0.25,"unit":"cup","note":"roughly chopped"}]}'::jsonb)
